local config = {
  ui_story_5046_50460101_1_dialog_content = "PlayerNameさん！",
  ui_story_5046_50460101_2_dialog_content = "影ノ街孤児院の竣工式にご出席いただけて光栄です。",
  ui_story_5046_50460101_3_dialog_content = "久しぶりだね、ベセル。",
  ui_story_5046_50460101_4_dialog_content = "わざわざシャドウマスターの名前なんて出さなくても、\n呼んでくれれば参加したのに。",
  ui_story_5046_50460101_5_dialog_content = "もう長い付き合いなんだから！",
  ui_story_5046_50460101_6_dialog_content = "あまりにも豪華な招待状で驚いちゃったくらいだよ。",
  ui_story_5046_50460101_7_dialog_content = "正式にご招待するのは当然です。\n知り合いだからといって、礼儀を欠くことは許されません！",
  ui_story_5046_50460101_8_dialog_content = "それに、今回ご招待したお客様の中には白夜城の貴族もたくさんいらっしゃいます。\n特に礼儀を重んじる方々ですからね…",
  ui_story_5046_50460101_9_dialog_content = "もしあなたがシャドウマスターからの招待状を受け取っていないと知ったら、\n何を言われるか分かりません。",
  ui_story_5046_50460101_10_dialog_content = "流言飛語の恐ろしさを見くびってはいけませんよ。",
  ui_story_5046_50460101_11_dialog_content = "た、確かにそうだね…",
  ui_story_5046_50460101_12_dialog_content = "僕も空の末裔は頭が3つで腕が6本、\n鋭い牙と爪をもった化け物だ、なんて言われたことあるけど…",
  ui_story_5046_50460101_13_dialog_content = "何でそうなるんだろう…！？",
  ui_story_5046_50460101_14_dialog_content = "そこまでいくと単なる中傷ですね…\n噂を広めている人たちの責任を問おうと思ったりはしないのですか？",
  ui_story_5046_50460101_15_dialog_content = "…やめてって抗議した以外は、特に何もしてないけど…",
  ui_story_5046_50460101_16_dialog_content = "それはいけませんね。\nPlayerNameさん、あなたは優しすぎます！",
  ui_story_5046_50460101_17_dialog_content = "誹謗中傷には厳しい態度で臨むべきです。\nでなければ、あなたの名誉が大きく傷ついてしまいますよ。",
  ui_story_5046_50460101_18_dialog_content = "世の中には流言に耳を傾けてしまう人が存在しますし、\n誰もが実際に会って分かり合えるわけでもありませんから。",
  ui_story_5046_50460101_19_dialog_content = "そうだね…",
  ui_story_5046_50460101_20_dialog_content = "そういえば、バイスさんとカレンさんは\nご一緒ではないのですか？",
  ui_story_5046_50460101_21_dialog_content = "バイスもカレンも予定があって、\n今日は来られないんだ。",
  ui_story_5046_50460101_22_dialog_content = "お詫びを伝えるように言われてるよ。",
  ui_story_5046_50460101_23_dialog_content = "そうですか。仕方ないことですね。\n残念ではありますが、あなたが来てくだされば十分です。",
  ui_story_5046_50460101_24_dialog_content = "それにしても、どうして僕を招待してくれたの？",
  ui_story_5046_50460101_25_dialog_content = "今まで影ノ街の孤児院には関わってないし、\n僕が出席するのは場違いじゃないかな？",
  ui_story_5046_50460101_26_dialog_content = "ご心配には及びませんよ。",
  ui_story_5046_50460101_27_dialog_content = "竣工式には他にもたくさんの著名人をお招きしているのです。\nご出席いただける方はどなたでも歓迎します。",
  ui_story_5046_50460101_28_dialog_content = "これは援助をいただいた方々に感謝を表すだけでなく、\n世間に孤児院の存在を知ってもらい、寄付を募る機会でもありますから。",
  ui_story_5046_50460101_29_dialog_content = "そんなことまで考えてたんだ。\nさすがベセルだね。",
  ui_story_5046_50460101_30_dialog_content = "とても大切な催しなので、当日何事もなく式が進むよう、\nわざわざ今日のリハーサルを設定しました。",
  ui_story_5046_50460101_31_dialog_content = "当日の流れも分かりますし、PlayerNameさんもご一緒にどうぞ。",
  ui_story_5046_50460101_32_dialog_content = "うん、ありがとう。",
  ui_story_5046_50460101_33_dialog_content = "では、こちらへ。",
  ui_story_5046_50460101_34_dialog_content = "<color=#e8d9bb>影ノ街孤児院竣工式、リハーサル会場</color>",
  ui_story_5046_50460101_35_dialog_content = "ベセル様、会場の警備体制は整っております。",
  ui_story_5046_50460101_36_dialog_content = "分かりました。ありがとうございます。",
  ui_story_5046_50460101_37_dialog_content = "PlayerNameさん、紹介しますね。",
  ui_story_5046_50460101_38_dialog_content = "こちらはリハーサル会場の警備をお任せしているゼナスさんです。\n警備隊の隊長でもあります。",
  ui_story_5046_50460101_39_dialog_content = "お噂はかねがねうかがっておりました。\nお目にかかれて光栄です。",
  ui_story_5046_50460101_40_dialog_content = "かしこまるほどのことはないよ…",
  ui_story_5046_50460101_41_dialog_content = "（服装からして白夜城の人だね…しかも身分が高そうだ…）",
  ui_story_5046_50460101_42_dialog_content = "（そんな人が、どうして警備なんかやってるんだろう？）",
  ui_story_5046_50460101_43_dialog_content = "お隣にいるのは白夜城法廷の見習い裁判官クリステンさんです。\nゼナスさんのお手伝いをされています。",
  ui_story_5046_50460101_44_dialog_content = "こんにちは。クリステンと申します。",
  ui_story_5046_50460101_45_dialog_content = "イルンティ裁判長や先輩方から\nあなたが智略に富み、勇敢な方であることはうかがっております。",
  ui_story_5046_50460101_46_dialog_content = "あはは…なんか照れちゃうな。",
  ui_story_5046_50460101_47_dialog_content = "ハーメル院長！",
  ui_story_5046_50460101_48_dialog_content = "ベセル様！",
  ui_story_5046_50460101_49_dialog_content = "ハーメル院長、今日はリハーサルですよ。なぜ会場へ？",
  ui_story_5046_50460101_50_dialog_content = "家にいても時間を持て余しますのでな。\nだったら見物でも、と思ったのです。",
  ui_story_5046_50460101_51_dialog_content = "シャドウマスターとベセル様には孤児院再建にご協力をいただき、\n心より感謝いたしますぞ。",
  ui_story_5046_50460101_52_dialog_content = "大火事で焼失した孤児院の再建という大事業を先導してくださったのです。\n私の方こそ、子供たちに代わってお礼を申し上げます。",
  ui_story_5046_50460101_53_dialog_content = "ああ、おしゃべりに気をとられて、ご紹介を忘れておりました。\nこちらは空の末裔、PlayerNameさんです。",
  ui_story_5046_50460101_54_dialog_content = "PlayerNameさん、こちらは新たに孤児院の院長となられるハーメル先生です。\n影ノ街でも名の知れた骨董商でもあります。",
  ui_story_5046_50460101_55_dialog_content = "おや、新聞で見るよりお若いですな。\nそれだというのに実に優秀でいらっしゃる。",
  ui_story_5046_50460101_56_dialog_content = "巨像でアストラ大陸のあちこちを旅し、\nあの浮遊商会とも協力関係にあるとか…",
  ui_story_5046_50460101_57_dialog_content = "めったに見られない才能をお持ちだ！",
  ui_story_5046_50460101_58_dialog_content = "い、いろんなの人の手助けがあったから、\nそうなっただけのことです。",
  ui_story_5046_50460101_59_dialog_content = "いやいや、人脈は商いに大切なものの1つですぞ。",
  ui_story_5046_50460101_60_dialog_content = "それだけの人脈を持てるというだけで、\n普通はなかなかできないことです！",
  ui_story_5046_50460101_61_dialog_content = "そのような方とお会いできるとは、\n長生きもしてみるものですな…",
  ui_story_5046_50460101_62_dialog_content = "ほ、褒めすぎですよ…\n僕は本当にすごく平凡なんです…",
  ui_story_5046_50460101_63_dialog_content = "かなりの資産をお持ちとも聞いております。",
  ui_story_5046_50460101_64_dialog_content = "え？…だ、誰に聞いたんですか？",
  ui_story_5046_50460101_65_dialog_content = "あれだけ大きな巨像を維持するには、\n相当な費用がかかるものと思いますが？",
  ui_story_5046_50460101_66_dialog_content = "確かにそうですけど、だからといって、\nお金があるということには…",
  ui_story_5046_50460101_67_dialog_content = "実に謙虚でいらっしゃる！",
  ui_story_5046_50460101_68_dialog_content = "あなたのように人脈も広く、\n控えめな資産家となると、アストラ大陸では非常に珍しい。",
  ui_story_5046_50460101_69_dialog_content = "それに、大変善良な方とお見受けします！",
  ui_story_5046_50460101_70_dialog_content = "いかがでしょう？\n孤児院に長期のご支援をいただくことに、興味はございませんかな？",
  ui_story_5046_50460101_71_dialog_content = "ええと…",
  ui_story_5046_50460101_72_dialog_content = "オホン…",
  ui_story_5046_50460101_73_dialog_content = "ハーメル院長、あまりお客様を困らせないでください。",
  ui_story_5046_50460101_74_dialog_content = "長期的な協力関係は、お互いの信頼の上に打ち立てていきませんと。",
  ui_story_5046_50460101_75_dialog_content = "あはは…そうですな…",
  ui_story_5046_50460101_76_dialog_content = "先走りすぎました、お許しくだされ。",
  ui_story_5046_50460101_77_dialog_content = "いいえ、気にしないでください。\n子どもたちを大事に思う気持ちは、よく分かります。",
  ui_story_5046_50460101_78_dialog_content = "いずれにしても、今日はまだリハーサルですから。\nこの場はご挨拶程度としておきましょう。",
  ui_story_5046_50460101_79_dialog_content = "これからの関係については、\n今後ゆっくりお話しすると言うことで。",
  ui_story_5046_50460101_80_dialog_content = "そうですな。",
  ui_story_5046_50460101_81_dialog_content = "皆さんはゆっくりご歓談ください。\n私は式典当日の細かい流れを確認してまいります。",
  ui_story_5046_50460101_82_dialog_content = "それでは、失礼いたします。",
  ui_story_5046_50460101_83_dialog_content = "ベセル、忙しそうだなぁ。",
  ui_story_5046_50460101_84_dialog_content = "そうだ、ちょっと聞きたいことが…",
  ui_story_5046_50460101_85_option_content = "どうして白夜城の人が影ノ街の警備を担当してるの？",
  ui_story_5046_50460101_86_dialog_content = "ご覧の通り、今回の式典には白夜城でも\n上位の貴族が多数招かれております。",
  ui_story_5046_50460101_87_dialog_content = "しかし、そういった方々は影ノ街の傭兵を信用しておらず…\n白夜城の者に警備させるよう要求したのです。",
  ui_story_5046_50460101_88_dialog_content = "そのうえ、最近影ノ街では放火事件の多発など穏やかでない話もありますし、\nいつも以上に慎重になっているのです。",
  ui_story_5046_50460101_89_dialog_content = "そういったわけで、私が白夜城から遣わされております。\nクリステン様も裁判官見習いとして、警備の補佐に来てくださっています。",
  ui_story_5046_50460101_90_dialog_content = "放火事件？そういえば、影ノ街に着いた時、\n指名手配の張り紙が貼ってあるのを見かけたような。",
  ui_story_5046_50460101_91_dialog_content = "人が多かったから、\n具体的に何が書いてあるのかは分からなかったけど…",
  ui_story_5046_50460101_92_dialog_content = "よく見ていらっしゃいますね。\nちょうど指名手配書を持っております、ご覧になってください。",
  ui_story_5046_50460101_93_dialog_content = "「指名手配」",
  ui_story_5046_50460101_94_dialog_content = "「影ノ街で起こった複数の放火事件の容疑者、\n3人が死亡、負傷者多数」",
  ui_story_5046_50460101_95_dialog_content = "「容疑者に関する手がかりの提供者には、\n懸賞金200000白夜コイン」",
  ui_story_5046_50460101_96_dialog_content = "「容疑者の特徴は以下の通り。\n体格が良く機敏。力が強く、野獣のような凶暴、残酷さ」",
  ui_story_5046_50460101_97_dialog_content = "「コードネームは『黒い凶星』」",
  ui_story_5046_50460101_98_dialog_content = "20万白夜コイン！？そんなに！？\n僕も探してみようかな…",
  ui_story_5046_50460101_99_dialog_content = "…でも「黒い凶星」なんて、いかにも物騒な名前だね。\nやっぱり危険なことはしないでおこう。",
  ui_story_5046_50460101_100_dialog_content = "そもそも指名手配書の似顔絵があいまいすぎて、\n参考にならないし…",
  ui_story_5046_50460101_101_dialog_content = "大変残念ながら、今のところ容疑者の姿を\nはっきりと見た者がいないのです。",
  ui_story_5046_50460101_102_dialog_content = "ただ1件目については、火災発生時に影ノ街の住民が\n現場から立ち去る野獣のような影を見たと証言しています。",
  ui_story_5046_50460101_103_dialog_content = "おそらく亜人族の血を引く者が犯人だと考えられます。",
  ui_story_5046_50460101_104_dialog_content = "似顔絵に似た怪しい者をお見かけになった時は、\n一番に私、もしくはゼナス隊長にお知らせください。",
  ui_story_5046_50460101_105_dialog_content = "ただし、容疑者はそうとう凶暴なようですから、\n賞金目当てに真っ向から戦うようなことはせず、安全第一としてください。",
  ui_story_5046_50460101_106_dialog_content = "わ、分かったよ…",
  ui_story_5046_50460101_107_dialog_content = "他にお聞きになりたいことはございますか？",
  ui_story_5046_50460101_108_option_content = "前の孤児院も火災に遭ったんだよね？",
  ui_story_5046_50460101_109_dialog_content = "以前の孤児院は数年前の失火で全焼してしまいました。\n幸い、子供たちは皆無事でしたがな。",
  ui_story_5046_50460101_110_dialog_content = "情け深いシャドウマスターが居場所を失った子供たちをあわれみ、\nご自身の邸宅に住まわせていたのです。",
  ui_story_5046_50460101_111_dialog_content = "それから数年間、そのような状態でしたが…",
  ui_story_5046_50460101_112_dialog_content = "いつまでも仮家住まいとはいかんでしょう？\nそれに、外にはまだ路頭に迷う子供たちがたくさんおります。",
  ui_story_5046_50460101_113_dialog_content = "ここ数年、骨董の商売で私もいくらか余裕が出来ましたのでな。\n孤児院を再建し、子供たちを引き取ろうと考えたのです。",
  ui_story_5046_50460101_114_dialog_content = "そうすれば、両親を失ったとしても、\n同じ年ごろの子供たちや心優しい大人たちに囲まれて成長できますからな。",
  ui_story_5046_50460101_115_dialog_content = "すごい…優しいんですね。",
  ui_story_5046_50460101_116_dialog_content = "ご立派な志です。",
  ui_story_5046_50460101_117_dialog_content = "子供たちのため、微力ながらできることをしているまでです。",
  ui_story_5046_50460101_118_dialog_content = "新しい孤児院が\n無事に竣工することを願うばかりですな。",
  ui_story_5046_50460101_119_dialog_content = "他にお聞きになりたいことはございますか？",
  ui_story_5046_50460101_120_option_content = "もうないよ",
  ui_story_5046_50460101_121_dialog_content = "先生、そろそろリハーサルのために、\n警備の手はずを整えなければなりません。",
  ui_story_5046_50460101_122_dialog_content = "あ、ごめん！仕事の邪魔しちゃったね。",
  ui_story_5046_50460101_123_dialog_content = "とんでもないことです。\nお客様の安全を守ることが私たちの職務ですから。",
  ui_story_5046_50460101_124_dialog_content = "<color=#e8d9bb>チャリン――</color>",
  ui_story_5046_50460101_125_dialog_content = "あれ？ゼナスさん、何か落としたみたいだよ。",
  ui_story_5046_50460101_126_dialog_content = "（きれいなペンダントだ。可愛い子馬があしらわれてる）",
  ui_story_5046_50460101_127_dialog_content = "はい。",
  ui_story_5046_50460101_128_dialog_content = "ありがとうございます。",
  ui_story_5046_50460101_129_dialog_content = "時間も時間です。\nお嬢様、パトロールを続けることといたしましょう。",
  ui_story_5046_50460101_130_dialog_content = "はい、先生――",
  ui_story_5046_50460101_131_dialog_content = "<color=#e8d9bb>ドカン――！</color>",
  ui_story_5046_50460101_132_dialog_content = "何事ですか！？",
  ui_story_5046_50460101_133_dialog_content = "火事だ！火事だ！",
  ui_story_5046_50460101_134_dialog_content = "どうしていきなり火が！？",
  ui_story_5046_50460101_135_dialog_content = "きっと「黒い凶星」の仕業だ！",
  ui_story_5046_50460101_136_dialog_content = "凶暴で残酷っていう「黒い凶星」がこんな所に！？",
  ui_story_5046_50460101_137_dialog_content = "皆さん、落ち着いてください。\n火の手は孤児院の方向で上がっているようです。",
  ui_story_5046_50460101_138_dialog_content = "お嬢様、見に行きましょう。",
  ui_story_5046_50460101_139_dialog_content = "わかりました！",
  ui_story_5046_50460101_140_dialog_content = "<color=#e8d9bb>現場近く</color>",
  ui_story_5046_50460101_141_dialog_content = "…",
  ui_story_5046_50460201_1_dialog_content = "PlayerName様、ハーメル様。",
  ui_story_5046_50460201_2_dialog_content = "お二人はここにいらしてください。\nまもなく警護の白夜城衛兵がまいります。",
  ui_story_5046_50460201_3_dialog_content = "僕も行くよ！人探しなら、感知能力を使うのが一番早い！",
  ui_story_5046_50460201_4_dialog_content = "私もおともしますぞ。\nしかし、どうして急に火など…？",
  ui_story_5046_50460201_5_dialog_content = "分かりました。時間もありません。\nお二人は安全のため、私の近くから離れないようお願いいたします。",
  ui_story_5046_50460201_6_dialog_content = "ゲホゲホ…煙が濃く、何も見えませんね。\nすぐに火を消さなければ…",
  ui_story_5046_50460201_7_dialog_content = "逆巻く激流よ！",
  ui_story_5046_50460201_8_dialog_content = "お待ちください、お嬢様！",
  ui_story_5046_50460201_9_dialog_content = "<color=#e8d9bb>ドン！！！</color>",
  ui_story_5046_50460201_10_dialog_content = "危ない！",
  ui_story_5046_50460201_11_dialog_content = "あ！先生！？",
  ui_story_5046_50460201_12_dialog_content = "ゴホゴホ…私は大丈夫です。",
  ui_story_5046_50460201_13_dialog_content = "火は地面の油に沿って広がっているようです。\nこの種の油は水に浮いて燃え続けますので、水では消せません。",
  ui_story_5046_50460201_14_dialog_content = "申し訳ございません。また先生におケガを…",
  ui_story_5046_50460201_15_dialog_content = "今はそのような話をする時ではありません。",
  ui_story_5046_50460201_16_dialog_content = "PlayerName様、感知能力で閉じ込められた人はいないか、\nもしくは「黒い凶星」の痕跡はないか調べていただけますか？",
  ui_story_5046_50460201_17_dialog_content = "分かった！",
  ui_story_5046_50460201_18_option_content = "強制感知！",
  ui_story_5046_50460201_19_dialog_content = "うう…た、たすけて…",
  ui_story_5046_50460201_20_dialog_content = "子どもが1人取り残されてる！\nこっちだよ！",
  ui_story_5046_50460201_21_dialog_content = "…",
  ui_story_5046_50460201_22_dialog_content = "母さん…",
  ui_story_5046_50460201_23_dialog_content = "ゴホッ、ゴホゴホ！の、のどが…いたいよぉ…",
  ui_story_5046_50460201_24_dialog_content = "だいぶ弱ってるみたいだ！早く助け出さないと！",
  ui_story_5046_50460201_25_dialog_content = "PlayerNameさん！\n煙が濃すぎてどこにいらっしゃるのか分かりません！",
  ui_story_5046_50460201_26_dialog_content = "行ってはなりません！\n火の勢いが激しすぎます、危険です！",
  ui_story_5046_50460201_27_dialog_content = "怖がらないで、助けにきたよ！",
  ui_story_5046_50460201_28_dialog_content = "ゴホッ、ゴホゴホ！こ…ここだよ…",
  ui_story_5046_50460201_29_dialog_content = "<color=#e8d9bb>ボン！</color>",
  ui_story_5046_50460201_30_dialog_content = "大変だ！火が大きくなってる！\n建物が今にも崩れそうだ！",
  ui_story_5046_50460201_31_dialog_content = "出口を探さないと…でも煙が濃すぎて何も見えない！",
  ui_story_5046_50460201_32_dialog_content = "うううっ…こわいよ…",
  ui_story_5046_50460201_33_dialog_content = "大丈夫だよ。絶対に出口を見つけるから！",
  ui_story_5046_50460201_34_dialog_content = "<color=#e8d9bb>ガラガラ…</color>",
  ui_story_5046_50460201_35_dialog_content = "屋根が崩れる…！",
  ui_story_5046_50460201_36_dialog_content = "きゃあああああ！",
  ui_story_5046_50460201_37_dialog_content = "目を開けな。まだ死んじゃいないよ。",
  ui_story_5046_50460201_38_dialog_content = "誰…？",
  ui_story_5046_50460201_39_dialog_content = "まだ生きてるんだ、さっさとここを離れな。",
  ui_story_5046_50460201_40_dialog_content = "ワンちゃん！ゴホッ…ゴホゴホ！",
  ui_story_5046_50460201_41_dialog_content = "ワンちゃんが助けてくれた！",
  ui_story_5046_50460201_42_dialog_content = "え、兄（あん）ちゃん…？",
  ui_story_5046_50460201_43_dialog_content = "いや…見た目は男っぽいけど、女の子だよね…",
  ui_story_5046_50460201_44_dialog_content = "ワンちゃん！…ゴホッ…ワンちゃんだよ！\nモコモコしたかわいいワンちゃん！",
  ui_story_5046_50460201_45_dialog_content = "な、なんか…ゴホゴホ…おとぎ話みたいな…",
  ui_story_5046_50460201_46_dialog_content = "そっけないけど、とってもやさしい…ゴホゴホ！\nそういうワンちゃん！",
  ui_story_5046_50460201_47_dialog_content = "いつまでおしゃべりしてんだ？\n焼け死にたいなら、ボクはもう行くよ。",
  ui_story_5046_50460201_48_dialog_content = "君、火の中でもなんともないの？",
  ui_story_5046_50460201_49_dialog_content = "この程度の火、なんともないさ。",
  ui_story_5046_50460201_50_dialog_content = "ま、待って！どこかで見たことあるような…",
  ui_story_5046_50460201_51_dialog_content = "あ！き、君は…「黒い凶星」だね！？",
  ui_story_5046_50460201_52_dialog_content = "「黒い凶星」？人違いだろ？",
  ui_story_5046_50460201_53_dialog_content = "ボクの名前は、ハーティだ。",
  ui_story_5046_50460201_54_dialog_content = "そんなに怯えるぐらいなら、手を放せよ。",
  ui_story_5046_50460201_55_dialog_content = "PlayerName様！どちらですか！？",
  ui_story_5046_50460201_56_dialog_content = "ゴホッ…オホン！\n外側の火は連れて来た者たちで大方消しましたぞ！",
  ui_story_5046_50460201_57_dialog_content = "PlayerNameさんのそばにもう1人いらっしゃいます！",
  ui_story_5046_50460201_58_dialog_content = "いや、その姿は…「黒い凶星」！？",
  ui_story_5046_50460201_59_dialog_content = "「黒い凶星」だと！？",
  ui_story_5046_50460201_60_dialog_content = "連続放火事件の容疑者「黒い凶星」！\n直ちに人質を解放しなさい！",
  ui_story_5046_50460201_61_dialog_content = "言っただろ。「黒い凶星」じゃない、ハーティだ。",
  ui_story_5046_50460201_62_dialog_content = "それと「人質」って、なんのことだ？",
  ui_story_5046_50460201_63_dialog_content = "PlayerName様さえ解放するなら、どんな条件でも飲もう！",
  ui_story_5046_50460201_64_dialog_content = "条件を飲む？交換ってことか？",
  ui_story_5046_50460201_65_dialog_content = "…PlayerNameってのはアイツらにとってそうとう大事みたいだな。\nで、アンタのことか？",
  ui_story_5046_50460201_66_dialog_content = "そ、そうだよ…僕が人質になるから、\nその女の子は解放してあげて…",
  ui_story_5046_50460201_67_dialog_content = "「黒い凶星」！落ち着きなさい！",
  ui_story_5046_50460201_68_dialog_content = "チッ…うるさいな！",
  ui_story_5046_50460201_69_dialog_content = "ワンちゃん…こわい…",
  ui_story_5046_50460201_70_dialog_content = "うわああ！！",
  ui_story_5046_50460201_71_dialog_content = "PlayerNameさんが「黒い凶星」の人質にとられたのですか！？",
  ui_story_5046_50460201_72_dialog_content = "一歩でも前に出たら、こいつ殺すよ。",
  ui_story_5046_50460201_73_dialog_content = "アンタたちにとって大事な人なんだろ？\nだったら、ちょっと借りるよ。",
  ui_story_5046_50460201_74_dialog_content = "どこに連れてく気！？放して！",
  ui_story_5046_50460201_75_dialog_content = "た、助けて！",
  ui_story_5046_50460201_76_dialog_content = "衛兵！捕らえなさい！",
  ui_story_5046_50460201_77_dialog_content = "「黒い凶星」はPlayerName様を連れています！\n逃がしてはなりません！",
  ui_story_5046_50460202_1_dialog_content = "…報告いたします。\n「黒い凶星」を見失いました。",
  ui_story_5046_50460202_2_dialog_content = "先生…申し訳ございません。",
  ui_story_5046_50460202_3_dialog_content = "自身を責めることはありません。\n火の中では炎を操る「黒い凶星」の方に分があります。",
  ui_story_5046_50460202_4_dialog_content = "そのうえ、普通の光霊よりも動きが格段に機敏でした。",
  ui_story_5046_50460202_5_dialog_content = "見失うであろうことは予想のうちです。",
  ui_story_5046_50460202_6_dialog_content = "用意していただいた緊急避難計画が役に立ちました。",
  ui_story_5046_50460202_7_dialog_content = "現場の混乱で招待客の皆さんも驚きこそしましたが、\n無事に火災現場から離れています。",
  ui_story_5046_50460202_8_dialog_content = "ただ…一つ教えていただけませんか？\nなぜPlayerNameさんが人質に？",
  ui_story_5046_50460202_9_dialog_content = "申し訳ございません。私どもの失態です。",
  ui_story_5046_50460202_10_dialog_content = "いいえ、PlayerNameさんは私のせいで…",
  ui_story_5046_50460202_11_dialog_content = "ベセル様、容疑者の情報が上がりました。",
  ui_story_5046_50460202_12_dialog_content = "お疲れ様。",
  ui_story_5046_50460202_13_dialog_content = "「ハーティ、女、18歳、出身地不詳」",
  ui_story_5046_50460202_14_dialog_content = "「以前、影ノ街孤児院で短期間暮らしていたが、\nその後大火事を引き起こしたため、シャドウマスターが邸宅に引き取った」",
  ui_story_5046_50460202_15_dialog_content = "（…お父様…？お父様が裏で動いている？）",
  ui_story_5046_50460202_16_dialog_content = "孤児院の大火事を引き起こした、ですか？\nどうやら常習犯のようですね。",
  ui_story_5046_50460202_17_dialog_content = "「2カ月前に満18歳となり、審査の結果問題なしとされ、\nシャドウマスターの邸宅を出た」",
  ui_story_5046_50460202_18_dialog_content = "（やはりお父様にもお伝えした方が良さそうです）",
  ui_story_5046_50460202_19_dialog_content = "放火の前科がある者を野放しにしてしまって、\nよかったのでしょうか…？",
  ui_story_5046_50460202_20_dialog_content = "いずれにせよ、この件はシャドウマスターに報告し、\n影ノ街の各勢力を動員してPlayerNameさんの行方を捜索します。",
  ui_story_5046_50460202_21_dialog_content = "しかし…そんなことをすれば、大事になりはしませんかな…？",
  ui_story_5046_50460202_22_dialog_content = "大切なお客様がリハーサルの日にさらわれたなどと、\n世間に知られれば、孤児院の評判は…",
  ui_story_5046_50460202_23_dialog_content = "しかし、PlayerNameさんが生きているかどうかも\n確認できていないのですよ！",
  ui_story_5046_50460202_24_dialog_content = "はぁ…",
  ui_story_5046_50460202_25_dialog_content = "べセル様、ハーメル様。",
  ui_story_5046_50460202_26_dialog_content = "私を信じていただけるのでしたら…\n今しばらく、この件の公表をお控えくださいますか？",
  ui_story_5046_50460202_27_dialog_content = "下手に騒ぎ立てれば、\n「黒い凶星」がPlayerName様に危害を加える恐れがあります。",
  ui_story_5046_50460202_28_dialog_content = "私が一刻も早く「黒い凶星」の行方を探し出し、\nPlayerName様を助け出してみせましょう。",
  ui_story_5046_50460202_29_dialog_content = "…",
  ui_story_5046_50460202_30_dialog_content = "申し訳ありませんが、そうは行きません。",
  ui_story_5046_50460202_31_dialog_content = "信じていただけないということでしょうか…",
  ui_story_5046_50460202_32_dialog_content = "アイヴァン家の名にかけて誓います。\n私の師、騎士ゼナスは信頼に足る人物です。",
  ui_story_5046_50460202_33_dialog_content = "お嬢様、私のためにそのようなことは…",
  ui_story_5046_50460202_34_dialog_content = "ベセル様、どうか失態を挽回するチャンスをお与えください。",
  ui_story_5046_50460202_35_dialog_content = "ゼナスさんの騎士としてのお噂は私も聞いています。",
  ui_story_5046_50460202_36_dialog_content = "没落貴族から現在の地位まで駆け上がったその実力と手腕は、\n並々ならぬものでしょう。",
  ui_story_5046_50460202_37_dialog_content = "…いいでしょう。アイヴァン家の方が保証するとまでおっしゃるなら、\nひとまずお任せすることにします。",
  ui_story_5046_50460202_38_dialog_content = "ただし、これだけははっきりしておきましょう。\nこの件は遅かれ早かれシャドウマスターの耳に入ります。",
  ui_story_5046_50460202_39_dialog_content = "3日間差し上げます。",
  ui_story_5046_50460202_40_dialog_content = "3日後の竣工式の会場に、\n傷一つないPlayerNameさんの姿がなければ…",
  ui_story_5046_50460202_41_dialog_content = "この件は影ノ街のやり方で処理させていただきます。",
  ui_story_5046_50460202_42_dialog_content = "感謝いたします。",
  ui_story_5046_50460202_43_dialog_content = "感謝いたします。",
  ui_story_5046_50460202_44_dialog_content = "では、PlayerNameさんの件、\nくれぐれもよろしくお願いします。",
  ui_story_5046_50460202_45_dialog_content = "私たちの目下の急務はお客様を落ち着かせることです。\nハーメル院長、手伝っていただけませんか？",
  ui_story_5046_50460202_46_dialog_content = "その通りですな！",
  ui_story_5046_50460202_47_dialog_content = "ハーメル院長、私についてきてください。",
  ui_story_5046_50460202_48_dialog_content = "先生、「黒い凶星」探しを手伝わせてください。",
  ui_story_5046_50460202_49_dialog_content = "ここ数年ずっと光力術と体術の訓練に励んできました。\nそれもこれもいつか先生のお力になりたかったからです。",
  ui_story_5046_50460202_50_dialog_content = "私に機会をお与えください！",
  ui_story_5046_50460202_51_dialog_content = "なりません。",
  ui_story_5046_50460202_52_dialog_content = "消火の時に先走ったせいで、信用していただけないのですか？",
  ui_story_5046_50460202_53_dialog_content = "…確かに私が間違っていました。\nまた先生に助けていただくなんて…",
  ui_story_5046_50460202_54_dialog_content = "なぜ私はいつも先生を危険にさらしてばかりなのでしょう…？",
  ui_story_5046_50460202_55_dialog_content = "お嬢様、ご自身を責めないでください。",
  ui_story_5046_50460202_56_dialog_content = "昔も今も、お嬢様を守ると決めたのは私自身です。",
  ui_story_5046_50460202_57_dialog_content = "では、なぜ…",
  ui_story_5046_50460202_58_dialog_content = "お嬢様はいつも現場の調査報告書や資料の中から、\n重要な手がかりを見つけ出すことができています。",
  ui_story_5046_50460202_59_dialog_content = "犯人を第一線で追跡されるより、\n調査や資料分析の方が適任と言えましょう。",
  ui_story_5046_50460202_60_dialog_content = "不得手なことを無理して行う必要はないのです。",
  ui_story_5046_50460202_61_dialog_content = "不得手というより、経験が不足しているだけで…",
  ui_story_5046_50460202_62_dialog_content = "お嬢様？",
  ui_story_5046_50460202_63_dialog_content = "…いいえ、何でもありません。",
  ui_story_5046_50460202_64_dialog_content = "では、お嬢様には火災現場の調査をお願いいたします。\nきっと有用な手がかりを見つけてくださると信じています。",
  ui_story_5046_50460202_65_dialog_content = "はい…わかりました。",
  ui_story_5046_50460202_66_dialog_content = "必ず手がかりを見つけてみせます！",
  ui_story_5046_50460202_67_dialog_content = "報告は以上です、お父様。",
  ui_story_5046_50460202_68_dialog_content = "この後、どういたしましょう？",
  ui_story_5046_50460202_69_dialog_content = "うむ…",
  ui_story_5046_50460202_70_dialog_content = "静観、だ。",
  ui_story_5046_50460202_71_dialog_content = "ですが、PlayerNameさんの安否は…",
  ui_story_5046_50460202_72_dialog_content = "心配はいらん。PlayerNameの方は見ている者がいる。",
  ui_story_5046_50460202_73_dialog_content = "はい。",
  ui_story_5046_50460301_1_dialog_content = "<color=#e8d9bb>影ノ街、バー・ファイアフライ</color>",
  ui_story_5046_50460301_2_dialog_content = "戻りましたか。",
  ui_story_5046_50460301_3_dialog_content = "（僕はいったいどこへ連れて来られたんだろう？）",
  ui_story_5046_50460301_4_dialog_content = "今日は竣工式のリハーサルを見に行ったんではなかったですか？\nその手みやげは？",
  ui_story_5046_50460301_5_dialog_content = "（この雰囲気、どこかのバーみたいだ…\n気を失ったふりして会話を聞いてみよう）",
  ui_story_5046_50460301_6_dialog_content = "うっとうしい「トゲ玉」だ。",
  ui_story_5046_50460301_7_dialog_content = "ハハハ…よく服にくっついてくる、\nトゲトゲの植物の種のことですか？",
  ui_story_5046_50460301_8_dialog_content = "ああ。昔母さんがよく外からくっつけて帰って来て、\n取るのを手伝わされたもんだよ。",
  ui_story_5046_50460301_9_dialog_content = "それで、モノは？\n手に入りましたか？",
  ui_story_5046_50460301_10_dialog_content = "いや。この「トゲ玉」のせいで手間取っちまった。\n人も増えたから手が出せなかった。",
  ui_story_5046_50460301_11_dialog_content = "この「トゲ玉」、たいしたやつみたいなんだ。\n現場にいたやつらが血眼になってた。",
  ui_story_5046_50460301_12_dialog_content = "おやおや、この人は…空の末裔じゃありませんか！",
  ui_story_5046_50460301_13_dialog_content = "空の末裔ってなんだ？",
  ui_story_5046_50460301_14_dialog_content = "空の末裔も知らないんですか？\nあ、そうでしたね…あなたは世間に出てまだ2カ月足らずでした。",
  ui_story_5046_50460301_15_dialog_content = "で、空の末裔ってのは寝たフリする習性でもあるのか？",
  ui_story_5046_50460301_16_dialog_content = "（うっ、盗み聞きしてるのがバレてる！？）",
  ui_story_5046_50460301_17_dialog_content = "分かりませんね。\n影ノ街のタブロイドにもそんなことは書かれていませんでしたが。",
  ui_story_5046_50460301_18_dialog_content = "おい、起きろ。",
  ui_story_5046_50460301_19_dialog_content = "（力が強い！ゆすられただけで骨が折れそうだ！）",
  ui_story_5046_50460301_20_dialog_content = "（いま目が覚めたふりをするしかないね…）",
  ui_story_5046_50460301_21_dialog_content = "う～ん…",
  ui_story_5046_50460301_22_dialog_content = "ここはどこ？",
  ui_story_5046_50460301_23_dialog_content = "なんだって今やっと目が覚めたみたいなフリしてんだ？\nバーに入って来た時からあちこち見回してたろ？",
  ui_story_5046_50460301_24_dialog_content = "あはは…な、何を言ってるの？\nほんとにいま目が覚めたばっかりだよ。",
  ui_story_5046_50460301_25_dialog_content = "ウソつきにろくなヤツはいない。",
  ui_story_5046_50460301_26_dialog_content = "まあまあ、PlayerNameさんを怖がらせちゃダメですよ。",
  ui_story_5046_50460301_27_dialog_content = "ど、どうして僕の名前を知ってるの？",
  ui_story_5046_50460301_28_dialog_content = "空の末裔の名は大陸中に響き渡ってますからね。\nあなたの名前を知ってても不思議じゃないでしょう？",
  ui_story_5046_50460301_29_dialog_content = "そ、それもそうだね。",
  ui_story_5046_50460301_30_dialog_content = "そう緊張することはありません。\n私たちは悪人と言う訳ではないので。",
  ui_story_5046_50460301_31_dialog_content = "私はグリム。「バー・ファイアフライ」のバーテンダーです。",
  ui_story_5046_50460301_32_dialog_content = "そちらはハーティ。このバーでアルバイトしてるんです。",
  ui_story_5046_50460301_33_dialog_content = "関係は…そうですね、私がハーティの保護者みたいなものでしょうか。",
  ui_story_5046_50460301_34_dialog_content = "シャドウマスターのところから出てきて以来、\nずっと私が面倒を見てるんです。",
  ui_story_5046_50460301_35_dialog_content = "大人っぽい見た目なんで、20代に見えるでしょう？\n実際には18歳なんですよ。",
  ui_story_5046_50460301_36_dialog_content = "おまけに世間に出てまだ2カ月ぐらいなもんで、\n実際の精神年齢は7、8歳といったところですかね。",
  ui_story_5046_50460301_37_dialog_content = "なぜあなたを連れてきたのかは知りませんが、\nこれだけは信じてください。ハーティはいい子ですよ。",
  ui_story_5046_50460301_38_dialog_content = "人をさらっておいて、「いい子」っていうのは…",
  ui_story_5046_50460301_39_dialog_content = "言動がまっすぐすぎるだけですよ。\n別に何か悪いことを考えてるわけじゃないんです。",
  ui_story_5046_50460301_40_dialog_content = "ですが、あなたをさらったことはハーティの過ちです。\n私からお詫びします。",
  ui_story_5046_50460301_41_dialog_content = "チッ、どうしてこんなやつに謝んなきゃいけないんだ？",
  ui_story_5046_50460301_42_dialog_content = "こいつも他のやつらと同じだ。ボクを悪者扱いした。\n「黒い凶星」とかなんとかって呼んでさ…",
  ui_story_5046_50460301_43_dialog_content = "相手が何を言ったとしても、誘拐するのは間違いです。",
  ui_story_5046_50460301_44_dialog_content = "間違いを犯したら、謝るのが当然です。",
  ui_story_5046_50460301_45_dialog_content = "チッ…",
  ui_story_5046_50460301_46_dialog_content = "ごめん。",
  ui_story_5046_50460301_47_dialog_content = "（凶暴そうな見た目なのに、\nグリムの言うことは聞くんだね…）",
  ui_story_5046_50460301_48_dialog_content = "すみませんでした、PlayerNameさん。",
  ui_story_5046_50460301_49_dialog_content = "（…今のところ誘拐以上に何かされたわけでもないし、ちゃんと誠意を感じる…）",
  ui_story_5046_50460301_50_dialog_content = "う、うん…心のこもった謝罪だし、\nひとまず許してあげるよ。",
  ui_story_5046_50460301_51_dialog_content = "じゃあ、握手でもして、帳消しとしましょうか。",
  ui_story_5046_50460301_52_dialog_content = "…",
  ui_story_5046_50460301_53_dialog_content = "…",
  ui_story_5046_50460301_54_dialog_content = "ハハハ、2人とも硬い顔してますね。",
  ui_story_5046_50460301_55_dialog_content = "あの力で握手って言うと…",
  ui_story_5046_50460301_56_dialog_content = "ああ、そうでした！空の末裔は感知能力で\n他人の奥深くに眠る記憶を探ることができるんですよね？",
  ui_story_5046_50460301_57_dialog_content = "PlayerNameさんに手伝ってもらえば、\nお母さんのことを思い出せるかもしれませんよ。",
  ui_story_5046_50460301_58_dialog_content = "（お母さんって聞いたとたん、ハーティが急に辛そうな顔をした…）",
  ui_story_5046_50460301_59_dialog_content = "ハーティ、昔に何があったのかずっと知りたがってたでしょう？",
  ui_story_5046_50460301_60_dialog_content = "…こいつが役に立つのか？",
  ui_story_5046_50460301_61_dialog_content = "僕の力を見くびらないでよ。\nでも…僕が手伝わなきゃいけない理由もないよね？",
  ui_story_5046_50460301_62_dialog_content = "ううん…確かにそれはそうですね。",
  ui_story_5046_50460301_63_dialog_content = "じゃあ、こうしよう。\n感知能力で手伝う代わりに、僕を皆のところへ帰して。",
  ui_story_5046_50460301_64_dialog_content = "それから、ハーティは自首するんだ。\n自分の犯した罪はきちんと償わないと。",
  ui_story_5046_50460301_65_dialog_content = "ごもっともな提案です。そうしましょう。",
  ui_story_5046_50460301_66_dialog_content = "ただ、火事の件は本当にハーティではありません。\n私が保証します。",
  ui_story_5046_50460301_67_dialog_content = "どうしても事件が気になるというのなら、\nハーティに真犯人探しを手伝わせてみてはどうですか？",
  ui_story_5046_50460301_68_dialog_content = "それもお手伝いの交換条件ということで。",
  ui_story_5046_50460301_69_dialog_content = "それでいいよ！",
  ui_story_5046_50460301_70_dialog_content = "…",
  ui_story_5046_50460301_71_dialog_content = "アンタがボクの記憶を取り戻せた時は…",
  ui_story_5046_50460301_72_dialog_content = "ボクを役人につき出して\n20万白夜コインの賞金にしても、文句はないよ。",
  ui_story_5046_50460301_73_dialog_content = "安心して。本当に犯人じゃないなら\nつき出したりはしないよ。",
  ui_story_5046_50460301_74_dialog_content = "20万は確かに大金だけど、\nお金のためにそんなことはしない。",
  ui_story_5046_50460301_75_dialog_content = "どっちでもいいさ。",
  ui_story_5046_50460301_76_dialog_content = "じゃあ…僕は何をすればいい？",
  ui_story_5046_50460301_77_dialog_content = "感知能力を十分に発揮するには、\n事情を詳しく知っておいた方がいいんだ。",
  ui_story_5046_50460301_78_dialog_content = "母さんを探したい。",
  ui_story_5046_50460301_79_dialog_content = "子どもの頃、母さんと一緒に暮らしてた。\nすごく可愛がってくれたわけじゃないけど、怖くもなかった。",
  ui_story_5046_50460301_80_dialog_content = "それがある日、母さんと離れ離れになったんだ。\nどうしてかは分からない。",
  ui_story_5046_50460301_81_dialog_content = "その後は、もう孤児院にいる時の記憶しかない。",
  ui_story_5046_50460301_82_dialog_content = "つまり、その間の記憶が抜けてるってことだね。",
  ui_story_5046_50460301_83_dialog_content = "そして、その記憶を取り戻すことができれば、\nお母さんを見つけられるかもしれない…",
  ui_story_5046_50460301_84_dialog_content = "そうだ。",
  ui_story_5046_50460301_85_dialog_content = "情報はそれだけ？",
  ui_story_5046_50460301_86_dialog_content = "うん。",
  ui_story_5046_50460301_87_dialog_content = "そっか…僕や僕の感知能力を信じられないのは分かる。",
  ui_story_5046_50460301_88_dialog_content = "でも、約束した以上は全力でやるよ。",
  ui_story_5046_50460301_89_dialog_content = "…",
  ui_story_5046_50460301_90_dialog_content = "すみませんね、PlayerNameさん。\nこの子は世間に出てまだ日が浅いので。とっつきにくいでしょう？",
  ui_story_5046_50460301_91_dialog_content = "大丈夫だよ。僕は君たちがきちんと約束を守って、\n手伝いが終わったら解放してくれればいいんだ。",
  ui_story_5046_50460301_92_dialog_content = "ハーティ、記憶が途切れる前に覚えてる、\n最後の情景を思い出してみて。",
  ui_story_5046_50460301_93_dialog_content = "準備ができたら教えてね。",
  ui_story_5046_50460301_94_dialog_content = "準備できた。",
  ui_story_5046_50460301_95_dialog_content = "ハーティ、深呼吸です。\n緊張しなくて大丈夫ですよ。",
  ui_story_5046_50460301_96_dialog_content = "じゃあ、始めるよ。",
  ui_story_5046_50460301_97_option_content = "強制感知！",
  ui_story_5046_50460301_98_dialog_content = "…",
  ui_story_5046_50460301_99_dialog_content = "（ここはどこだろう？普通の民家みたいだな…）",
  ui_story_5046_50460301_100_dialog_content = "（ハーティの家かな？）",
  ui_story_5046_50460301_101_dialog_content = "（PlayerName？）",
  ui_story_5046_50460301_102_dialog_content = "（アンタ、本当にボクの記憶が見えるんだな）",
  ui_story_5046_50460301_103_dialog_content = "（これで、信じた？）",
  ui_story_5046_50460301_104_dialog_content = "<color=#e8d9bb>カツン、カツン、カツン…</color>",
  ui_story_5046_50460301_105_dialog_content = "（足跡が近づいてくる）",
  ui_story_5046_50460301_106_dialog_content = "ハーティったら…どこへ行ったのかしら？",
  ui_story_5046_50460301_107_dialog_content = "（誰だろう？）",
  ui_story_5046_50460301_108_dialog_content = "（母さん…）",
  ui_story_5046_50460301_109_dialog_content = "はぁ…",
  ui_story_5046_50460301_110_dialog_content = "あの子の力…ますます制御が効かなくなってるわ…\n心配ね…",
  ui_story_5046_50460301_111_dialog_content = "それに、どんどん外へ出たがるようになってる…",
  ui_story_5046_50460301_112_dialog_content = "でも、絶対に外の世界に出すわけにはいかない…",
  ui_story_5046_50460301_113_dialog_content = "（どうしてハーティを外に出しちゃいけないんだろう？）",
  ui_story_5046_50460301_114_dialog_content = "（ボクの力を…ボクの炎を…恐れてるんだ）",
  ui_story_5046_50460301_115_dialog_content = "<color=#e8d9bb>ボン…</color>",
  ui_story_5046_50460301_116_dialog_content = "アオオオン！！！",
  ui_story_5046_50460301_117_dialog_content = "（うわっ！？）",
  ui_story_5046_50460301_118_dialog_content = "（こ、これは…犬？オオカミ？大きい！）",
  ui_story_5046_50460301_119_dialog_content = "（しかもハーティとちょっと似てる…）",
  ui_story_5046_50460301_120_dialog_content = "（ボクの心の闇さ。自分の力に対する恐怖や嫌悪が具現化したんだ）",
  ui_story_5046_50460301_121_dialog_content = "（こいつがボクの失った記憶を守ってるんだ。\n一歩も近づけさせてくれない）",
  ui_story_5046_50460301_122_dialog_content = "（う――！頭が痛い！）",
  ui_story_5046_50460301_123_dialog_content = "（どうしたの？…よくない状況になったみたいだ）",
  ui_story_5046_50460301_124_dialog_content = "俺が嫌いか…！？だが…俺はお前だ…！",
  ui_story_5046_50460301_125_dialog_content = "（まずい！感知をやめて、ここを離れよう！）",
  ui_story_5046_50460301_126_dialog_content = "PlayerNameは本当にボクの記憶が見えるんだな。\nしかも、心の闇まで…",
  ui_story_5046_50460301_127_dialog_content = "空の末裔の能力って不思議だな。",
  ui_story_5046_50460301_128_dialog_content = "どうやら、空の末裔の感知能力が助けになりそうですね。",
  ui_story_5046_50460301_129_dialog_content = "よかったですね、ハーティ。",
  ui_story_5046_50460301_130_dialog_content = "でも、心の闇が出てきて、\nハーティの気持ちが動揺したから、感知を止めたんだ。",
  ui_story_5046_50460301_131_dialog_content = "ハーティはまだ何も思い出せてないよ…",
  ui_story_5046_50460301_132_dialog_content = "事情を詳しく知った方が、\n記憶を取り戻せる可能性は高くなるって言ってたな？",
  ui_story_5046_50460301_133_dialog_content = "えっ？",
  ui_story_5046_50460301_134_dialog_content = "た、たぶんね…",
  ui_story_5046_50460301_135_dialog_content = "じゃあ、もっと詳しく話す。\nそれからもう一回、感知能力で試してくれないか？",
  ui_story_5046_50460301_136_dialog_content = "別にいいけど…",
  ui_story_5046_50460301_137_dialog_content = "約束は守ってね。終わったら僕を解放してよ。",
  ui_story_5046_50460301_138_dialog_content = "約束する。",
  ui_story_5046_50460401_1_dialog_content = "クリステン裁判官、報告いたします。\nこちらが火災現場の調査報告書です。お目通しください。",
  ui_story_5046_50460401_2_dialog_content = "ありがとうございます。ただ、私はまだ見習い裁判官ですから、\nクリステンと呼んでくださって結構です。",
  ui_story_5046_50460401_3_dialog_content = "火元は発火性の油…孤児院の建設工事で余った建材と\n一緒に倉庫に保管されていたわけですね。",
  ui_story_5046_50460401_4_dialog_content = "火災発生当時は竣工式の準備で現場があわただしく、\n誰も倉庫に油が持ち込まれたことに気づかなかった…",
  ui_story_5046_50460401_5_dialog_content = "今回見つかった油は過去2カ月に発生した火災現場のものと\n一致しており、同一人物の犯行と推測される…",
  ui_story_5046_50460401_6_dialog_content = "うーん…確かに筋は通っていますね。",
  ui_story_5046_50460401_7_dialog_content = "ただ過去2カ月の火災では、逃走時に人質など取っていません。\nそれが今回は空の末裔をさらって逃走…",
  ui_story_5046_50460401_8_dialog_content = "この点には疑問が残りますね。\n容疑者の犯行動機は何なのでしょう？",
  ui_story_5046_50460401_9_dialog_content = "現場の者によると、容疑者は亜人族系の光霊で、\n名はハーティと言うそうです。",
  ui_story_5046_50460401_10_dialog_content = "これまでシャドウマスターの邸宅で暮らしていたようですが、\n2カ月前その邸宅を離れています。こちらが関連の資料です。",
  ui_story_5046_50460401_11_dialog_content = "ふむ…",
  ui_story_5046_50460401_12_dialog_content = "「目撃者は孤児院の火災当夜、ハーティが強大な炎の光力を放ち、\n大火災を起こしたと証言している」",
  ui_story_5046_50460401_13_dialog_content = "今ある手がかりからは、すべてこのハーティという名の\n亜人族系光霊が浮かび上がります。",
  ui_story_5046_50460401_14_dialog_content = "ハーティがシャドウマスターの邸宅を出て間もなく、\n火災が発生するように…ただ、目的は何なのでしょう？",
  ui_story_5046_50460401_15_dialog_content = "そういえば、救助された女の子は…",
  ui_story_5046_50460401_16_dialog_content = "現在孤児院の宿舎で、保育士が面倒を見ています。",
  ui_story_5046_50460401_17_dialog_content = "孤児院に行って、女の子に事件の時の状況を聞いてみましょう。",
  ui_story_5046_50460401_18_dialog_content = "こんにちは。白夜城の見習い裁判官クリステンと申します。",
  ui_story_5046_50460401_19_dialog_content = "その子に火災時の状況をお聞きしたいのですが。",
  ui_story_5046_50460401_20_dialog_content = "白夜城貴族の方ですか…お断りするとは言えませんが…\nただ、この子はまだ気持ちが落ち着いてないんです。",
  ui_story_5046_50460401_21_dialog_content = "聞きたいことがあるのでしたら手短にお願いします。\nあの子が騒ぎ出すようなら、すぐに帰っていただきますよ。",
  ui_story_5046_50460401_22_dialog_content = "当然のご配慮です。手短に済ませるようにいたします。",
  ui_story_5046_50460401_23_dialog_content = "こんにちは。",
  ui_story_5046_50460401_24_dialog_content = "あ！あの時のお姉ちゃんだ！",
  ui_story_5046_50460401_25_dialog_content = "あたしを助けてくれたお兄ちゃんとワンちゃんは！？",
  ui_story_5046_50460401_26_dialog_content = "2人は…来てないの。お兄ちゃんたちとはお友だち？",
  ui_story_5046_50460401_27_dialog_content = "ちがうよ。でも火がついた時、あたしを守ってくれたの。\nだから、お兄ちゃんはいい人だよ！",
  ui_story_5046_50460401_28_dialog_content = "ワンちゃんはね、お空から木が落ちて来た時突然現れてね。\nあたしとお兄ちゃんを守ってくれたの！",
  ui_story_5046_50460401_29_dialog_content = "（ハーティが2人を守ったということ？）",
  ui_story_5046_50460401_30_dialog_content = "じゃあ、お姉ちゃんに教えてくれる？\nどうしてあの時、逃げ遅れたの？",
  ui_story_5046_50460401_31_dialog_content = "…ぐすっ…",
  ui_story_5046_50460401_32_dialog_content = "…",
  ui_story_5046_50460401_33_dialog_content = "うっ…そうそう、お菓子でも食べない？",
  ui_story_5046_50460401_34_dialog_content = "たべる！",
  ui_story_5046_50460401_35_dialog_content = "モグモグ…あの日はね、かくれんぼしてたの。\nそれであそこにかくれてたんだよ。",
  ui_story_5046_50460401_36_dialog_content = "中にはたくさんタルがあって、\nそれから、おかしな箱も置いてあった。",
  ui_story_5046_50460401_37_dialog_content = "おかしな箱？",
  ui_story_5046_50460401_38_dialog_content = "うん。あたし、箱にぶつかっちゃって、地面に落としちゃったんだ。\nそしたら、バアーって火がついちゃったの！",
  ui_story_5046_50460401_39_dialog_content = "お外ににげようと思ったけど、火がいっぱいで、あつくて、\nすっごくこわかった。",
  ui_story_5046_50460401_40_dialog_content = "うっ…うわああん…あ、あたし…わざとじゃないよ…",
  ui_story_5046_50460401_41_dialog_content = "うわああああああん――",
  ui_story_5046_50460401_42_dialog_content = "火、こわいよおおお！",
  ui_story_5046_50460401_43_dialog_content = "何をやってるんですか？また泣き出したじゃないですか。\n聞きたいことは聞いたでしょう？さっさと帰ってください。",
  ui_story_5046_50460401_44_dialog_content = "ごめんね…ただ、今度からは1人で知らない所に行ってはダメよ。",
  ui_story_5046_50460401_45_dialog_content = "うわあああん…わ、わかった…",
  ui_story_5046_50460401_46_dialog_content = "<color=#e8d9bb>影ノ街、バー・ファイアフライ</color>",
  ui_story_5046_50460401_47_dialog_content = "ダメだ…やっぱり思い出せない…",
  ui_story_5046_50460401_48_dialog_content = "これだけたくさん情報があっても、\n感知能力じゃ、やっぱりあの頃の記憶を思い出せないのか…",
  ui_story_5046_50460401_49_dialog_content = "ごめん。力になれなくて…",
  ui_story_5046_50460401_50_dialog_content = "さらってきたことを許してくれただけでなく、\n手助けまでしてくれようとしたんです。十分ですよ。",
  ui_story_5046_50460401_51_dialog_content = "きっと他に方法はあるさ…",
  ui_story_5046_50460401_52_dialog_content = "ペンダント！そうだ、ロケットペンダントだ！",
  ui_story_5046_50460401_53_dialog_content = "ロケットペンダント？",
  ui_story_5046_50460401_54_dialog_content = "こいつをさらってきたのは、\nあのマスク野郎からペンダントを取り返すためなんだ。",
  ui_story_5046_50460401_55_dialog_content = "あのロケットペンダントは大切なものなんだ。\nアンタもマスク野郎にとって大切だ。",
  ui_story_5046_50460401_56_dialog_content = "等価交換だ。",
  ui_story_5046_50460401_57_dialog_content = "僕とペンダントを交換する！？\nそんな荒っぽいやり方通らないでしょ！？",
  ui_story_5046_50460401_58_dialog_content = "君は本当に人付き合いができないんだね！",
  ui_story_5046_50460401_59_dialog_content = "グリム、ハーティの保護者なんだよね？\n何か言うことはないの？",
  ui_story_5046_50460401_60_dialog_content = "確かに直球すぎますが、間違ってはないんじゃないですか？",
  ui_story_5046_50460401_61_dialog_content = "PlayerNameさんは皆さんの元へ帰れますし、\nハーティもほしいものを手に入れられます。",
  ui_story_5046_50460401_62_dialog_content = "とても割に合った取引だと思いますよ？",
  ui_story_5046_50460401_63_dialog_content = "た、確かに筋は通ってるね…",
  ui_story_5046_50460401_64_dialog_content = "いや、ちょっと待ってよ！\n手伝ったら解放してくれるんじゃなかったの？",
  ui_story_5046_50460401_65_dialog_content = "どうして今度もまた僕が取引のコマになるの！？\n約束が違うでしょ！？",
  ui_story_5046_50460401_66_dialog_content = "ですが…ハーティは記憶を取り戻せてないですよね？",
  ui_story_5046_50460401_67_dialog_content = "うう、そんな…影ノ街の人はやっぱりずるい。",
  ui_story_5046_50460401_68_dialog_content = "（交換条件にされるのは気分が悪いけど、\n僕が何か損をするわけじゃないし…）",
  ui_story_5046_50460401_69_dialog_content = "（それに隙を見て逃げ出せるかもしれない…\nそうすればベセルたちに知らせることもできる…）",
  ui_story_5046_50460401_70_dialog_content = "じゃあ次はどうしたらマスク男と取引できるか、\n考えないといけませんね。",
  ui_story_5046_50460401_71_dialog_content = "ハーティは今指名手配されてますから、\nむやみに出て行っては、取引する前に逮捕されてしまいます。",
  ui_story_5046_50460401_72_dialog_content = "では、こうしましょう。ハーティ、手紙を書いてください。\n私が何とかしてマスク男に渡しましょう。",
  ui_story_5046_50460401_73_dialog_content = "影ノ街の外で会うことにし、\n向こうには必ず1人で来るよう伝えるんです。",
  ui_story_5046_50460401_74_dialog_content = "分かった。",
  ui_story_5046_50460401_75_dialog_content = "グリム、そいつが逃げないように見張っててくれ。",
  ui_story_5046_50460401_76_dialog_content = "逃げ出そうとしたら、気を失わせるんだ。\nボクが連れてきた時みたいにさ。",
  ui_story_5046_50460401_77_dialog_content = "うう！",
  ui_story_5046_50460401_78_dialog_content = "何か飲みますか？取引が成立すれば、帰れますよ。",
  ui_story_5046_50460401_79_dialog_content = "そうしたら、ここでゆっくり飲むこともかなわなくなりますから。",
  ui_story_5046_50460401_80_dialog_content = "ロケットペンダントって、どういうものなの？",
  ui_story_5046_50460401_81_dialog_content = "どうしてハーティは取り返そうとしてるの？",
  ui_story_5046_50460401_82_dialog_content = "ちょうどハーティもいませんし、お話でもしましょうか。",
  ui_story_5046_50460401_83_dialog_content = "ある日ハーティが突然慌てて帰ってきて、\nマスクの男が母親のロケットペンダントを付けていたと言ったんです。",
  ui_story_5046_50460401_84_dialog_content = "マスクの男？きっとゼナスのことだね。\nマスクをつけてるのはゼナスだけだから。",
  ui_story_5046_50460401_85_dialog_content = "その男と交渉したそうですが、相手はハーティを見てとても驚いた様子で、\nどんな条件を出しても渡してくれなかったそうです。",
  ui_story_5046_50460401_86_dialog_content = "そこで、ハーティはペンダントを男から奪う計画を立てました。",
  ui_story_5046_50460401_87_dialog_content = "でも、そんなことしたら犯罪だよね！？",
  ui_story_5046_50460401_88_dialog_content = "それにゼナスの付けてるペンダントが自分の探してるものだって、\nどうしてハーティには分かるの？",
  ui_story_5046_50460401_89_dialog_content = "本人が言うには、そのロケットペンダントを見た途端、\n突然頭が痛くなったらしいですよ。",
  ui_story_5046_50460401_90_dialog_content = "それと、ペンダントの紋様は母親のしていたものと\n全く同じだったとも言っていました。",
  ui_story_5046_50460401_91_dialog_content = "そのペンダントさえあれば、\n失くした記憶を取り戻せると言ってましてね。",
  ui_story_5046_50460401_92_dialog_content = "子馬の紋様のこと？",
  ui_story_5046_50460401_93_dialog_content = "白夜城の貴族はぞれぞれ家紋をもってるんだよね。\nまさかゼナスとハーティの母親は同じ一族なのかな？",
  ui_story_5046_50460401_94_dialog_content = "それは私にも分かりません。",
  ui_story_5046_50460401_95_dialog_content = "手紙、書けたよ。",
  ui_story_5046_50460401_96_dialog_content = "<color=#e8d9bb>トントン、トン、トトン</color>",
  ui_story_5046_50460401_97_dialog_content = "ちょうどいいところに来てくれました。どうぞ。",
  ui_story_5046_50460401_98_dialog_content = "店主さん。",
  ui_story_5046_50460401_99_dialog_content = "大丈夫です。ハーティもPlayerNameさんも悪い人じゃありません。",
  ui_story_5046_50460401_100_dialog_content = "影ノ街の各勢力に動きはありません。\n白夜城から来たあの騎士が今人を連れてこっちに向かってます。",
  ui_story_5046_50460401_101_dialog_content = "たぶん、もうすぐ来ます。",
  ui_story_5046_50460401_102_dialog_content = "そうですか。ちょうどいいじゃないですか。",
  ui_story_5046_50460401_103_dialog_content = "ありがとう。さあ、報酬ですよ。",
  ui_story_5046_50460401_104_dialog_content = "ありがとう！",
  ui_story_5046_50460401_105_dialog_content = "失礼します。",
  ui_story_5046_50460401_106_dialog_content = "（あの子、グリムの密偵だったの？\nグリムはいったい何者なんだろう…？）",
  ui_story_5046_50460401_107_dialog_content = "ハーティ、手紙は私が渡します。\n先に約束の場所に行って待ってるといいですよ。",
  ui_story_5046_50460401_108_dialog_content = "分かった。PlayerName、行くぞ。",
  ui_story_5046_50460401_109_dialog_content = "大人しくついてこいよ。大声で叫びでもしたら…",
  ui_story_5046_50460401_110_dialog_content = "気を失わせる、でしょ？",
  ui_story_5046_50460401_111_dialog_content = "今度こそ約束を守ってくれることを願ってるよ。\nペンダントを手に入れたら、僕を解放してね。",
  ui_story_5046_50460401_112_dialog_content = "白夜城の衛兵はもう近くまで来ています。\nくれぐれも気を付けてくださいね。",
  ui_story_5046_50460401_113_dialog_content = "気を失わせりゃ済むことだ。",
  ui_story_5046_50460402_1_dialog_content = "<color=#e8d9bb>チリン――</color>",
  ui_story_5046_50460402_2_dialog_content = "いらっしゃいませ。何にいたしますか？",
  ui_story_5046_50460402_3_dialog_content = "おや、白夜城のお役人さんでしたか。\n貴いご身分のお方が影ノ街の小さなバーに何の用です？",
  ui_story_5046_50460402_4_dialog_content = "長くお邪魔するつもりはありません。\nお聞きしたいことがあります。",
  ui_story_5046_50460402_5_dialog_content = "では、何か飲みながらゆっくりお話ししましょう。\n知ってることは何でもお話ししますよ。",
  ui_story_5046_50460402_6_dialog_content = "いいえ…",
  ui_story_5046_50460402_7_dialog_content = "目撃者の証言によると、今日リハーサル会場で火をつけた犯人は、\nあなたの友人であるハーティです。",
  ui_story_5046_50460402_8_dialog_content = "逃走ルートから推測するに、\nハーティはこのバーに逃げ込んだと考えられます。",
  ui_story_5046_50460402_9_dialog_content = "捜査にご協力願います。",
  ui_story_5046_50460402_10_dialog_content = "もちろん、協力したいのはやまやまですが、\nハーティが放火犯だという確固たる証拠を見せていただかないと…",
  ui_story_5046_50460402_11_dialog_content = "協力は難しいですね。",
  ui_story_5046_50460402_12_dialog_content = "ならば、強制捜査するのみです。",
  ui_story_5046_50460402_13_dialog_content = "空の末裔はハーティと一緒にいますよ。",
  ui_story_5046_50460402_14_dialog_content = "！",
  ui_story_5046_50460402_15_dialog_content = "白夜城からわざわざ影ノ街の警備にきておきながら、\n大切な客人をさらわれてしまうとは。",
  ui_story_5046_50460402_16_dialog_content = "ベセルさんは影ノ街の勢力の協力を仰がず、\nあなたに好きなように調査させている…",
  ui_story_5046_50460402_17_dialog_content = "事を荒立てない配慮でしょうね。",
  ui_story_5046_50460402_18_dialog_content = "あなただって、この件を世間に知られたくはないんでしょう？",
  ui_story_5046_50460402_19_dialog_content = "フッ。ハーティの居場所を知っていますね？\nハーティさえ引き渡せば、白夜城も影ノ街も悪いようにはいたしません。",
  ui_story_5046_50460402_20_dialog_content = "ハハハ…悪いようにしない、ですか。\n2人きりでゆっくり話しましょうか。",
  ui_story_5046_50460402_21_dialog_content = "あなたたちは外してください。",
  ui_story_5046_50460402_22_dialog_content = "しかし、隊長――",
  ui_story_5046_50460402_23_dialog_content = "外で待っていなさい。",
  ui_story_5046_50460402_24_dialog_content = "はい。",
  ui_story_5046_50460402_25_dialog_content = "フフ、さすが今の地位まで登ってきただけのことはありますね。",
  ui_story_5046_50460402_26_dialog_content = "で、これがハーティからあなたに渡すよう頼まれた手紙ですよ。",
  ui_story_5046_50460402_27_dialog_content = "「マスク野郎」",
  ui_story_5046_50460402_28_dialog_content = "「日が落ちるまでにロケットペンダントをもって、\n影ノ街の東の森にある一番背の高いメープルの木の下まで来い。空の末裔と交換だ」",
  ui_story_5046_50460402_29_dialog_content = "「必ず1人で来い。誰にもこのことを話すな。\n小賢しいマネをすれば後悔するぞ」",
  ui_story_5046_50460402_30_dialog_content = "「ハーティ」",
  ui_story_5046_50460402_31_dialog_content = "…",
  ui_story_5046_50460402_32_dialog_content = "PlayerName様は無事なのでしょうね？",
  ui_story_5046_50460402_33_dialog_content = "安心してください。空の末裔ならピンピンしてます。\nただ…時間もあまりないことですし、他に選択肢はありませんよ。",
  ui_story_5046_50460402_34_dialog_content = "フッ、この私に脅しは通用しません。",
  ui_story_5046_50460402_35_dialog_content = "お気を付けて。今度は何か注文してくださいね。",
  ui_story_5046_50460402_36_dialog_content = "…",
  ui_story_5046_50460402_37_dialog_content = "店主さん。",
  ui_story_5046_50460402_38_dialog_content = "店番をしててくれますか？ちょっと出てきます。",
  ui_story_5046_50460402_39_dialog_content = "隊長！",
  ui_story_5046_50460402_40_dialog_content = "少々独りで調べたいことができました。",
  ui_story_5046_50460402_41_dialog_content = "あなたたちは引き続きこの一帯を捜索してください。\n隅々まで探すのですよ。",
  ui_story_5046_50460402_42_dialog_content = "容疑者とPlayerName様の痕跡を見つけ次第、\nPlayerName様の安全を第一に2人を連れ帰るのです。",
  ui_story_5046_50460402_43_dialog_content = "了解です！",
  ui_story_5046_50460402_44_dialog_content = "<color=#e8d9bb>影ノ街、資料館</color>",
  ui_story_5046_50460402_45_dialog_content = "過去2カ月に起こった火災の資料はこちらです。",
  ui_story_5046_50460402_46_dialog_content = "ありがとうございます。あとは私1人で大丈夫です。",
  ui_story_5046_50460402_47_dialog_content = "ここ2カ月の間火災が頻繁に起こっています。\nですが、そのうち死者が出たのは3件だけ…",
  ui_story_5046_50460402_48_dialog_content = "1件目の被害者はアンドレアス、36歳、無職、男性。\n時どき日雇いで働き、酒におぼれていた。",
  ui_story_5046_50460402_49_dialog_content = "2件目の被害者はフィルマン、42歳、商人、男性。\n商売はずっとかんばしくなかった。",
  ui_story_5046_50460402_50_dialog_content = "3件目の被害者はカルロッタ、31歳、洗濯女。\nこれといった特徴なし。",
  ui_story_5046_50460402_51_dialog_content = "この3名の被害者は全員以前の孤児院で働いていたのですね。\nアンドレアスは経理、フィルマンは配達、カルロッタは清掃員でした。",
  ui_story_5046_50460402_52_dialog_content = "ハーティと3名の被害者との共通点も孤児院です。",
  ui_story_5046_50460402_53_dialog_content = "まさかハーティは昔孤児院で被害者たちにいじめられていたのでしょうか？\nそれで恨みをもち、報復をしたと？",
  ui_story_5046_50460402_54_dialog_content = "もう少し詳しく以前の孤児院の人事資料を調べてみましょう。",
  ui_story_5046_50460402_55_dialog_content = "以前の孤児院で働いていた人たちは火災後散り散りになっています。\n誰かに当時の状況を聞くにもとっかかりがありません。",
  ui_story_5046_50460402_56_dialog_content = "どうしたらよいでしょう…？",
  ui_story_5046_50460402_57_dialog_content = "「ハーメル氏は長きにわたり孤児院に寄付をし、\n定期的に慈善活動を催しては孤児院のため寄付を募ってきた…」",
  ui_story_5046_50460402_58_dialog_content = "ハーメル氏！？",
  ui_story_5046_50460402_59_dialog_content = "<color=#e8d9bb>孤児院内</color>",
  ui_story_5046_50460402_60_dialog_content = "ハーメルさん、数分ほどお時間をいただけますか？",
  ui_story_5046_50460402_61_dialog_content = "クリステンさん！空の末裔殿が見つかったのですか！？\nそれはよかった！",
  ui_story_5046_50460402_62_dialog_content = "いいえ、今のところ空の末裔さんの行方はまだわかっていません。\nただ、黒い凶星についてお聞きしたいことがあり、まいりました。",
  ui_story_5046_50460402_63_dialog_content = "あの放火犯のことですかな？",
  ui_story_5046_50460402_64_dialog_content = "放火犯黒い凶星はハーティである可能性が非常に高く、\nしかも前の孤児院の従業員と確執があり、犯行に及んだ可能性があります。",
  ui_story_5046_50460402_65_dialog_content = "あなたは前の孤児院に長年寄付をされ、募金の慈善活動も行っていらっしゃいました。\n孤児院の事情にお詳しいかと思いまして…",
  ui_story_5046_50460402_66_dialog_content = "お考えをお伺いしたいと思ったのです。",
  ui_story_5046_50460402_67_dialog_content = "確かに…私は長年孤児院に資金援助し、募金活動を行ってきました。",
  ui_story_5046_50460402_68_dialog_content = "しかし、具体的なことはすべて孤児院の院長と従業員が計画しておったのです。\n私は当日顔を出すだけでしてな。",
  ui_story_5046_50460402_69_dialog_content = "孤児院から定期的に出納明細が送られてきてはおりましたが、\nその他のことはよく分からんのですよ。",
  ui_story_5046_50460402_70_dialog_content = "ですが、今あなたは新しい孤児院の院長であり、\n以前の孤児院とも関係が深い…",
  ui_story_5046_50460402_71_dialog_content = "容疑者の目的が本当に孤児院関係者への報復であった場合、\n次のターゲットとして最も可能性が高いのがあなたなのです。",
  ui_story_5046_50460402_72_dialog_content = "どうかよく思い出してみてください。\n一刻も早い容疑者逮捕につながる可能性があるのです。",
  ui_story_5046_50460402_73_dialog_content = "それと、しばらくは白夜城衛兵が駐留する所にお泊りください。",
  ui_story_5046_50460402_74_dialog_content = "容疑者がいつお命を狙ってくるかわかりません。\n白夜城の衛兵がお守りしましょう。",
  ui_story_5046_50460402_75_dialog_content = "クリステンさん、あなたのおっしゃることは推測にすぎんでしょう？",
  ui_story_5046_50460402_76_dialog_content = "この孤児院は影ノ街で最も大きい孤児院ですぞ。\n関係者などたくさんおります。",
  ui_story_5046_50460402_77_dialog_content = "この辺りに住むほとんどの者が孤児院の関係者だと言っても\n過言ではありませんぞ。",
  ui_story_5046_50460402_78_dialog_content = "建設に携わった者、清掃員、さらには孤児院の入口前に\n屋台を出して食べ物を売っていた者…",
  ui_story_5046_50460402_79_dialog_content = "容疑者はそうした者たちにまで報復するというのですかな？",
  ui_story_5046_50460402_80_dialog_content = "そ、それは…",
  ui_story_5046_50460402_81_dialog_content = "ただの偶然でしょう。",
  ui_story_5046_50460402_82_dialog_content = "そんな偶然に時間を使うくらいなら、\n一刻も早く容疑者を逮捕してくださった方が皆のためというものです。",
  ui_story_5046_50460402_83_dialog_content = "もうこんな時間ですから、年寄りは休むことにしましょう。",
  ui_story_5046_50460402_84_dialog_content = "申し訳ございません。お邪魔しました、失礼いたします。",
  ui_story_5046_50460402_85_dialog_content = "では、お気をつけて。",
  ui_story_5046_50460402_86_dialog_content = "お久しぶりですね。",
  ui_story_5046_50460402_87_dialog_content = "あんたか。",
  ui_story_5046_50460402_88_dialog_content = "私に会えて、嬉しくないのですか？",
  ui_story_5046_50460402_89_dialog_content = "私に会いにきたわけではなかろう。\n<color=#FFB400>アレ</color>が目的だろうが。",
  ui_story_5046_50460501_1_dialog_content = "ハーメルさんの態度、どこかおかしいですね…\n何か隠していらっしゃるようです。",
  ui_story_5046_50460501_2_dialog_content = "でも、細かいことはお話しになりたがらない…",
  ui_story_5046_50460501_3_dialog_content = "容疑者ハーティ、さらわれた空の末裔、\nリハーサル会場の油のタルと引火装置…",
  ui_story_5046_50460501_4_dialog_content = "旧孤児院の火災とハーメル氏の秘密…",
  ui_story_5046_50460501_5_dialog_content = "すべて偶然なのでしょうか？",
  ui_story_5046_50460501_6_dialog_content = "はぁ…糸口がまったくつかめません。",
  ui_story_5046_50460501_7_dialog_content = "先生がいらっしゃれば、きっとすぐに――",
  ui_story_5046_50460501_8_dialog_content = "お嬢様、お呼びですか？",
  ui_story_5046_50460501_9_dialog_content = "せ、先生！？",
  ui_story_5046_50460501_10_dialog_content = "いつお戻りになったのですか？",
  ui_story_5046_50460501_11_dialog_content = "しばらくになります。独り言をおっしゃりながら、\n何か真剣にお考えのようだったので黙っておりました。",
  ui_story_5046_50460501_12_dialog_content = "申し訳ございません。気づきませんでした…",
  ui_story_5046_50460501_13_dialog_content = "それはそうと、先生！\n調査の結果、重要な発見がありました！",
  ui_story_5046_50460501_14_dialog_content = "おや？どのような発見でしょう？",
  ui_story_5046_50460501_15_dialog_content = "リハーサル会場で救助された女の子の話では、\nうっかり何かの箱を落としてしまったことで火災が起こったそうです。",
  ui_story_5046_50460501_16_dialog_content = "思うに、その箱とは引火装置でしょう。\n特定の時間に倉庫に置かれた油に引火するよう設定されていたのです。",
  ui_story_5046_50460501_17_dialog_content = "犯人は引火装置を置いたものの、\n女の子の出現によって計画を乱されてしまったのでしょう。",
  ui_story_5046_50460501_18_dialog_content = "特定の時間に火災を起こす…\nその目的は何でしょうか？",
  ui_story_5046_50460501_19_dialog_content = "これまでの調査から、過去2カ月に起こった火災のうち、\n死傷者が出たのは3件のみです。",
  ui_story_5046_50460501_20_dialog_content = "そして、その3名の被害者は全員、旧孤児院で働いていました。",
  ui_story_5046_50460501_21_dialog_content = "今日火災現場に現れたハーティも\nかつて旧孤児院に1か月間いたことがあります。",
  ui_story_5046_50460501_22_dialog_content = "以上のことから推測するに、ハーティは以前孤児院で何かひどい目に遭い、\n孤児院関係者に恨みを抱いたのではないでしょうか？",
  ui_story_5046_50460501_23_dialog_content = "炎の力の制御を失い、旧孤児院の大火事を起した後、\nシャドウマスターの邸宅に引き取られ、報復計画は中止せざるを得ませんでしたが――",
  ui_story_5046_50460501_24_dialog_content = "2カ月前邸宅を出た後すぐに報復を始めました。",
  ui_story_5046_50460501_25_dialog_content = "今日の火災現場にも\n長年孤児院に資金援助をされていたハーメル氏がいらっしゃいました。",
  ui_story_5046_50460501_26_dialog_content = "つまり、ハーティのターゲットはハーメル氏だと疑っておられるのですね。",
  ui_story_5046_50460501_27_dialog_content = "はい。すべて推測であり、確固たる根拠はありません。",
  ui_story_5046_50460501_28_dialog_content = "ですからハーメル氏を訪ね、\n捜査に協力してもらおうとした、というわけですか。",
  ui_story_5046_50460501_29_dialog_content = "はい…",
  ui_story_5046_50460501_30_dialog_content = "ハーメル氏はすべて偶然に過ぎないとおっしゃいましたが、\n私にはハーメル氏が何か隠しているように思えてならないのです。",
  ui_story_5046_50460501_31_dialog_content = "お嬢様はいつも一歩先まで考えておられますね。",
  ui_story_5046_50460501_32_dialog_content = "先生、どういうことでしょう？",
  ui_story_5046_50460501_33_dialog_content = "善悪の入り混じる影ノ街で、財産や地位を得た人物はたいてい\n何かしらの秘密をもっているものです。",
  ui_story_5046_50460501_34_dialog_content = "そうした秘密は彼らの命も同然です。\n他人、特に白夜城の者には知られたくないのです。",
  ui_story_5046_50460501_35_dialog_content = "ハーメル氏を守りたいというお気持ちは分かりますが、\nお嬢様のやり方はかえって相手を警戒させてしまいます。",
  ui_story_5046_50460501_36_dialog_content = "ハーメル氏が捜査に協力せず、警護もさせてもらえないばかりか、\n容疑者はお嬢様の意図に気づき、さらに深く身を隠してしまいます。",
  ui_story_5046_50460501_37_dialog_content = "私の配慮が足りませんでした…\n申し訳ございません。",
  ui_story_5046_50460501_38_dialog_content = "やはり私では…先生のお力にはなれないのですね。",
  ui_story_5046_50460501_39_dialog_content = "ただし、お嬢様の推測には根拠があると考えます。\n決してすべてが偶然なわけではありません。",
  ui_story_5046_50460501_40_dialog_content = "私の推測は正しいとおっしゃるのですか？",
  ui_story_5046_50460501_41_dialog_content = "当然です。長い間ずっとおそばで成長を見守ってまいりました。\nお嬢様の能力は私が一番存じあげています。",
  ui_story_5046_50460501_42_dialog_content = "資料の中から糸口を見つけ出し、完璧な証拠の連鎖を編み上げる――\nお嬢様の能力はすばらしいものです。",
  ui_story_5046_50460501_43_dialog_content = "せ、先生…",
  ui_story_5046_50460501_44_dialog_content = "それもこれも先生の教えのおかげです！",
  ui_story_5046_50460501_45_dialog_content = "…",
  ui_story_5046_50460501_46_dialog_content = "オホン…それはそうと、先生は容疑者とPlayerNameさんの行方を\n追っていたのではないのですか？",
  ui_story_5046_50460501_47_dialog_content = "ええ。バー・ファイアフライという酒場の主は、\nハーティの友人であることを突き止めました。",
  ui_story_5046_50460501_48_dialog_content = "ただ、口が堅く、何も聞き出せませんでした。\nバーの付近を見張らせているので、何かつかめるといいのですが。",
  ui_story_5046_50460501_49_dialog_content = "ううっ…",
  ui_story_5046_50460501_50_dialog_content = "先生！どうされたのです！？やけどが痛むのですか？",
  ui_story_5046_50460501_51_dialog_content = "私のせいです。私のせいで、先生におケガを…",
  ui_story_5046_50460501_52_dialog_content = "大丈夫です。このくらいの傷なんともありません。",
  ui_story_5046_50460501_53_dialog_content = "ハーメル氏が次のターゲットと推測されるからには、\n急ぎ戻って手配しなければなりません…",
  ui_story_5046_50460501_54_dialog_content = "時間はもう多く残されてはいません…",
  ui_story_5046_50460501_55_dialog_content = "うっ！",
  ui_story_5046_50460501_56_dialog_content = "先生、無理をなさってはいけません！",
  ui_story_5046_50460501_57_dialog_content = "初めてお会いした時、先生は満身創いになってまで、\n私を火の海から救ってくださいました。",
  ui_story_5046_50460501_58_dialog_content = "今日もそうです。私がやみくもに火を消そうとし、\nかえって危険を招いた時かばってくださった…",
  ui_story_5046_50460501_59_dialog_content = "私にも先生のために何かさせてください！",
  ui_story_5046_50460501_60_dialog_content = "お嬢様…",
  ui_story_5046_50460501_61_dialog_content = "お嬢様とお呼びにならないでください。",
  ui_story_5046_50460501_62_dialog_content = "いつまでも守られているだけの、\n温室育ちのお嬢様でいるつもりはありません。",
  ui_story_5046_50460501_63_dialog_content = "私も白夜城に正義をもたらす裁判官に、\n先生のように信頼に足る者になりたいのです。",
  ui_story_5046_50460501_64_dialog_content = "そこに至るまでの道のりが遠いことはよくわかっています。\nですが、第一歩を踏み出さなければ、永遠に変われません。",
  ui_story_5046_50460501_65_dialog_content = "ほんの小さな一歩であろうとも、\n前に進みつづけなければならないのです。",
  ui_story_5046_50460501_66_dialog_content = "で、ですから、ハーメル氏の警護は私にお任せください！",
  ui_story_5046_50460501_67_dialog_content = "フフ…",
  ui_story_5046_50460501_68_dialog_content = "お嬢様…",
  ui_story_5046_50460501_69_dialog_content = "いいえ、クリステン。",
  ui_story_5046_50460501_70_dialog_content = "ご立派なご覚悟です。その決意に深く感動いたしました。",
  ui_story_5046_50460501_71_dialog_content = "（えっ…！？なぜ、こんなにもたれかかってくるのでしょう…？）",
  ui_story_5046_50460501_72_dialog_content = "（先生の息づかいが伝わってくる…）",
  ui_story_5046_50460501_73_dialog_content = "（髪が顔に触れて、くすぐったい…）",
  ui_story_5046_50460501_74_dialog_content = "クリステン、あなたの私への思いも十分伝わりましたよ…",
  ui_story_5046_50460501_75_dialog_content = "（お、思い…！？先生は何をおっしゃってるのでしょう！？）",
  ui_story_5046_50460501_76_dialog_content = "（ま、まさか！）",
  ui_story_5046_50460501_77_dialog_content = "私はクリステンのことが…",
  ui_story_5046_50460501_78_dialog_content = "せ、先生！",
  ui_story_5046_50460501_79_dialog_content = "ハーメル氏の警護に行かなければ！",
  ui_story_5046_50460501_80_dialog_content = "必ず立派に務めを果たしてみせます！",
  ui_story_5046_50460501_81_dialog_content = "フフ…",
  ui_story_5046_50460501_82_dialog_content = "あなたの頭脳と勇気があれば、\n立派に任務を果たせると信じています。",
  ui_story_5046_50460501_83_dialog_content = "ありがとうございます！",
  ui_story_5046_50460501_84_dialog_content = "必ず務めを果たし、先生のご期待に応えてご覧にいれます！",
  ui_story_5046_50460501_85_dialog_content = "<color=#e8d9bb>影ノ街郊外</color>",
  ui_story_5046_50460501_86_dialog_content = "森で一番背の高いメープルの木はこの先だ。",
  ui_story_5046_50460501_87_dialog_content = "着いたの？",
  ui_story_5046_50460501_88_dialog_content = "森の中の道は歩きにくいから…",
  ui_story_5046_50460501_89_dialog_content = "うわ！",
  ui_story_5046_50460501_90_dialog_content = "…つまづかないようにな。",
  ui_story_5046_50460501_91_dialog_content = "アイタタタタタタ！！",
  ui_story_5046_50460501_92_dialog_content = "座りな。",
  ui_story_5046_50460501_93_dialog_content = "大丈夫だよ。大したことないから。",
  ui_story_5046_50460501_94_dialog_content = "座りな。",
  ui_story_5046_50460501_95_dialog_content = "（すごい威圧感…なんか、断れない…）",
  ui_story_5046_50460501_96_dialog_content = "分かった。じゃあ、ちょっと座らせてもらうね。",
  ui_story_5046_50460501_97_dialog_content = "ズボンのすそをまくれ。",
  ui_story_5046_50460501_98_dialog_content = "どういうこと？",
  ui_story_5046_50460501_99_dialog_content = "痛みをやわらげてやる。",
  ui_story_5046_50460501_100_dialog_content = "大して痛くないから…あっ！ぼ、僕が自分でまくるよ！",
  ui_story_5046_50460501_101_dialog_content = "これでいい？",
  ui_story_5046_50460501_102_dialog_content = "ああ。この辺りか？押すと痛いか？",
  ui_story_5046_50460501_103_dialog_content = "そこは大して痛くないよ。それにしても君の手、熱いね。\n森の中はずいぶん冷え込んでるのに。",
  ui_story_5046_50460501_104_dialog_content = "ボクは体温が高い。寒いなら少し近づきな。",
  ui_story_5046_50460501_105_dialog_content = "（ハーティって一見冷たそうだけど、本当は優しいんだな。\nしゃがむとフワフワした耳が揺れてて可愛らしいし…）",
  ui_story_5046_50460501_106_dialog_content = "（転ばないように注意してくれたり、\n足を痛めたら、マッサージしてくれたり…）",
  ui_story_5046_50460501_107_dialog_content = "ああ？どうしたんだ？",
  ui_story_5046_50460501_108_dialog_content = "な、何でもないよ！",
  ui_story_5046_50460501_109_dialog_content = "約束の時間までまだあるから、\nここでひと休みしよう。",
  ui_story_5046_50460501_110_dialog_content = "そうだね。",
  ui_story_5046_50460501_111_dialog_content = "…",
  ui_story_5046_50460501_112_dialog_content = "…",
  ui_story_5046_50460501_113_dialog_content = "（き、気まずい…何か話さなきゃ…）",
  ui_story_5046_50460501_114_dialog_content = "ねえ、お母さんのこと話してくれる？",
  ui_story_5046_50460501_115_dialog_content = "べ、別に何か意図があるわけじゃないんだ！",
  ui_story_5046_50460501_116_dialog_content = "僕のお母さんは僕が生まれて間もなくいなくなっちゃったから、\nどんな人だったか覚えてなくて…",
  ui_story_5046_50460501_117_dialog_content = "…",
  ui_story_5046_50460501_118_dialog_content = "…話したくないなら、いいんだ！",
  ui_story_5046_50460501_119_dialog_content = "…",
  ui_story_5046_50460501_120_dialog_content = "失くした記憶を取り戻したいって気持ち、\n実はよく分かるんだ。",
  ui_story_5046_50460501_121_dialog_content = "…",
  ui_story_5046_50460501_122_dialog_content = "生まれてから何年もの間、僕を育ててくれたのはソラヴァンだった。",
  ui_story_5046_50460501_123_dialog_content = "ソラヴァンは巨像だけど、僕の親友であり、先生なんだ。",
  ui_story_5046_50460501_124_dialog_content = "長い間ずっとソラヴァンが一緒にいてくれて、\n外の世界の知識も教えてくれたし、気が塞がないようにおしゃべりもしてくれた。",
  ui_story_5046_50460501_125_dialog_content = "でも、今はもう僕のこと覚えてないんだ。",
  ui_story_5046_50460501_126_dialog_content = "ソラヴァンも記憶を失ったのか？",
  ui_story_5046_50460501_127_dialog_content = "僕を助けるために、記憶を全部失ったんだ。\nだから今僕はソラヴァンの記憶を取り戻す方法を探してるんだよ。",
  ui_story_5046_50460501_128_dialog_content = "グリムの言った通り、僕たちは少し似てるかもね。",
  ui_story_5046_50460501_129_dialog_content = "2人とも記憶のために頑張ってるから。",
  ui_story_5046_50460501_130_dialog_content = "だから君の気持ち、よく分かる。\n早くお母さんの記憶を取り戻せるといいね。",
  ui_story_5046_50460501_131_dialog_content = "…",
  ui_story_5046_50460501_132_dialog_content = "ソラヴァンの記憶を取り戻すのに、\n手伝えることがあれば、何でも言ってくれ。",
  ui_story_5046_50460501_133_dialog_content = "ありがとう。でも手伝うにはまず容疑を晴らさなきゃね！",
  ui_story_5046_50460501_134_dialog_content = "ロケットペンダントを取り戻したら、\n皆にきちんと説明するんだよ。",
  ui_story_5046_50460501_135_dialog_content = "チッ…面倒くせえ。",
  ui_story_5046_50460501_136_dialog_content = "面倒臭くてもやらなきゃ！",
  ui_story_5046_50460501_137_dialog_content = "分かったよ。",
  ui_story_5046_50460501_138_dialog_content = "約束だよ！",
  ui_story_5046_50460501_139_dialog_content = "グアア――！",
  ui_story_5046_50460501_140_dialog_content = "暗鬼が集まってきてる！数も多い…",
  ui_story_5046_50460501_141_dialog_content = "グガァ！！",
  ui_story_5046_50460501_142_dialog_content = "気をつけて。",
  ui_story_5046_50460501_143_dialog_content = "ふん、アンタ弱っちいな。",
  ui_story_5046_50460501_144_dialog_content = "空の末裔は戦えないんだよ！",
  ui_story_5046_50460501_145_dialog_content = "よわ。",
  ui_story_5046_50460501_146_dialog_content = "僕をバカにしちゃいけないよ。\nそれより、左方向から暗鬼が向かってくる！",
  ui_story_5046_50460501_147_dialog_content = "グオオオ――！",
  ui_story_5046_50460501_148_dialog_content = "たたっ切ってやる！",
  ui_story_5046_50460501_149_dialog_content = "どう！？戦闘能力はないけど、\n僕にはカレンにも認められた指揮能力があるんだよ！",
  ui_story_5046_50460501_150_dialog_content = "だったら背後に隠れて指揮に集中しな！",
  ui_story_5046_50460502_1_dialog_content = "ダメだ、暗鬼が多すぎる…",
  ui_story_5046_50460502_2_dialog_content = "はぁ…はぁ…",
  ui_story_5046_50460502_3_dialog_content = "こんな所でやられるわけにはいかない…",
  ui_story_5046_50460502_4_dialog_content = "グギギ…",
  ui_story_5046_50460502_5_dialog_content = "また暗鬼が向かってくる！",
  ui_story_5046_50460502_6_dialog_content = "クソッ！このままじゃラチが明かない…",
  ui_story_5046_50460502_7_dialog_content = "<color=#e8d9bb>ボンッ――</color>",
  ui_story_5046_50460502_8_dialog_content = "グオオオオオオ！",
  ui_story_5046_50460502_9_dialog_content = "わ！暗鬼が…全部焼けこげちゃった！？",
  ui_story_5046_50460502_10_dialog_content = "周りにはもう暗鬼の気配はしない。",
  ui_story_5046_50460502_11_dialog_content = "はぁ…はぁ…",
  ui_story_5046_50460502_12_dialog_content = "うわっ！",
  ui_story_5046_50460502_13_dialog_content = "お前…やはりこの力を使うんだな…",
  ui_story_5046_50460502_14_dialog_content = "キキッ…",
  ui_story_5046_50460502_15_dialog_content = "お前の嫌いな自分に…なったな…",
  ui_story_5046_50460502_16_dialog_content = "だから母さんは…離れて行った…俺たちの元から…",
  ui_story_5046_50460502_17_dialog_content = "黙るんだ！黙れ！！",
  ui_story_5046_50460502_18_dialog_content = "ハーティ！？どうしたの！？",
  ui_story_5046_50460502_19_dialog_content = "（ハーティが目をつむったまま地面に転がってもがいてる。\nすごくつらそうな顔をしてる…）",
  ui_story_5046_50460502_20_dialog_content = "黙れって言ってるだろ！",
  ui_story_5046_50460502_21_dialog_content = "母さん…ボクは悪い子じゃない…悪い子じゃないよ…",
  ui_story_5046_50460502_22_dialog_content = "母さん？過去の記憶にとらわれちゃったの？",
  ui_story_5046_50460502_23_dialog_content = "このままじゃいけない！\n感知能力で介入してハーティを助けなきゃ！",
  ui_story_5046_50460502_24_dialog_content = "ごめん、ハーティ。君の記憶を勝手に探る気はないけど…",
  ui_story_5046_50460502_25_option_content = "強制感知！",
  ui_story_5046_50460502_26_dialog_content = "（ここはどこだろう？）",
  ui_story_5046_50460502_27_dialog_content = "母さん！服にトゲ玉がくっついてるよ。\n取ってあげる。",
  ui_story_5046_50460502_28_dialog_content = "ありがとう、ハーティ。",
  ui_story_5046_50460502_29_dialog_content = "あなたは本当にいい子ね。",
  ui_story_5046_50460502_30_dialog_content = "えへへ…",
  ui_story_5046_50460502_31_dialog_content = "お外で母さんと遊べてうれしいな。",
  ui_story_5046_50460502_32_dialog_content = "（小さい頃のハーティかな？あれはお母さん？）",
  ui_story_5046_50460502_33_dialog_content = "…",
  ui_story_5046_50460502_34_dialog_content = "ごめんね、ハーティ。",
  ui_story_5046_50460502_35_dialog_content = "なんで母さんがあやまるの？\n母さんは何もわるいことしてないよ。",
  ui_story_5046_50460502_36_dialog_content = "いいえ…母さんが悪いの。",
  ui_story_5046_50460502_37_dialog_content = "母さんはわるくないよ…",
  ui_story_5046_50460502_38_dialog_content = "お外で自由に遊ばせてあげればいいのに、\nどうして私は…",
  ui_story_5046_50460502_39_dialog_content = "フェンリル…私は正しかったのかしら…",
  ui_story_5046_50460502_40_dialog_content = "母さん、泣いてるの…？ボクのせい…？",
  ui_story_5046_50460502_41_dialog_content = "だったら、ボクもうお外で遊ばないよ…",
  ui_story_5046_50460502_42_dialog_content = "大丈夫よ。母さんは大丈夫…さあ、楽しく遊びましょう！",
  ui_story_5046_50460502_43_dialog_content = "目を閉じて3つ数えたら、\n母さんがハーティを捕まえちゃうわよ！",
  ui_story_5046_50460502_44_dialog_content = "うん！",
  ui_story_5046_50460502_45_dialog_content = "3…",
  ui_story_5046_50460502_46_dialog_content = "ガァ…",
  ui_story_5046_50460502_47_dialog_content = "真っ黒いもんが母さんに近づいてく…",
  ui_story_5046_50460502_48_dialog_content = "2…",
  ui_story_5046_50460502_49_dialog_content = "母さんをおそう気だ…",
  ui_story_5046_50460502_50_dialog_content = "1…",
  ui_story_5046_50460502_51_dialog_content = "<color=#e8d9bb>ボン！</color>",
  ui_story_5046_50460502_52_dialog_content = "！！！",
  ui_story_5046_50460502_53_dialog_content = "ハーティ！？",
  ui_story_5046_50460502_54_dialog_content = "母さん！こいつ悪いやつだよ！",
  ui_story_5046_50460502_55_dialog_content = "ハーティが火の球にしたよ！",
  ui_story_5046_50460502_56_dialog_content = "やーいっ！",
  ui_story_5046_50460502_57_dialog_content = "なぜ…炎は使っちゃいけないって言ったでしょ！？",
  ui_story_5046_50460502_58_dialog_content = "なぜ言うことを聞けないの！",
  ui_story_5046_50460502_59_dialog_content = "でも…母さんが…",
  ui_story_5046_50460502_60_dialog_content = "すぐにお家に帰るわよ！",
  ui_story_5046_50460502_61_dialog_content = "うえええん…なんでだよ…",
  ui_story_5046_50460502_62_dialog_content = "火遊びするボクは…嫌いなの…？",
  ui_story_5046_50460502_63_dialog_content = "（母さんはハーティが嫌いなんだ…炎が嫌いなんだ…）",
  ui_story_5046_50460502_64_dialog_content = "（ハーティは悪い子だ…）",
  ui_story_5046_50460502_65_dialog_content = "（悪い子だ…）",
  ui_story_5046_50460502_66_dialog_content = "（ボクは…悪い子？）",
  ui_story_5046_50460502_67_dialog_content = "（違うよ！ハーティは悪い子じゃない！）",
  ui_story_5046_50460502_68_dialog_content = "（君は大切な人を守るために力を使ったんだ。\nお母さんは力を使っちゃいけないって言っただけ…）",
  ui_story_5046_50460502_69_dialog_content = "（ハーティが悪い子だってことにはならない！）",
  ui_story_5046_50460502_70_dialog_content = "（ハーティは…悪い子じゃない？）",
  ui_story_5046_50460502_71_dialog_content = "（お母さんはきっと他のことで悩んでて、\nだから、つい大きな声をあげただけだ…）",
  ui_story_5046_50460502_72_dialog_content = "（お母さんを守るために炎の力を使ったハーティは、\nとってもカッコよかったよ！）",
  ui_story_5046_50460502_73_dialog_content = "（さっき僕を守るために炎を使ったハーティもそう。\nすっごくカッコいい！）",
  ui_story_5046_50460502_74_dialog_content = "（ハーティはすっごくいい子だ！）",
  ui_story_5046_50460502_75_dialog_content = "（ボクが…いい子？）",
  ui_story_5046_50460502_76_dialog_content = "（そうだよ。ハーティはいい子だよ。\nさあ、気持ちを落ち着けて、ゆっくり目を覚ますんだ…）",
  ui_story_5046_50460502_77_dialog_content = "…",
  ui_story_5046_50460502_78_dialog_content = "PlayerNameか？",
  ui_story_5046_50460502_79_dialog_content = "うん、もう大丈夫だね？",
  ui_story_5046_50460502_80_dialog_content = "ああ…",
  ui_story_5046_50460502_81_dialog_content = "ごめん、迷惑かけた。",
  ui_story_5046_50460502_82_dialog_content = "謝るのは僕の方だよ。",
  ui_story_5046_50460502_83_dialog_content = "君の許可もなく、感知能力で君の記憶に介入した…",
  ui_story_5046_50460502_84_dialog_content = "怒らないでね！",
  ui_story_5046_50460502_85_dialog_content = "さっきは…アンタがいなかったら…",
  ui_story_5046_50460502_86_dialog_content = "たぶん、完全に理性を失ってた。",
  ui_story_5046_50460502_87_dialog_content = "ありがとうございます。",
  ui_story_5046_50460502_88_dialog_content = "急にそんなに優しくなられたら、\nかえって居たたまれないな…",
  ui_story_5046_50460502_89_dialog_content = "時間も時間だよ。急いでメープルの木の所へ行こう。",
  ui_story_5046_50460502_90_dialog_content = "取引が成立した後も、\n記憶を取り戻すのに僕の手伝いが必要なら…",
  ui_story_5046_50460502_91_dialog_content = "その時は…巨像を訪ねてくるといいよ。",
  ui_story_5046_50460502_92_dialog_content = "分かった。",
  ui_story_5046_50460502_93_dialog_content = "それと、約束だよ。ちゃんと皆に事情を説明して、\n容疑を晴らすんだ…",
  ui_story_5046_50460502_94_dialog_content = "そうじゃないと君が僕を訪ねてくる前に、\n他の誰かが懸賞金目当てに君を捕まえちゃうから…",
  ui_story_5046_50460502_95_dialog_content = "約束する。",
  ui_story_5046_50460502_96_dialog_content = "絶対だよ？",
  ui_story_5046_50460502_97_dialog_content = "絶対だ。",
  ui_story_5046_50460601_1_dialog_content = "（朝、白夜城の衛兵を孤児院に遣わしましたが、\nハーメル氏は追い返そうともしませんでした）",
  ui_story_5046_50460601_2_dialog_content = "（そればかりか、衛兵を連れて影ノ街を出て、\nこの森にやってきました…）",
  ui_story_5046_50460601_3_dialog_content = "（さらにPlayerNameさんとハーティが現れ、双方が戦い始めました…）",
  ui_story_5046_50460601_4_dialog_content = "（ですが、衛兵のこの戦い方…白夜城のものとは違います。\n確かに白夜城衛兵の制服を着てはいますが…）",
  ui_story_5046_50460601_5_dialog_content = "（いっちどういうことでしょう…？）",
  ui_story_5046_50460601_6_dialog_content = "（今止めに入っても何にもなりません。\nやはりここに隠れて様子をみることにいたしましょう）",
  ui_story_5046_50460601_7_dialog_content = "はぁ…はぁ…これでもまだ死なんのか。",
  ui_story_5046_50460601_8_dialog_content = "ハーメルさん！？何を言ってるんですか！？\nどうしてここへ？",
  ui_story_5046_50460601_9_dialog_content = "ゼナスはどうしたんですか？\nゼナスは手紙を受け取ってないんですか？",
  ui_story_5046_50460601_10_dialog_content = "お前に命を奪われるくらいなら、私がお前を倒してやる！",
  ui_story_5046_50460601_11_dialog_content = "アンドレアスもフィルマンもカルロッタも、\n全部お前が殺したのであろう？",
  ui_story_5046_50460601_12_dialog_content = "孤児院でのことを根に持って、私たちに復讐しているのだろう？",
  ui_story_5046_50460601_13_dialog_content = "あの日リハーサルで、一気に私たちを片付けようとした、\nそうであろうが！",
  ui_story_5046_50460601_14_dialog_content = "残念だったな。計画は失敗だ。",
  ui_story_5046_50460601_15_dialog_content = "アンタの言った人たちのことなんて知らないさ。\nリハーサルの日も通りかかっただけだ。",
  ui_story_5046_50460601_16_dialog_content = "まだとぼける気か！お前は私と…うっ！",
  ui_story_5046_50460601_17_dialog_content = "あぶない！",
  ui_story_5046_50460601_18_dialog_content = "（ハーメルさんが倒れました！ハーティが殺したのでしょうか！？）",
  ui_story_5046_50460601_19_dialog_content = "ハーメルさん！？しっかりしてください。",
  ui_story_5046_50460601_20_dialog_content = "もう死んでるよ。",
  ui_story_5046_50460601_21_dialog_content = "ハーティ・ケルピー！\nあなたを殺人の容疑で直ちに影ノ街に連れ帰り、尋問いたします！",
  ui_story_5046_50460601_22_dialog_content = "クリステン？どうしてここに？",
  ui_story_5046_50460601_23_dialog_content = "こいつはボクがやったんじゃない。",
  ui_story_5046_50460601_24_dialog_content = "犯人は誰でもそう言うものです。",
  ui_story_5046_50460601_25_dialog_content = "ハーティの言ってることは本当だよ。僕が証明する。\nハーメルさんは突然倒れたんだよ…",
  ui_story_5046_50460601_26_dialog_content = "PlayerNameさん、なぜ殺人犯をかばおうとなさるのですか？",
  ui_story_5046_50460601_27_dialog_content = "ハーティは斧を手にしています。\nそれが凶器であることは明らかです…",
  ui_story_5046_50460601_28_dialog_content = "本当だよ！",
  ui_story_5046_50460601_29_dialog_content = "それでも弁解なさるというのなら、私と一緒に法廷へいらしてください。",
  ui_story_5046_50460601_30_dialog_content = "見習い裁判官といえど、正義のため罪を見逃すわけにはまいりません。",
  ui_story_5046_50460601_31_dialog_content = "ダメだ。まだアンタと一緒に行くわけにはいかない。",
  ui_story_5046_50460601_32_dialog_content = "同行を拒否すれば罪はさらに重くなります。",
  ui_story_5046_50460601_33_dialog_content = "好きにすればいいさ。",
  ui_story_5046_50460601_34_dialog_content = "2人ともちょっと落ち着いてよ！",
  ui_story_5046_50460601_35_dialog_content = "クリステン！無事ですか？",
  ui_story_5046_50460601_36_dialog_content = "ふん、マスク野郎。やっと現れたか。",
  ui_story_5046_50460601_37_dialog_content = "こ、これは…ハーメル様ではありませんか！？",
  ui_story_5046_50460601_38_dialog_content = "ハーティ？なるほど…ハーメル様を殺した犯人はお前だな。\nクリステン、逮捕しなさい。",
  ui_story_5046_50460601_39_dialog_content = "ちょ、ちょっと待ってよ！本当にハーティじゃないんだ！",
  ui_story_5046_50460601_40_dialog_content = "やるのか？いいよ、つきやってやる！",
  ui_story_5046_50460601_41_dialog_content = "PlayerNameさん、そこは危険です！\n早くこちらへいらしてください！",
  ui_story_5046_50460601_42_dialog_content = "受けてみろ！",
  ui_story_5046_50460601_43_dialog_content = "鈍いな。",
  ui_story_5046_50460601_44_dialog_content = "<color=#e8d9bb>カタン</color>",
  ui_story_5046_50460601_45_dialog_content = "マスクが…",
  ui_story_5046_50460601_46_dialog_content = "そ、その顔は…！？",
  ui_story_5046_50460601_47_dialog_content = "誰だ！？いったい誰なんだ！？",
  ui_story_5046_50460601_48_dialog_content = "ハーティ！どうしたの！？",
  ui_story_5046_50460601_49_dialog_content = "ぼ、ボクは…うう…うわあ！",
  ui_story_5046_50460601_50_dialog_content = "<color=#e8d9bb>「あの日…」</color>",
  ui_story_5046_50460601_51_dialog_content = "<color=#e8d9bb>「この顔を見た」</color>",
  ui_story_5046_50460601_52_dialog_content = "<color=#e8d9bb>「あの日…」</color>",
  ui_story_5046_50460601_53_dialog_content = "<color=#e8d9bb>「ボクの…母さんに…何があったんだ？」</color>",
  ui_story_5046_50460601_54_dialog_content = "うわああああ！！",
  ui_story_5046_50460601_55_dialog_content = "ハーティ！？ハーティ！",
  ui_story_5046_50460601_56_dialog_content = "先生、様子がおかしいようです！",
  ui_story_5046_50460601_57_dialog_content = "あああああああ！！！",
  ui_story_5046_50460601_58_dialog_content = "ハーティ！ハーティ！僕の声が聞こえる！？",
  ui_story_5046_50460601_59_dialog_content = "しっかりして！",
  ui_story_5046_50460601_60_dialog_content = "ううっ！！",
  ui_story_5046_50460601_61_dialog_content = "<color=#e8d9bb>パチパチ――</color>",
  ui_story_5046_50460601_62_dialog_content = "姿が変わった…！？しかも体から火が出ています！",
  ui_story_5046_50460601_63_dialog_content = "気を付けるのです！クリステン、後ろへ下がって！",
  ui_story_5046_50460601_64_dialog_content = "ガオオオオ！！",
  ui_story_5046_50460601_65_dialog_content = "ハーティ！！！",
  ui_story_5046_50460601_66_dialog_content = "（ハーティの今の姿…記憶の中でみた心の闇そっくりだ…）",
  ui_story_5046_50460601_67_dialog_content = "（まさか、心の闇に心身をのっとられたの！？\nこのままじゃいけない！意識を取り戻させなきゃ！）",
  ui_story_5046_50460601_68_dialog_content = "PlayerNameさん！こちらへいらしてください！\nハーティは今とても危険な状態です！",
  ui_story_5046_50460601_69_dialog_content = "大丈夫、ハーティが僕を傷つけることはないよ！\n今ハーティには僕が必要なんだ！",
  ui_story_5046_50460601_70_dialog_content = "ハーティ、落ち着いて！",
  ui_story_5046_50460601_71_dialog_content = "ガオオオオ！！",
  ui_story_5046_50460601_72_dialog_content = "無駄です！何を言っても今のハーティには聞こえません！",
  ui_story_5046_50460601_73_dialog_content = "早くこちらへいらしてください！",
  ui_story_5046_50460601_74_dialog_content = "PlayerName…",
  ui_story_5046_50460601_75_dialog_content = "今、僕の名前を呼んだ！？",
  ui_story_5046_50460601_76_dialog_content = "ダメだ、このまま放っておけない！",
  ui_story_5046_50460601_77_dialog_content = "（どうしたら僕の声が届くんだろう…？）",
  ui_story_5046_50460601_78_dialog_content = "（そうだ、僕にはこの手が…）",
  ui_story_5046_50460601_79_option_content = "強制感知！",
  ui_story_5046_50460601_80_dialog_content = "（ハーティ！落ち着くんだ！）",
  ui_story_5046_50460601_81_dialog_content = "（PlayerNameか？あ…あの男の顔を見たら…\n自分を抑えられなくなっちまった…）",
  ui_story_5046_50460601_82_dialog_content = "（頭がすごく痛いんだ。うう、うわああ――）",
  ui_story_5046_50460601_83_dialog_content = "（どうすればいい…？どうすればいいんだ…？）",
  ui_story_5046_50460601_84_dialog_content = "（とにかく、ここを離れよう。どこか落ち着ける所を探すんだ）",
  ui_story_5046_50460601_85_dialog_content = "（一緒に…来てくれるのか？）",
  ui_story_5046_50460601_86_dialog_content = "（僕も一緒に行くよ！）",
  ui_story_5046_50460601_87_dialog_content = "2人を逃がしてはいけません！ううっ！",
  ui_story_5046_50460601_88_dialog_content = "先生、ケガをされているのです。\n動いてはいけません。",
  ui_story_5046_50460601_89_dialog_content = "PlayerName様は？",
  ui_story_5046_50460601_90_dialog_content = "ハーティが連れて行ってしまいました…",
  ui_story_5046_50460601_91_dialog_content = "なんと！また逃げられましたか！",
  ui_story_5046_50460601_92_dialog_content = "私のマスクはどこですか？",
  ui_story_5046_50460601_93_dialog_content = "私が探してきますから、先生は動かないでください！",
  ui_story_5046_50460601_94_dialog_content = "（先生の顔の傷…）",
  ui_story_5046_50460601_95_dialog_content = "大変です！火事です！",
  ui_story_5046_50460601_96_dialog_content = "お嬢様！お嬢様がまだ中に！",
  ui_story_5046_50460601_97_dialog_content = "まだ中に人がいるのですか？",
  ui_story_5046_50460601_98_dialog_content = "どうかお願いいたします！\nクリステンお嬢様をどうかお助けください！",
  ui_story_5046_50460601_99_dialog_content = "ゴホ、ゴホゴホッ…",
  ui_story_5046_50460601_100_dialog_content = "お父様…お母様…どこ…？",
  ui_story_5046_50460601_101_dialog_content = "お嬢さん！",
  ui_story_5046_50460601_102_dialog_content = "だ…誰…？",
  ui_story_5046_50460601_103_dialog_content = "ようやく見つけました。怖がらないで大丈夫ですよ。\n火の外にお連れします。",
  ui_story_5046_50460601_104_dialog_content = "お嬢様、ご無事でしたか！",
  ui_story_5046_50460601_105_dialog_content = "私は大丈夫。ありがとうございます…あっ！",
  ui_story_5046_50460601_106_dialog_content = "まあ！お顔にひどい傷が！すぐに手当てしないといけません！",
  ui_story_5046_50460601_107_dialog_content = "私ですか？申し訳ございません。\nお嬢さんを驚かしてしまいましたね。",
  ui_story_5046_50460601_108_dialog_content = "ご、ごめんなさい。助けてもらったのに…ケガを…",
  ui_story_5046_50460601_109_dialog_content = "大丈夫です。あなたが無事なら、それでよいのです。",
  ui_story_5046_50460601_110_dialog_content = "あの…お名前は…？",
  ui_story_5046_50460601_111_dialog_content = "ゼナスと申します。",
  ui_story_5046_50460601_112_dialog_content = "今日から私がお嬢様の家庭教師を務めさせていただきます。",
  ui_story_5046_50460601_113_dialog_content = "うれしいです、先生！",
  ui_story_5046_50460601_114_dialog_content = "没落貴族である私をいとうことなく、\nお父上に推薦してくださったこと、感謝いたします。",
  ui_story_5046_50460601_115_dialog_content = "先生は貴族出身なのですか？",
  ui_story_5046_50460601_116_dialog_content = "はい。これが我が一族の家紋でございます。",
  ui_story_5046_50460601_117_dialog_content = "とても変わった紋様ですね。",
  ui_story_5046_50460601_118_dialog_content = "もう没落した一族です。一文の価値もございません。",
  ui_story_5046_50460601_119_dialog_content = "<color=#e8d9bb>「それから先生はずっと私のそばにいて、教え導いてくれました」</color>",
  ui_story_5046_50460601_120_dialog_content = "<color=#e8d9bb>「途中先生は家庭教師の職を辞し、\n白夜城に行き、職に就かれました」</color>",
  ui_story_5046_50460601_121_dialog_content = "<color=#e8d9bb>「私は黎明学院を卒業後、白夜城法廷に入り、先生のおそばで務めを果たしています」</color>",
  ui_story_5046_50460601_122_dialog_content = "先生、マスクです。",
  ui_story_5046_50460601_123_dialog_content = "ふぅ…",
  ui_story_5046_50460601_124_dialog_content = "ハーティはハーメル氏を殺害し、\n再び空の末裔をさらっていきました。",
  ui_story_5046_50460601_125_dialog_content = "すぐにハーティの逃走した方向に衛兵を遣わし、\n追跡を強化しなければなりません。",
  ui_story_5046_50460601_126_dialog_content = "はい、先生！",
  ui_story_5046_50460601_127_dialog_content = "クリステン、あなたはここまでで結構です。",
  ui_story_5046_50460601_128_dialog_content = "えっ？",
  ui_story_5046_50460601_129_dialog_content = "事件はこの後ますます危険度を増すでしょう。\nあなたを巻き込みたくはありません。",
  ui_story_5046_50460601_130_dialog_content = "それに、ハーメル氏の件でも分かるように、\n経験の浅いあなたには容疑者と渡り合うのは難しいでしょう。",
  ui_story_5046_50460601_131_dialog_content = "先生を除いて、一連の事件に詳しい者は私の他におりません。\nどうか引き続きお手伝いをさせてください。",
  ui_story_5046_50460601_132_dialog_content = "もう決めたことです。この事件は私一人で対応します。",
  ui_story_5046_50460601_133_dialog_content = "あなたは今までに得た情報を整理し、\n白夜城法廷に報告書を提出してください。",
  ui_story_5046_50460601_134_dialog_content = "ですが、先生…！",
  ui_story_5046_50460601_135_dialog_content = "もう結構です。お嬢様といえど、私の部下であることをお忘れなく。",
  ui_story_5046_50460601_136_dialog_content = "指示に従いなさい！",
  ui_story_5046_50460601_137_dialog_content = "…はい。",
  ui_story_5046_50460601_138_dialog_content = "少々きつい言葉になってしまいましたが、\nそれもこれもあなたの安全のためです。",
  ui_story_5046_50460601_139_dialog_content = "先に帰っていてください。",
  ui_story_5046_50460601_140_dialog_content = "容疑者の追跡を初めて任せていただいたのに、\n私のせいで逃げられてしまいました…",
  ui_story_5046_50460601_141_dialog_content = "先生は引き続き私が関与することを許してくださいませんでしたが、\n真相はこの手で突き止めなければ。",
  ui_story_5046_50460601_142_dialog_content = "それに…一連の事件には疑問点がたくさんあります…",
  ui_story_5046_50460601_143_dialog_content = "火事を起こしたのがハーティなら、\nなぜ火事現場からPlayerNameさんと女の子を救い出したのでしょう？",
  ui_story_5046_50460601_144_dialog_content = "そして先程のことも不思議です。\nなぜ人質のPlayerNameさんがハーティをかばい、逃走を助けたのでしょう？",
  ui_story_5046_50460601_145_dialog_content = "ハーメル氏は殺される直前、ハーティの狙いは自分以外に\nもう1人いると言っていました。",
  ui_story_5046_50460601_146_dialog_content = "その人物が誰かを突き止めれば、\nハーティの足取りもつかめるはずです。",
  ui_story_5046_50460601_147_dialog_content = "先生、今度こそ証明してみせます。\n私はもう温室育ちのお嬢様ではありません！",
  ui_story_5046_50460601_148_dialog_content = "必ず自身の力で、先生のお力になってみせます！",
  ui_story_5046_50460701_1_dialog_content = "（うう、布団が湿ってる。気持ちわるい）",
  ui_story_5046_50460701_2_dialog_content = "（また雨漏りか？この前の家はこんなんじゃなかったのに）",
  ui_story_5046_50460701_3_dialog_content = "母さん？母さん？",
  ui_story_5046_50460701_4_dialog_content = "（母さん、寝ちゃったのか？）",
  ui_story_5046_50460701_5_dialog_content = "（母さん、いつも出掛けてばかりだ。\n帰ってくれば食事を作って、家事をして…きっと疲れたんだろう）",
  ui_story_5046_50460701_6_dialog_content = "（ボクはもう大きくなったんだ！母さんに迷惑かけちゃいけない！）",
  ui_story_5046_50460701_7_dialog_content = "（布団は自分で干そう！）",
  ui_story_5046_50460701_8_dialog_content = "（目を覚ました時、ボクが自分で自分のことやってるの見たら、\n母さんきっと喜ぶね！）",
  ui_story_5046_50460701_9_dialog_content = "（ハーティはいい子ねって、きっとほめてくれるよ！）",
  ui_story_5046_50460701_10_dialog_content = "<color=#e8d9bb>パタンパタン</color>",
  ui_story_5046_50460701_11_dialog_content = "（ふぅ…これでいいんだよね？\n母さんはいつもどれくらい干しとくんだろう？）",
  ui_story_5046_50460701_12_dialog_content = "（母さんが目を覚ます前に乾くといいな！）",
  ui_story_5046_50460701_13_dialog_content = "お布団、お布団、早く乾け～！",
  ui_story_5046_50460701_14_dialog_content = "お布団、お布団…",
  ui_story_5046_50460701_15_dialog_content = "早くカラッカラに乾け～！",
  ui_story_5046_50460701_16_dialog_content = "<color=#e8d9bb>パチパチ――</color>",
  ui_story_5046_50460701_17_dialog_content = "うわああ！！！",
  ui_story_5046_50460701_18_dialog_content = "なんで火が勝手に！？",
  ui_story_5046_50460701_19_dialog_content = "母さんに見られたら、怒られちゃう！",
  ui_story_5046_50460701_20_dialog_content = "消さなきゃ！火を消さなきゃ！",
  ui_story_5046_50460701_21_dialog_content = "ハーティ？何をしてるの？",
  ui_story_5046_50460701_22_dialog_content = "ううっ、母さん！",
  ui_story_5046_50460701_23_dialog_content = "（母さん、ボクを怖がってるみたいだ…早く謝るんだ！）",
  ui_story_5046_50460701_24_dialog_content = "ごめんなさい。ただお布団を干そうと思っただけなんだよ…",
  ui_story_5046_50460701_25_dialog_content = "ひ、火をつけようと思ったわけじゃないんだ…火が勝手に…",
  ui_story_5046_50460701_26_dialog_content = "ケガはない！？",
  ui_story_5046_50460701_27_dialog_content = "大丈夫だよ…母さん…ボク、本当にわざとじゃないんだ…",
  ui_story_5046_50460701_28_dialog_content = "わざと母さんにダメって言われたことやったわけじゃ…",
  ui_story_5046_50460701_29_dialog_content = "ハーティ、よく聞いて！\n今後二度とこの力は使わないで！",
  ui_story_5046_50460701_30_dialog_content = "分かった！？",
  ui_story_5046_50460701_31_dialog_content = "（母さん…すごく怒ってる…）",
  ui_story_5046_50460701_32_dialog_content = "でも、ボクはただ母さんの手伝いを…わざとじゃないんだ…",
  ui_story_5046_50460701_33_dialog_content = "うわあああああん！",
  ui_story_5046_50460701_34_dialog_content = "あなたはまだこの力をうまく制御できないの…",
  ui_story_5046_50460701_35_dialog_content = "強大な力なの。だから、ちょっとした不注意で\nあなた自身を傷つけてしまうのよ…",
  ui_story_5046_50460701_36_dialog_content = "しかも、その力を奪おうとする人がいるの…\nそんなことになれば、ハーティ、あなたもケガをしてしまうわ…",
  ui_story_5046_50460701_37_dialog_content = "だから、この力は二度と使っちゃダメ。\nいい？分かったわね？",
  ui_story_5046_50460701_38_dialog_content = "ぐすっ…分かったよ…",
  ui_story_5046_50460701_39_dialog_content = "（母さん…）",
  ui_story_5046_50460701_40_dialog_content = "<color=#e8d9bb>「母さん、ボクの力がそんなに怖いの？」</color>",
  ui_story_5046_50460701_41_dialog_content = "<color=#e8d9bb>「母さん、ボクのことがそんなに怖いの？」</color>",
  ui_story_5046_50460701_42_dialog_content = "<color=#e8d9bb>「ボクは母さんのことが一番好きなのに！」</color>",
  ui_story_5046_50460701_43_dialog_content = "ううっ、うわあああ！",
  ui_story_5046_50460701_44_dialog_content = "（母さんは…ハーティのこと要らないんだ…）",
  ui_story_5046_50460701_45_dialog_content = "（だってハーティは…言うこと聞かないから…）",
  ui_story_5046_50460701_46_dialog_content = "ボクは…ううっ…母さん…ああああ…！",
  ui_story_5046_50460701_47_dialog_content = "ハーティ、しっかりして！",
  ui_story_5046_50460701_48_dialog_content = "（ハーティが記憶の中に閉じ込められちゃったみたいだ）",
  ui_story_5046_50460701_49_dialog_content = "（心の闇がずっとハーティの耳元でささやいてるのを感じる…）",
  ui_story_5046_50460701_50_dialog_content = "心の闇に立ち向かわない限り、\nハーティはずっと記憶の中にとらわれたままだ…",
  ui_story_5046_50460701_51_dialog_content = "このまま過去にとらわれて、目を覚ませなかったら大変だ。",
  ui_story_5046_50460701_52_dialog_content = "助けてあげなきゃ！",
  ui_story_5046_50460701_53_option_content = "強制感知！",
  ui_story_5046_50460701_54_dialog_content = "（ここは…ハーティの家かな）",
  ui_story_5046_50460701_55_dialog_content = "ハーティ！何をしてるの！",
  ui_story_5046_50460701_56_dialog_content = "か、母さん？",
  ui_story_5046_50460701_57_dialog_content = "何をしてるのって聞いてるの！",
  ui_story_5046_50460701_58_dialog_content = "あ、あの子たち、お外で何してるのかなって\n見てみたかっただけだよ。",
  ui_story_5046_50460701_59_dialog_content = "窓を閉めなさい！今すぐよ！",
  ui_story_5046_50460701_60_dialog_content = "でも、ボクもお外で遊びたい。",
  ui_story_5046_50460701_61_dialog_content = "そのことはもう話したでしょ？何度言ったら分かるの？",
  ui_story_5046_50460701_62_dialog_content = "ううっ…",
  ui_story_5046_50460701_63_dialog_content = "なんでお外で遊ばせてくれないんだ！",
  ui_story_5046_50460701_64_dialog_content = "母さんはいつもボクを守るためだって…\nだからお外で遊んじゃいけないって言うけど…",
  ui_story_5046_50460701_65_dialog_content = "理由をぜんぜん教えてくれない！",
  ui_story_5046_50460701_66_dialog_content = "…",
  ui_story_5046_50460701_67_dialog_content = "新しいお家、ボロボロで寒いし、\n何もないじゃん！",
  ui_story_5046_50460701_68_dialog_content = "絵本があるでしょう？本を読んでなさい。",
  ui_story_5046_50460701_69_dialog_content = "もうあきるほど読んだよ！",
  ui_story_5046_50460701_70_dialog_content = "ご本の中の子どもたちはいつも一緒に遊んでるよ。\nお友だちのお家にも遊びに行ってる…",
  ui_story_5046_50460701_71_dialog_content = "母さんが本に書いてあるみたいに他人とおしゃべりして、\nお買い物して、お礼を言いなさいって教えてくれたのに…",
  ui_story_5046_50460701_72_dialog_content = "…",
  ui_story_5046_50460701_73_dialog_content = "ぜんぜん使えないよ！",
  ui_story_5046_50460701_74_dialog_content = "だってお外に出してくれないから！",
  ui_story_5046_50460701_75_dialog_content = "あなたに色々教えたのは…",
  ui_story_5046_50460701_76_dialog_content = "母さんがそばにいなくなっても、\nハーティが一人でちゃんと暮らしていけるようになってほしいからよ。",
  ui_story_5046_50460701_77_dialog_content = "なんで母さんはそばにいてくれないの？",
  ui_story_5046_50460701_78_dialog_content = "…",
  ui_story_5046_50460701_79_dialog_content = "なんでそんな悲しそうな顔するの？",
  ui_story_5046_50460701_80_dialog_content = "誰かにいじめられたの？",
  ui_story_5046_50460701_81_dialog_content = "ハーティはもう大きいんだよ！",
  ui_story_5046_50460701_82_dialog_content = "母さんをいじめるような悪いやつは、\nハーティがやっつけてやる！",
  ui_story_5046_50460701_83_dialog_content = "やっつけられないなら、\nそいつらを燃やしちゃえばいいんだ！",
  ui_story_5046_50460701_84_dialog_content = "！",
  ui_story_5046_50460701_85_dialog_content = "<color=#e8d9bb>バシッ！</color>",
  ui_story_5046_50460701_86_dialog_content = "か…母さん？",
  ui_story_5046_50460701_87_dialog_content = "そういうことしちゃダメだって言ったの忘れたの！？",
  ui_story_5046_50460701_88_dialog_content = "母さんが…ボクをぶった…",
  ui_story_5046_50460701_89_dialog_content = "なんでいけないんだよ！？",
  ui_story_5046_50460701_90_dialog_content = "なんでだよ！なんで、なんでだよ！",
  ui_story_5046_50460701_91_dialog_content = "（なぜ…いけないのか…）",
  ui_story_5046_50460701_92_dialog_content = "<color=#e8d9bb>ヒュ――</color>",
  ui_story_5046_50460701_93_dialog_content = "！？",
  ui_story_5046_50460701_94_dialog_content = "うわぁああ！",
  ui_story_5046_50460701_95_dialog_content = "ハーティ、あなた…！",
  ui_story_5046_50460701_96_dialog_content = "か、母さん？ボクの…体から…炎が…",
  ui_story_5046_50460701_97_dialog_content = "母さんとハーティのロケットペンダント、おそろいだね。",
  ui_story_5046_50460701_98_dialog_content = "これ、なに？",
  ui_story_5046_50460701_99_dialog_content = "このロケットペンダントはね、\nとても大切なものなのよ。",
  ui_story_5046_50460701_100_dialog_content = "ハーティ、大切にしてね。",
  ui_story_5046_50460701_101_dialog_content = "うん！",
  ui_story_5046_50460701_102_dialog_content = "でも、なんでペンダントが大切なの？",
  ui_story_5046_50460701_103_dialog_content = "…このロケットペンダントが…大切なのはね…",
  ui_story_5046_50460701_104_dialog_content = "…身に付けて…いると…",
  ui_story_5046_50460701_105_dialog_content = "（この部分の記憶…はっきりしてない…）",
  ui_story_5046_50460701_106_dialog_content = "母さん、何してるの？どうして、そんなに怖い顔してるの？",
  ui_story_5046_50460701_107_dialog_content = "今日って、ボクの誕生日だよね？\nイチゴのケーキが食べたいな！",
  ui_story_5046_50460701_108_dialog_content = "…ハーティ…よく聞いて…",
  ui_story_5046_50460701_109_dialog_content = "もう時間がないわ。お話ししてる時間がないの。",
  ui_story_5046_50460701_110_dialog_content = "このペンダントを肌身離さず持っているのよ。\n絶対に失くしてはダメ。",
  ui_story_5046_50460701_111_dialog_content = "母さん、何言ってるの？よく分からないよ。",
  ui_story_5046_50460701_112_dialog_content = "悪い人が…悪い人が来るの。",
  ui_story_5046_50460701_113_dialog_content = "悪い人？いったい誰？",
  ui_story_5046_50460701_114_dialog_content = "母さん、悪い人って誰のこと？",
  ui_story_5046_50460701_115_dialog_content = "母さん、何するつもりなの？母さん！？",
  ui_story_5046_50460701_116_dialog_content = "うあああ――！",
  ui_story_5046_50460701_117_dialog_content = "<color=#e8d9bb>「母さん、悪い人って誰のこと？」</color>",
  ui_story_5046_50460701_118_dialog_content = "<color=#e8d9bb>「悪い人が来るからって、どうしてボクを…」</color>",
  ui_story_5046_50460701_119_dialog_content = "<color=#e8d9bb>「母さんは、ボクが悪い人だって思ってるの？」</color>",
  ui_story_5046_50460701_120_dialog_content = "<color=#e8d9bb>「だから、ボクを焼き殺すの…？」</color>",
  ui_story_5046_50460701_121_dialog_content = "<color=#e8d9bb>「そうなんでしょ？母さん…」</color>",
  ui_story_5046_50460701_122_dialog_content = "（やっと分かったか…ハーティ…）",
  ui_story_5046_50460701_123_dialog_content = "（母さんの言ってた悪い人は…お前だ…）",
  ui_story_5046_50460701_124_dialog_content = "（この力を忌み嫌い…この力に飲み込まれた…俺たちのことだ…）",
  ui_story_5046_50460701_125_dialog_content = "俺たち…？",
  ui_story_5046_50460701_126_dialog_content = "ハーティ！ハーティ！",
  ui_story_5046_50460701_127_dialog_content = "誰だ…？",
  ui_story_5046_50460701_128_dialog_content = "僕だよ！PlayerNameだよ！",
  ui_story_5046_50460701_129_dialog_content = "PlayerName？アンタも…ボクを見捨てるのか？",
  ui_story_5046_50460701_130_dialog_content = "（PlayerName…お前の大好きなPlayerName…）",
  ui_story_5046_50460701_131_dialog_content = "（こいつもお前を見捨てていく…）",
  ui_story_5046_50460701_132_dialog_content = "（自身の火を制御できず…そこらじゅうに火をつけて回るやつなんて…\n誰が好いてくれるというんだ…？）",
  ui_story_5046_50460701_133_dialog_content = "（母さんを怒らせてばかりで…母さんに捨てられたハーティを…\n誰が好いてくれるというんだ？）",
  ui_story_5046_50460701_134_dialog_content = "母さんはボクのこと愛してないんだ…誰もボクのことなんて…",
  ui_story_5046_50460701_135_dialog_content = "違うよ！",
  ui_story_5046_50460701_136_dialog_content = "ハーティが力を使うのは、いつだって大切な人のためだ！",
  ui_story_5046_50460701_137_dialog_content = "お母さんが暗鬼に傷つけられないように…\nお母さんがゆっくり休めるように布団を乾かしたり…",
  ui_story_5046_50460701_138_dialog_content = "暗鬼の群れの中から、まったく戦闘能力のない僕を助けてくれたり…",
  ui_story_5046_50460701_139_dialog_content = "大切な人のために、許されない力を使ったんだ…",
  ui_story_5046_50460701_140_dialog_content = "そんなハーティは、心のとってもきれいな、\n他人の気持ちの分かるいい子だ！",
  ui_story_5046_50460701_141_dialog_content = "僕はそんなハーティが好きだよ！",
  ui_story_5046_50460701_142_dialog_content = "君のお母さんもきっとそうだ！",
  ui_story_5046_50460701_143_dialog_content = "ハーティのお母さんは絶対に、\n可愛くて、心のきれいなハーティのことを心から愛してるよ！",
  ui_story_5046_50460701_144_dialog_content = "母さんが…ボクを愛してる？",
  ui_story_5046_50460701_145_dialog_content = "（そいつは…お前をだましてるんだ…）",
  ui_story_5046_50460701_146_dialog_content = "僕はハーティをだましてなんかいない！",
  ui_story_5046_50460701_147_dialog_content = "お前こそずっとハーティをイジメてるじゃないか！\n悪いやつはお前の方だ！",
  ui_story_5046_50460701_148_dialog_content = "ハーティ、一緒にこいつを倒そう！",
  ui_story_5046_50460702_1_dialog_content = "ボク…勝ったの？",
  ui_story_5046_50460702_2_dialog_content = "（お前…本当に…勝ったか…？）",
  ui_story_5046_50460702_3_dialog_content = "（いいや…お前はまだここにいる…俺もまだここにいる…）",
  ui_story_5046_50460702_4_dialog_content = "（お前はまだ…本当には…自分を受け入れられていない…）",
  ui_story_5046_50460702_5_dialog_content = "アンタ…いったい何者だ？",
  ui_story_5046_50460702_6_dialog_content = "（また…会おう…）",
  ui_story_5046_50460702_7_dialog_content = "ハーティ！！",
  ui_story_5046_50460702_8_dialog_content = "はあ…はあ…",
  ui_story_5046_50460702_9_dialog_content = "あ、PlayerName…？",
  ui_story_5046_50460702_10_dialog_content = "よかった。ようやく気がついたんだね。",
  ui_story_5046_50460702_11_dialog_content = "…",
  ui_story_5046_50460702_12_dialog_content = "ありがとう。またアンタに救われた。",
  ui_story_5046_50460702_13_dialog_content = "お礼なんて必要ないよ。\n君だって僕を暗鬼から救ってくれたじゃないか。",
  ui_story_5046_50460702_14_dialog_content = "…",
  ui_story_5046_50460702_15_dialog_content = "あのマスク野郎からペンダントを取り返したいのは、\nあれは母さんのものだからだ。",
  ui_story_5046_50460702_16_dialog_content = "小さい頃からボクは他の子どもたちとは違ってた。\nいつだって遠くから窓越しに見てるだけ、外には出られなかった。",
  ui_story_5046_50460702_17_dialog_content = "ボクの世界には、母さんしかいなかったんだ。",
  ui_story_5046_50460702_18_dialog_content = "いつも母さんがボクと遊んでくれて、読み書きも教えてくれた。\nお話も聞かせてくれた…ぜんぶ母さんがしてくれたんだ…",
  ui_story_5046_50460702_19_dialog_content = "ボクは母さんが大好きだ。でも、母さんは…\nボクみたいにボクを愛してなかったのかもしれない。",
  ui_story_5046_50460702_20_dialog_content = "どうしてそう思うの…？",
  ui_story_5046_50460702_21_dialog_content = "記憶の中のボクたちはいつも引っ越してばかりで、\n一つ所に長く留まってたことはないんだ。",
  ui_story_5046_50460702_22_dialog_content = "母さんがボクを見る目にはよく恐怖が浮かんでた。\nボクを外に出してくれることもなかった。",
  ui_story_5046_50460702_23_dialog_content = "一番長く住んだのは最後の家だよ。\nボクの子ども時代が終わった場所でもあるんだ。",
  ui_story_5046_50460702_24_dialog_content = "ハーティ…",
  ui_story_5046_50460702_25_dialog_content = "ボクはいつも逃げてばかりだ。\nあの日の記憶から逃げてばかりだ。でも、忘れられやしないよ。",
  ui_story_5046_50460702_26_dialog_content = "8月26日…ボクの誕生日だった。",
  ui_story_5046_50460702_27_dialog_content = "！？",
  ui_story_5046_50460702_28_dialog_content = "ハーティ…",
  ui_story_5046_50460702_29_dialog_content = "時どき怖かったけど、母さんはボクに優しかった。",
  ui_story_5046_50460702_30_dialog_content = "前の日から材料を準備して、\n誕生日にはイチゴのショートケーキを一緒に作るんだ。",
  ui_story_5046_50460702_31_dialog_content = "あの日も母さんはいつも通り早起きしてたけど、\n何だか気分が沈んでるみたいだった。",
  ui_story_5046_50460702_32_dialog_content = "誕生日おめでとう、とだけ言って、\nすぐに忙しそうに何か準備し始めたんだ。",
  ui_story_5046_50460702_33_dialog_content = "ボクがケーキ食べたいってゴネても、\n母さんは何も答えてくれなかった。",
  ui_story_5046_50460702_34_dialog_content = "それから母さんはボクを暖炉の中に突き飛ばした。\n母さんはボクを焼き殺そうとしたんだ。",
  ui_story_5046_50460702_35_dialog_content = "どうしてそんなことを！？",
  ui_story_5046_50460702_36_dialog_content = "暖炉の中に入れられた後のことは、よく覚えてない。\n次に気が付いた時には、もう孤児院にいた。",
  ui_story_5046_50460702_37_dialog_content = "初めて、他のたくさんの子どもたちと一緒に過ごした…",
  ui_story_5046_50460702_38_dialog_content = "ずっと外に出て、他の子たちと遊びたいって思ってたけど、\nそんな形で実現するとはな。",
  ui_story_5046_50460702_39_dialog_content = "ボクは孤児院で他の子どもたちや大人と仲良くしようとしたけど、\nみんなは良くしてくれなかった。",
  ui_story_5046_50460702_40_dialog_content = "子ども同士のケンカはしょっちゅうだったし、\n先生たちも子どもたちに優しいわけじゃない。",
  ui_story_5046_50460702_41_dialog_content = "孤児院で嫌なことがあって、\n母さんに聞いてもらいたかったけど、母さんはどこにもいなかった。",
  ui_story_5046_50460702_42_dialog_content = "そうして、ようやく気づいたんだ。\nボクは母さんに捨てられたんだって。",
  ui_story_5046_50460702_43_dialog_content = "あの晩、孤児院の人がボクが眠ってる間にボクに何かしようとして、\n思いっきりあがいたら、片方の耳が切れちゃった。",
  ui_story_5046_50460702_44_dialog_content = "耳を切られるって、本当に痛いんだよ。\n本当に痛かった…",
  ui_story_5046_50460702_45_dialog_content = "それで自分の感情を抑えられなくなって、\n怒りを爆発させたら、孤児院が火の海になっちまったんだ。",
  ui_story_5046_50460702_46_dialog_content = "その後のことはアンタも知ってのとおりさ。\nシャドウマスターの所へ送られて、2カ月前に出てきたんだ。",
  ui_story_5046_50460702_47_dialog_content = "ハーティ…",
  ui_story_5046_50460702_48_dialog_content = "子どもを愛さない親なんていないよ。",
  ui_story_5046_50460702_49_dialog_content = "お母さんはきっと、どんなことがあろうと、\n君に幸せに暮らしてほしいと思ってるはずだ。",
  ui_story_5046_50460702_50_dialog_content = "慰めてくれなくていいよ、PlayerName。",
  ui_story_5046_50460702_51_dialog_content = "愛してくれてたなら、\nどうしてボクを暖炉の中になんて入れたんだ？",
  ui_story_5046_50460702_52_dialog_content = "でもハーティだって、そんなふうには思ってないんでしょ？",
  ui_story_5046_50460702_53_dialog_content = "じゃなければ、こんなに一生懸命失った記憶を\n取り戻そうなんてしないよ。",
  ui_story_5046_50460702_54_dialog_content = "ハーティも心のどこかでお母さんは\n自分を愛してくれてるって信じてるんだよね？",
  ui_story_5046_50460702_55_dialog_content = "…",
  ui_story_5046_50460702_56_dialog_content = "…そうね。",
  ui_story_5046_50460702_57_dialog_content = "さっきボクが自分を抑えられなくなった時、\nアンタなんで隙を見て、あいつらと逃げなかったんだ？",
  ui_story_5046_50460702_58_dialog_content = "それは…君には僕の助けが必要だと思ったからだよ。",
  ui_story_5046_50460702_59_dialog_content = "グリム以外でこんな風にボクを助けてくれる人は初めてだ。",
  ui_story_5046_50460702_60_dialog_content = "友だちなら、お互い励まし合うのが当たり前でしょ。",
  ui_story_5046_50460702_61_dialog_content = "友だち？ボクに友だちはいない。",
  ui_story_5046_50460702_62_dialog_content = "じゃあ今から僕は君の友だちだ。",
  ui_story_5046_50460702_63_dialog_content = "シャドウマスターの所を離れてから2カ月間ずっと、\n記憶を取り戻そうと頑張ってきたんだよね。",
  ui_story_5046_50460702_64_dialog_content = "でも、外の世界はすごく広いんだ。\n君の知らないことがまだまだたくさんある。",
  ui_story_5046_50460702_65_dialog_content = "記憶を取り戻したら、巨像に遊びに来てよ！",
  ui_story_5046_50460702_66_dialog_content = "一緒に世界中を回ろうよ！\n今まで外で遊べなかった分取り返すんだ！",
  ui_story_5046_50460702_67_dialog_content = "…",
  ui_story_5046_50460702_68_dialog_content = "約束だよ？",
  ui_story_5046_50460702_69_dialog_content = "…",
  ui_story_5046_50460702_70_dialog_content = "分かった。",
  ui_story_5046_50460801_1_dialog_content = "（ハーメル氏が死の直前に話していたことも、\n氏の言う最後の生き残りという人物もすべて孤児院と関係があります）",
  ui_story_5046_50460801_2_dialog_content = "（今のところ他に手がかりはありません。\n容疑者ハーティとPlayerNameさんにも逃げられてしまいました）",
  ui_story_5046_50460801_3_dialog_content = "（この状況では、孤児院を糸口に探っていくしかありません）",
  ui_story_5046_50460801_4_dialog_content = "（再建された孤児院にはほぼ過去の痕跡は残っていません。\nそうすると、手がかりは当時の子どもたちだけですね）",
  ui_story_5046_50460801_5_dialog_content = "白夜城の裁判官だって？人違いでしょ？\nあたしはただの雇われ人だよ。",
  ui_story_5046_50460801_6_dialog_content = "（資料に記録が残っていたのは、たったの2人…\nこの女性はハーティより2つ年上だったはず）",
  ui_story_5046_50460801_7_dialog_content = "（火災後近くの家庭に引き取られ、\n今は白夜城のある貴族の家でメイドをしています）",
  ui_story_5046_50460801_8_dialog_content = "そう緊張なさらないでください。私はただ影ノ街孤児院の火災について、\n当時の状況を知りたいだけなのです。",
  ui_story_5046_50460801_9_dialog_content = "記録によると、あなたは孤児院に長くいらっしゃったのですね？",
  ui_story_5046_50460801_10_dialog_content = "ああ、あのこと。それだったら、もう何回も聞かれたよ。\n今になってなんでまた？",
  ui_story_5046_50460801_11_dialog_content = "あの晩あたしは熟睡していて、他の子どもたちの叫び声で起きたんだよ。\n目を開けた時、あたりはもう火の海だった。",
  ui_story_5046_50460801_12_dialog_content = "新しく来た亜人族が全身から火を出してて、\n隣のベッドの男の子はそいつが火をつけたんだって言ってたっけ。",
  ui_story_5046_50460801_13_dialog_content = "あん時は逃げるので精いっぱいで、\n他のことなんて覚えちゃいないよ。",
  ui_story_5046_50460801_14_dialog_content = "（うーん…かつての証言と食い違いはありませんね。\nいずれもすでに知っている情報です）",
  ui_story_5046_50460801_15_dialog_content = "では、当時そのハーティという亜人族の子は、\n孤児院の誰かに恨みをもっていませんでしたか？",
  ui_story_5046_50460801_16_dialog_content = "孤児院の先生や管理人さんともめていた、といったことはありませんでしたか？",
  ui_story_5046_50460801_17_dialog_content = "それは分からないね。聞いたこともないし。",
  ui_story_5046_50460801_18_dialog_content = "ただ…恨みをもつ？あの子、当時まだ小さかったんだよ。\nあたしよりも年下だったし。",
  ui_story_5046_50460801_19_dialog_content = "孤児院にも1か月くらいしかいなかった。\n誰に恨みをもつっていうの？",
  ui_story_5046_50460801_20_dialog_content = "あえていうなら…孤児院にも成長の早い、身体の大きい子がいてね。\nそういう子は他の子たちに言うこと聞かそうとしてたよ。",
  ui_story_5046_50460801_21_dialog_content = "その亜人族も体が小さかったから、\nそういうガキ大将みたいのにはかなわなかったんじゃない？",
  ui_story_5046_50460801_22_dialog_content = "それに先生たちも子どものケンカなんて放っておいたし、\nすぐヒステリー起こして、ぜんぜん優しくなかったし…",
  ui_story_5046_50460801_23_dialog_content = "あんなとこ好きな子なんていないんじゃない？",
  ui_story_5046_50460801_24_dialog_content = "もう一つお聞きしたいことがあります。",
  ui_story_5046_50460801_25_dialog_content = "孤児院から引き取られていった子どもたちと\n今も連絡はありますか？",
  ui_story_5046_50460801_26_dialog_content = "あなたのいた孤児院では、非常に高い割合で里親がみつかっているのですが、\n里親の方々に関する記録が全くなく、事後訪問もしていません…",
  ui_story_5046_50460801_27_dialog_content = "連絡なんて取ってないよ。",
  ui_story_5046_50460801_28_dialog_content = "当時もよく冗談言ってたんだ。毎月10人近い子どもが引き取られるなんて、\n暗鬼のエサにでもなってるんじゃないかって。",
  ui_story_5046_50460801_29_dialog_content = "毎月10人近い子どもが引き取られていったのですか…？",
  ui_story_5046_50460801_30_dialog_content = "（それは少々不可解ですね…）",
  ui_story_5046_50460801_31_dialog_content = "お時間をいただき、ありがとうございました。",
  ui_story_5046_50460801_32_dialog_content = "（次はこの方ですね。ハーティとほぼ同い年の男性です）",
  ui_story_5046_50460801_33_dialog_content = "（記録では、パン屋の夫婦に引き取られ、一緒に経営をしているとか…）",
  ui_story_5046_50460801_34_dialog_content = "裁判官だって？俺は何もしちゃいねーよ。",
  ui_story_5046_50460801_35_dialog_content = "そう緊張なさらないでください。私はただ影ノ街孤児院の火災について、\n当時の状況をうかがいたいだけなのです。",
  ui_story_5046_50460801_36_dialog_content = "ああ？ずいぶん昔のことだろう？まだ何か調べてんのか？",
  ui_story_5046_50460801_37_dialog_content = "だが、俺は何も知りやしねーぜ。\n覚えてることは全部話したし、調書に載ってるはずだ。",
  ui_story_5046_50460801_38_dialog_content = "だから、商売の邪魔しねーでもらえねえか。",
  ui_story_5046_50460801_39_dialog_content = "それは…",
  ui_story_5046_50460801_40_dialog_content = "当時のことで何か新しい情報を思い出していただけたのなら、\n残りのパンは全部私が購入しましょう。",
  ui_story_5046_50460801_41_dialog_content = "本当か！？",
  ui_story_5046_50460801_42_dialog_content = "そうなりゃ、何かしら思い出さねえといけねーな。",
  ui_story_5046_50460801_43_dialog_content = "ご協力に感謝します。あなたは当時ハーティが火を点けたのを\nご覧になったのですよね？\n状況を詳しくお聞かせ願えませんか？",
  ui_story_5046_50460801_44_dialog_content = "そのことか…俺は小せえ時から眠りが浅くてな。\nあの時もあの亜人族の叫び声がした途端目を覚ましたんだ。",
  ui_story_5046_50460801_45_dialog_content = "ベッドが離れてたからよ、何が起こったのかハッキリ見えた訳じゃねーけど、\n叫び声をあげた後、あいつの全身から火が出たんだ。",
  ui_story_5046_50460801_46_dialog_content = "それから、その火がカーテンに燃え移って、\n火の勢いが大きくなった頃に他の子どもたちも目を覚ましたんだよ。",
  ui_story_5046_50460801_47_dialog_content = "俺は他の子どもたちについて逃げたが、ふくらはぎをやけどしちまった。\nそれは昔事情聴取された時に話したことだ。",
  ui_story_5046_50460801_48_dialog_content = "では、その亜人族のハーティは孤児院の誰かに\n恨みを持っていませんでしたか？",
  ui_story_5046_50460801_49_dialog_content = "最近起こった火災の被害者は皆孤児院の関係者でした。\nですから、彼らとハーティの間に怨恨があったのかどうか知りたいのです。",
  ui_story_5046_50460801_50_dialog_content = "孤児院にはしょっちゅう新しいのが入ってきてな。\nでも、仲も良くなる前に引き取られていっちまうのが常だった。",
  ui_story_5046_50460801_51_dialog_content = "あいつは亜人族だったから、かろうじて覚えてたが、\n誰と怨恨があったかなんて知りやしねーよ。",
  ui_story_5046_50460801_52_dialog_content = "孤児院の大人たちについては…",
  ui_story_5046_50460801_53_dialog_content = "毎日自分の子でもねえ騒がしいガキどもの相手しなきゃいけねーからな。",
  ui_story_5046_50460801_54_dialog_content = "表面的にゃ普通にしてたが、裏で何してたか知れねーぜ。",
  ui_story_5046_50460801_55_dialog_content = "（どうやら孤児院の従業員に対して、\n皆さんいい印象を持っていないようですね…）",
  ui_story_5046_50460801_56_dialog_content = "では、以前孤児院から引き取られていった他の子とは、\n今も連絡がありますか？",
  ui_story_5046_50460801_57_dialog_content = "もしくは、里親となった家庭のことをご存じではありませんか？",
  ui_story_5046_50460801_58_dialog_content = "引き取られた後はまったく連絡なんてねーよ。",
  ui_story_5046_50460801_59_dialog_content = "里親の情報なら…",
  ui_story_5046_50460801_60_dialog_content = "院長がそういうもんを記録してんじゃねーの？",
  ui_story_5046_50460801_61_dialog_content = "そういや、孤児院のセンコーどもはよくノートを持って\n子どもをじっと観察しながら何か書いたり、絵を描いたりしてたな。",
  ui_story_5046_50460801_62_dialog_content = "引き取りの日には、そのガキどもが引き取られていくんだ。",
  ui_story_5046_50460801_63_dialog_content = "今思えば、あのノートには引き取られるガキたちの情報が書かれてたのかもな。\nよく分かんねーけどよ。あんたら裁判官なら手に入んじゃねーの？",
  ui_story_5046_50460801_64_dialog_content = "残念ながら、火事でそのノートも焼けてしまったようです。",
  ui_story_5046_50460801_65_dialog_content = "いずれにせよ、ご協力ありがとうございました。\nお店のパンは全部いただきます。",
  ui_story_5046_50460801_66_dialog_content = "（ふぅ…ようやく大量のパンを処理できました。この後は…）",
  ui_story_5046_50460801_67_dialog_content = "（引き取られた後音信を絶った子どもたちと\n当時まだ子どもだった犯人のハーティについて調べなければ）",
  ui_story_5046_50460801_68_dialog_content = "（いったいどうすれば毎月たくさんの子どもを里親のもとへ送り出せるのでしょう？\nしかもその後音信不通になるとは…）",
  ui_story_5046_50460801_69_dialog_content = "（最悪の可能性は、孤児院の大人たちが\n子どもたちを利用して何かしていたということですが…）",
  ui_story_5046_50460801_70_dialog_content = "（恐ろしい推測ですが…もし本当であれば、\nハーティの放火とハーメル氏殺害もつじつまが合います…）",
  ui_story_5046_50460801_71_dialog_content = "（考えただけでも鳥肌が立ちます。\n旧孤児院にはいったいどれだけの秘密が隠されているのでしょう？）",
  ui_story_5046_50460801_72_dialog_content = "あ…",
  ui_story_5046_50460801_73_dialog_content = "お気を付けください、お嬢さん。",
  ui_story_5046_50460801_74_dialog_content = "ありがとうございます。失礼ですが、あなたは…",
  ui_story_5046_50460801_75_dialog_content = "そこの角にある「バー・ファイアフライ」の店主です。\nグリムと呼んでくださって結構です。",
  ui_story_5046_50460801_76_dialog_content = "グリムさん？ハーティのご友人ですね？\nゼナス先生からお話を聞いています。",
  ui_story_5046_50460801_77_dialog_content = "おや、私をご存じでしたか。ただ、おしゃべりは後にして、\nお願いしたいことがあるんですが？",
  ui_story_5046_50460801_78_dialog_content = "何かあったので…",
  ui_story_5046_50460801_79_dialog_content = "グガアア――！",
  ui_story_5046_50460801_80_dialog_content = "！！！",
  ui_story_5046_50460801_81_dialog_content = "さっき郊外に行ったところ、\n汚らわしいヤツらが付いてきてしまいましてね。",
  ui_story_5046_50460801_82_dialog_content = "暗鬼！？後ろにお気をつけください！",
  ui_story_5046_50460802_1_dialog_content = "さっきは助けていただいてありがとうございました。\nお嬢さんがいなかったら、暗鬼に食われちまうところでしたよ。",
  ui_story_5046_50460802_2_dialog_content = "大したことではありません。\nそれはそうと、ハーティについてお聞きしたいことがございます。",
  ui_story_5046_50460802_3_dialog_content = "もちろん構いませんよ。この先の角が私の店ですから、\n何か飲みながらお話ししましょう。",
  ui_story_5046_50460802_4_dialog_content = "<color=#e8d9bb>チリン――</color>",
  ui_story_5046_50460802_5_dialog_content = "お邪魔します。",
  ui_story_5046_50460802_6_dialog_content = "助けていただいたんですから、遠慮なんていりませんよ。",
  ui_story_5046_50460802_7_dialog_content = "今は営業時間じゃないので、お好きなところにお座りください。\n何をお飲みになります？",
  ui_story_5046_50460802_8_dialog_content = "今は業務時間中ですので。\nそれにお酒はたしなみません。",
  ui_story_5046_50460802_9_dialog_content = "お酒以外にも、いいソフトドリンクがありますよ。",
  ui_story_5046_50460802_10_dialog_content = "ブルー・ハリケーン、影ノ街の香り、白夜のアイスティーなど…",
  ui_story_5046_50460802_11_dialog_content = "結構です。ありがとうございます。\n早速本題に入ってもよろしいですか？",
  ui_story_5046_50460802_12_dialog_content = "ハーティとは、どうやってお知り合いに？",
  ui_story_5046_50460802_13_dialog_content = "ハーティはここで働いてるんで、当然知ってますよ。",
  ui_story_5046_50460802_14_dialog_content = "食材の運搬や厨房の清掃なんかをやってもらってます。\n無駄口もたたかず、勤勉で真面目ないい従業員ですよ。",
  ui_story_5046_50460802_15_dialog_content = "最近起こった数件の火災発生時、ハーティはどこにいましたか？",
  ui_story_5046_50460802_16_dialog_content = "もうずいぶん経ってますからね。\n私もよく覚えちゃいません。",
  ui_story_5046_50460802_17_dialog_content = "ただ、この日は仕入れ日でしたから、よく覚えています。",
  ui_story_5046_50460802_18_dialog_content = "ハーティは厨房で一日中作業してました。\n届いた食材を確認したり、鮮度をチェックしたり、夜になってようやく終わったんです。",
  ui_story_5046_50460802_19_dialog_content = "（フィルマンが被害に遭った日ですね。\nグリムさんの証言が本当なら、ハーティに犯行の時間はありません）",
  ui_story_5046_50460802_20_dialog_content = "（ただ、ハーティをかばっている可能性もあります）",
  ui_story_5046_50460802_21_dialog_content = "お嬢さん、信じてください。本当ですよ。",
  ui_story_5046_50460802_22_dialog_content = "クリステンで結構です。",
  ui_story_5046_50460802_23_dialog_content = "ハーティについて、他に何かご存じですか？",
  ui_story_5046_50460802_24_dialog_content = "たとえば、ハーティが誰かに恨みを持っている、\n復讐するといった類の話をしたことは？",
  ui_story_5046_50460802_25_dialog_content = "ハーティはあまり話したがらない子でしてね。\nしかも知り合って日も浅いので、そんな話は聞いたことありません。",
  ui_story_5046_50460802_26_dialog_content = "（どうやら何も聞き出せそうにありませんね）",
  ui_story_5046_50460802_27_dialog_content = "そうですか。では、お邪魔しました。\nこれで失礼します。",
  ui_story_5046_50460802_28_dialog_content = "特製のジュースでも飲んでいかれませんか？",
  ui_story_5046_50460802_29_dialog_content = "さっきご紹介したものはお好みではなかったようなので、\n話しながら1杯作ってみたんです。",
  ui_story_5046_50460802_30_dialog_content = "これでも影ノ街で一番のバーテンダーなんです。",
  ui_story_5046_50460802_31_dialog_content = "お構いなく…",
  ui_story_5046_50460802_32_dialog_content = "そう冷たくなさらないでくださいよ。1杯飲みながら、\nウソかホントか分からない話を聞くのが影ノ街の暮らしってもんですよ。",
  ui_story_5046_50460802_33_dialog_content = "せっかくですから試してみては？",
  ui_story_5046_50460802_34_dialog_content = "（何か裏がありそうですね…それになぜ、\n急にこんなに近づいてくるのでしょう！？）",
  ui_story_5046_50460802_35_dialog_content = "まだ勤務中ですし、容疑者も捕まっていない状況で飲み物など…",
  ui_story_5046_50460802_36_dialog_content = "道で会った時、あなたは何か悩んでるようでした。\n事件調査が行き詰ってるのでは？",
  ui_story_5046_50460802_37_dialog_content = "そういう時こそ飲み物を口にしながら物語でも聞いて、\nリラックスすると何かひらめくかもしれませんよ。",
  ui_story_5046_50460802_38_dialog_content = "（図星です…）",
  ui_story_5046_50460802_39_dialog_content = "（今の状況では、他に手がかりも見つかりそうもありません。\n話を聞いてみてもよいかもしれません）",
  ui_story_5046_50460802_40_dialog_content = "わかりました。ただし、1杯だけです。",
  ui_story_5046_50460802_41_dialog_content = "フフ、では物語を始めましょうか。",
  ui_story_5046_50460802_42_dialog_content = "10年前影ノ街にはまだシャドウマスターはいませんでした。\nケンカや殺しが日常茶飯事でも放ったらかし。郊外の孤児院となればなおさらです。",
  ui_story_5046_50460802_43_dialog_content = "そんな状況で郊外の孤児院が普通にやっていけてたのは…",
  ui_story_5046_50460802_44_dialog_content = "どんな理由だと思います？",
  ui_story_5046_50460802_45_dialog_content = "秩序の乱れた状況下で孤児院が正常にやっていけるとしたら…\nおそらく善意をもった方が支援してくださっていたのでしょう。",
  ui_story_5046_50460802_46_dialog_content = "その通りです。あの孤児院には確かに出資者がいました。\nしかし、支援の理由は善意じゃありませんよ。",
  ui_story_5046_50460802_47_dialog_content = "孤児院には従業員5人と院長が1人しかいませんでした。\n影ノ街の大物がバックについてるという話も聞いたことはありません。",
  ui_story_5046_50460802_48_dialog_content = "しかも定期的に何人かの子どもが引き取られていき、\n代わりに新しく何人かの子どもが入所する…",
  ui_story_5046_50460802_49_dialog_content = "まるで、このバーの商売みたいじゃないですか。",
  ui_story_5046_50460802_50_dialog_content = "ま、まさか…あの孤児院で\n子どもの人身売買が行われていたというのですか？",
  ui_story_5046_50460802_51_dialog_content = "そうお急ぎにならないでください。\n物語はまだ終わってませんよ。",
  ui_story_5046_50460802_52_dialog_content = "子どもたちは白夜城の貴族の元へ引き取られ、\nかつその貴族たちは今はもう没落しているという話です。",
  ui_story_5046_50460802_53_dialog_content = "ただ、少し前にピアタマンというお役人が\nその数家の貴族を再調査したそうです。",
  ui_story_5046_50460802_54_dialog_content = "ピアタマン先輩が調査なさってるなら、<color=#FFB400>あの事件</color>ですね！",
  ui_story_5046_50460802_55_dialog_content = "従業員5名と院長1名…\n人数は私の調べた旧孤児院の情報と一致しています。",
  ui_story_5046_50460802_56_dialog_content = "旧孤児院の大火災で院長が亡くなり、\n3名の従業員がここ2カ月に発生した火災で亡くなっています…",
  ui_story_5046_50460802_57_dialog_content = "ハーメル氏も旧孤児院と関係がありました。\nさらに氏の話していた人物を加えると…",
  ui_story_5046_50460802_58_dialog_content = "ちょうど5名です！",
  ui_story_5046_50460802_59_dialog_content = "火災で生き残った2人の子どもの証言を合わせると…",
  ui_story_5046_50460802_60_dialog_content = "そのお話に出てくる孤児院とはあの旧孤児院ですね？",
  ui_story_5046_50460802_61_dialog_content = "おや…私はただ物語をお聞かせしただけですよ。",
  ui_story_5046_50460802_62_dialog_content = "何かひらめいたのなら、嬉しいかぎりですね。",
  ui_story_5046_50460802_63_dialog_content = "今のお話、大変参考になりました。\nご協力に心より感謝いたします。",
  ui_story_5046_50460802_64_dialog_content = "ただ、少々お尋ねしますが、\n今のお話をどちらで知ったのですか？",
  ui_story_5046_50460802_65_dialog_content = "ピアタマン先輩の調べている事件は白夜城貴族が関係しています。",
  ui_story_5046_50460802_66_dialog_content = "今のお話をした方はずいぶんと細かいことまでご存じのようですね。\n普通の人物ではないのではありませんか？",
  ui_story_5046_50460802_67_dialog_content = "ここへ来て話をしていく人たちは皆名乗りません。\n知ってることが少ないほど物語は面白いもんですよ。",
  ui_story_5046_50460802_68_dialog_content = "影は秘密をすべて知っています。",
  ui_story_5046_50460802_69_dialog_content = "（この人、一見信用しがたい雰囲気ですが、\n言動にまったく隙がありません…）",
  ui_story_5046_50460802_70_dialog_content = "（今日道で会ったのもおそらく偶然ではないでしょう。\n今の話をするため、私をここへ連れてくるつもりだったのでしょう）",
  ui_story_5046_50460802_71_dialog_content = "この大陸で起こるすべての物事は互いにつながってるんです。\n影ノ街の蝶がはばたけば、白夜城に嵐が起こります。",
  ui_story_5046_50460802_72_dialog_content = "え？",
  ui_story_5046_50460802_73_dialog_content = "（なぜ急に私を見つめながら、そんなことを言うのでしょう？）",
  ui_story_5046_50460802_74_dialog_content = "フフ…さあ、物語の時間もおしまいです。",
  ui_story_5046_50460802_75_dialog_content = "見てください。外の夜景、素晴らしいですよ。\nクリステンは影ノ街の夜景をあまり見たことないんじゃないですか？",
  ui_story_5046_50460802_76_dialog_content = "夜になると影ノ街には明かりを灯した屋台がたくさん並び、\n銀河のように美しく温かいですね。",
  ui_story_5046_50460802_77_dialog_content = "お話とジュース、ありがとうございました。\nおいしかったです。",
  ui_story_5046_50460802_78_dialog_content = "フフ、実はその特製ジュースもあなたにお会いして思いついたんです。\n初めて作ったんですよ。",
  ui_story_5046_50460802_79_dialog_content = "名前はあるのですか？",
  ui_story_5046_50460802_80_dialog_content = "いいえ、まだありません。ただ――",
  ui_story_5046_50460802_81_dialog_content = "「白夜城のユリ」にしようかと思ってます。",
  ui_story_5046_50460901_1_dialog_content = "ハーティ、昔どこに住んでたか覚えてる？",
  ui_story_5046_50460901_2_dialog_content = "記憶を取り戻すなら、\n昔住んでた場所に行けば何か思い出すんじゃないかな？",
  ui_story_5046_50460901_3_dialog_content = "何度も引っ越してたから、あまりよく覚えてないんだ。",
  ui_story_5046_50460901_4_dialog_content = "でも、ボクが火事を起こした家のことはまだ覚えてるよ。\n影ノ街の近くだった。",
  ui_story_5046_50460901_5_dialog_content = "君が火事を起こしたんじゃないよ。きっと何かの間違いだ。",
  ui_story_5046_50460901_6_dialog_content = "じゃあ、そこに行ってみようか。\n何か思い出せるかもしれない。",
  ui_story_5046_50460901_7_dialog_content = "ここだよ。",
  ui_story_5046_50460901_8_dialog_content = "途中にあった民家も皆荒れ果ててたね。\nこの辺りは長い間人が住んでなかったみたいだ。",
  ui_story_5046_50460901_9_dialog_content = "でも、焼け落ちてるのはこの家だけだ。\n一目で分かる。",
  ui_story_5046_50460901_10_option_content = "どうして荒れ果ててるんだろう？",
  ui_story_5046_50460901_11_dialog_content = "分からない。",
  ui_story_5046_50460901_12_dialog_content = "あの火事の後、次に目を覚ました時には\nボクはもう孤児院にいた。",
  ui_story_5046_50460901_13_dialog_content = "その後まもなく、孤児院が火事になって、\nボクはシャドウマスターの所へ送られた。",
  ui_story_5046_50460901_14_dialog_content = "ここへ来たのは、それ以来始めてだ。",
  ui_story_5046_50460901_15_dialog_content = "君のお家を見せて。",
  ui_story_5046_50460901_16_option_content = "どうして引っ越しばかりしてたの？",
  ui_story_5046_50460901_17_dialog_content = "悪いやつらに追われてたからだよ。",
  ui_story_5046_50460901_18_dialog_content = "母さんが昔言ってたんだ。父さんはすごい人で、\nだから父さんを捕まえて実験したがってる人がいるって。",
  ui_story_5046_50460901_19_dialog_content = "ある日悪いやつが家にやってきて父さんを捕まえようとした。\n父さんは母さんを守るため、自分だけその場に残った。",
  ui_story_5046_50460901_20_dialog_content = "逃げ出した母さんは一人でボクを生んだんだ。",
  ui_story_5046_50460901_21_dialog_content = "昔母さんに聞いたことがある。なんで父さんがいないのって。\nそうしたら、父さんは遠い所にいるんだよって母さんは答えた。",
  ui_story_5046_50460901_22_dialog_content = "でも、ボクが大きくなると母さんは、ある謎の組織が\n父さんを実験台にするために捕まえたんだって教えてくれたんだ。",
  ui_story_5046_50460901_23_dialog_content = "謎の組織はその後もずっと追ってきて、\nだから、母さんはボクを連れて逃げるように引っ越しを繰り返してた。",
  ui_story_5046_50460901_24_dialog_content = "君のお家を見せて。",
  ui_story_5046_50460901_25_option_content = "君のお家を見せて",
  ui_story_5046_50460901_26_dialog_content = "燃えちゃってるけど、ここで暮らしてた時の事、\nまだ覚えてるでしょ？",
  ui_story_5046_50460901_27_dialog_content = "君が辛い思いをすることは分かってる。\nでも、どんなささいなことでも記憶を取り戻すきっかけになるかもしれない。",
  ui_story_5046_50460901_28_dialog_content = "本当のこと言うと、ここに来るの…怖かったんだ。\n母さんと暮らしてた時のこと、思い出すのが怖かったから…",
  ui_story_5046_50460901_29_dialog_content = "失った記憶を取り戻すことも。",
  ui_story_5046_50460901_30_dialog_content = "母さんがもし本当にボクの力を恐れて、\nボクを暖炉に入れたんだとしたら…",
  ui_story_5046_50460901_31_dialog_content = "それはないよ。お母さんがそうしたのには、\nきっと別の理由がある。",
  ui_story_5046_50460901_32_dialog_content = "だって君は火の中にいてもケガ一つしないでしょ？\nお母さんもそのことは知ってたはずだ。",
  ui_story_5046_50460901_33_dialog_content = "当時何か危険が迫ってて、\nお母さんはハーティを守ろうとして暖炉に入れたのかもしれないよ。",
  ui_story_5046_50460901_34_dialog_content = "ハーティのお父さんがお母さんを守ろうとした時みたいにね。",
  ui_story_5046_50460901_35_dialog_content = "…",
  ui_story_5046_50460901_36_dialog_content = "行こう。ボクが昔住んでた所を見せてやるよ。",
  ui_story_5046_50460901_37_dialog_content = "うん！",
  ui_story_5046_50460901_38_dialog_content = "ここを入るとすぐに客間だ。\n母さんはいつもおいしいものや絵本をもってきてくれた。",
  ui_story_5046_50460901_39_dialog_content = "ここには窓があったんだ。厚いカーテンがかかってたから、\n光が入ってこなくて、外も見えなかったけど…",
  ui_story_5046_50460901_40_dialog_content = "外で遊ぶ子どもたちの声は聞こえたよ。",
  ui_story_5046_50460901_41_dialog_content = "ある時ボクが窓を開けて、外の子どもたちが何して遊んでるのか見ようとしたら、\n母さんに止められたんだ。",
  ui_story_5046_50460901_42_dialog_content = "「窓を閉めなさい！今すぐよ！」",
  ui_story_5046_50460901_43_dialog_content = "光が入ってこないなら、家の中はいつも真っ暗だったんじゃない？",
  ui_story_5046_50460901_44_dialog_content = "母さんがロウソクをたくさん灯してくれてたんだ。",
  ui_story_5046_50460901_45_dialog_content = "それは不思議だね…",
  ui_story_5046_50460901_46_dialog_content = "ボクは生まれつき強大な炎の光力を持ってたんだ。\n母さんが言うには、父さんから受け継いだ力らしいよ。",
  ui_story_5046_50460901_47_dialog_content = "小さい頃、よくうっかり布団や絵本を燃やしちゃってね。\n母さんも火を使わせてくれなかった。",
  ui_story_5046_50460901_48_dialog_content = "母さんが他の子どもたちと遊ばせてくれなかったのも、\nボクを暖炉に入れたのも、きっとボクの炎を恐れてたからだと思うんだ。",
  ui_story_5046_50460901_49_dialog_content = "（ハーティのお母さんはハーティを外に出そうせず、\nカーテンで家の中が外から見えないようにしてた…）",
  ui_story_5046_50460901_50_dialog_content = "（しかも誰かがハーティたちを追ってたってことは…\nハーティのお母さんは世間に何かを隠してたのかもしれない）",
  ui_story_5046_50460901_51_dialog_content = "ほら、この暖炉だよ。",
  ui_story_5046_50460901_52_dialog_content = "…",
  ui_story_5046_50460901_53_dialog_content = "PlayerName…暖炉の中に入ってみようと思う。",
  ui_story_5046_50460901_54_dialog_content = "えっ？",
  ui_story_5046_50460901_55_dialog_content = "さっきアンタ、ここでの生活を思い出すように言ったろ？\nだから、あの時みたいに暖炉の中に入ってみたいんだ。",
  ui_story_5046_50460901_56_dialog_content = "そうすれば、何か思い出すかもしれない。",
  ui_story_5046_50460901_57_dialog_content = "いい方法だとは思うけど…",
  ui_story_5046_50460901_58_dialog_content = "…うん、分かった。",
  ui_story_5046_50460901_59_dialog_content = "何かあったら、感知能力で君の記憶に強制介入して助けてあげる。",
  ui_story_5046_50460901_60_dialog_content = "ありがとう。でも、まずは自分で思い出してみたいんだ。",
  ui_story_5046_50460901_61_dialog_content = "分かった。でも、助けが必要な時はちゃんと教えてね！",
  ui_story_5046_50460901_62_dialog_content = "<color=#e8d9bb>影ノ街郊外</color>",
  ui_story_5046_50460901_63_dialog_content = "この先にハーティが以前住んでいた家があるのですね。",
  ui_story_5046_50460901_64_dialog_content = "以前お父様が購入した影ノ街の別荘も\n確かこの辺りでしたね。",
  ui_story_5046_50460901_65_dialog_content = "この角を左に曲がり、少し歩くと見えるはずです。",
  ui_story_5046_50460901_66_dialog_content = "確か最後にあの別荘へ行ったのはお父様とお母様と一緒に休暇を過ごすためでしたね…\n先生が私を助けてくださったのもあの別荘…",
  ui_story_5046_50460901_67_dialog_content = "あれは…PlayerNameさん！",
  ui_story_5046_50460901_68_dialog_content = "何か思い出した？",
  ui_story_5046_50460901_69_dialog_content = "いや、何も。",
  ui_story_5046_50460901_70_dialog_content = "やっぱりダメか…",
  ui_story_5046_50460901_71_dialog_content = "PlayerNameさん！ハーティ！",
  ui_story_5046_50460901_72_dialog_content = "クリステン！？",
  ui_story_5046_50460901_73_dialog_content = "ハーティ！法に基づき、複数の殺人および放火の容疑で、\nあなたを逮捕します！",
  ui_story_5046_50460901_74_dialog_content = "ちょっと待って！",
  ui_story_5046_50460901_75_dialog_content = "ハーティは犯人じゃないよ。どうしてハーティを捕まえるの？",
  ui_story_5046_50460901_76_dialog_content = "自ら罪を認める犯人はいません。",
  ui_story_5046_50460901_77_dialog_content = "だ、だったら…証拠はあるの？",
  ui_story_5046_50460901_78_dialog_content = "証拠ですか？",
  ui_story_5046_50460901_79_dialog_content = "PlayerNameさん、あなたもご覧になったでしょう？\nハーティは私たちの目の前でハーメル氏を殺害したのですよ。",
  ui_story_5046_50460901_80_dialog_content = "クリステン、僕を信じて。\nハーメルさんはハーティが殺したんじゃない！",
  ui_story_5046_50460901_81_dialog_content = "きっと誰かが裏でハーメルさんに手を下したんだ。",
  ui_story_5046_50460901_82_dialog_content = "いずれにせよ、ハーティがハーメル氏が亡くなった現場にいたのは事実です。",
  ui_story_5046_50460901_83_dialog_content = "彼女が殺したのでなくとも、捜査に協力する義務があります。",
  ui_story_5046_50460901_84_dialog_content = "ご同行願います。",
  ui_story_5046_50460901_85_dialog_content = "母さんとの記憶を取り戻さなきゃいけないんだ。",
  ui_story_5046_50460901_86_dialog_content = "それ以外のことは重要じゃない。",
  ui_story_5046_50460901_87_dialog_content = "つまり、同行を拒否するということですか？",
  ui_story_5046_50460901_88_dialog_content = "どう思おうとアンタの勝手だ。",
  ui_story_5046_50460901_89_dialog_content = "そうですか…では、強制執行しか手はないようですね。",
  ui_story_5046_50460901_90_dialog_content = "クリステン、ハーティが記憶を取り戻してからじゃダメかな？",
  ui_story_5046_50460901_91_dialog_content = "PlayerNameさん、おどきください。",
  ui_story_5046_50460901_92_dialog_content = "それ以上容疑者をかばうなら、\nあなたを共犯として逮捕する以外なくなります。",
  ui_story_5046_50460901_93_dialog_content = "お母さんとの記憶は…\nハーティにとって、とても大事なものなんだ。",
  ui_story_5046_50460901_94_dialog_content = "それがどんなに大切なものか、僕にはよく分かる。",
  ui_story_5046_50460901_95_dialog_content = "それにハーティと約束したんだ。\n記憶を取り戻すのを手伝うって。",
  ui_story_5046_50460901_96_dialog_content = "だから、絶対にどかない。",
  ui_story_5046_50460901_97_dialog_content = "僕はハーティを守るよ。ハーティが記憶を取り戻すその時まで。",
  ui_story_5046_50460901_98_dialog_content = "あなたはハーティを守りたい…ですが、私も先生を守りたいのです！",
  ui_story_5046_50460901_99_dialog_content = "ハーティが孤児院に火を放ち、あなたを人質として連れ去った…",
  ui_story_5046_50460901_100_dialog_content = "あなたたちが先生の騎士としての生涯に泥を塗ったのですよ！",
  ui_story_5046_50460901_101_dialog_content = "あなたとハーティのせいで、\n先生がどれだけ苦労なさっているかご存じですか！？",
  ui_story_5046_50460901_102_dialog_content = "あなたたちを連れ帰り、\nシャドウマスターと影ノ街のため務めを全うできれば…",
  ui_story_5046_50460901_103_dialog_content = "そうすれば、先生はきっとお喜びになります！",
  ui_story_5046_50460901_104_dialog_content = "もう一度申し上げます！",
  ui_story_5046_50460901_105_dialog_content = "PlayerNameさん！おどきください！",
  ui_story_5046_50460901_106_dialog_content = "嫌だ！僕は絶対に退かない！",
  ui_story_5046_50460901_107_dialog_content = "ハーティ…守るのよ…ペンダントを…",
  ui_story_5046_50460901_108_dialog_content = "母さん…母さん、ボクは何を守ればいいんだ…",
  ui_story_5046_50460901_109_dialog_content = "教えてくれよ、母さん…",
  ui_story_5046_50460901_110_dialog_content = "あの日いったい何があったんだ。ボクを暖炉に入れるなんて…",
  ui_story_5046_50460901_111_dialog_content = "これが最後の忠告です！おどきください！",
  ui_story_5046_50460901_112_dialog_content = "例の物を…渡してもらおう…でないと…死んで…",
  ui_story_5046_50460901_113_dialog_content = "うう！頭が痛い！何かかボクの頭の中に入って来た！",
  ui_story_5046_50460901_114_dialog_content = "来たわ。",
  ui_story_5046_50460901_115_dialog_content = "やはり逃げ切れないのね。",
  ui_story_5046_50460901_116_dialog_content = "母さん？",
  ui_story_5046_50460901_117_dialog_content = "ハーティ。母さんはどこに行っても、\nあなたをずっとずっと愛してるわ。",
  ui_story_5046_50460901_118_dialog_content = "母さん…どっか行っちゃうの？",
  ui_story_5046_50460901_119_dialog_content = "なんでそばにいてくれないの？",
  ui_story_5046_50460901_120_dialog_content = "もう…時間がないの…",
  ui_story_5046_50460901_121_dialog_content = "ハーティ、この片方のロケットペンダントを大切にするのよ。",
  ui_story_5046_50460901_122_dialog_content = "このロケットペンダントには父さんと母さんのあなたへの愛が\nたくさん詰まってるの。永遠にハーティを守ってくれるわ。",
  ui_story_5046_50460901_123_dialog_content = "生き延びるのよ。愛してるわ。",
  ui_story_5046_50460901_124_dialog_content = "母さん！？",
  ui_story_5046_50460901_125_dialog_content = "うう！",
  ui_story_5046_50460901_126_dialog_content = "（母さん…なんでボクを暖炉の中に突き飛ばしたの！？）",
  ui_story_5046_50460901_127_dialog_content = "<color=#e8d9bb>ギィ…</color>",
  ui_story_5046_50460901_128_dialog_content = "（誰か来た！？誰？うちには誰も来たことないのに！）",
  ui_story_5046_50460901_129_dialog_content = "ずいぶん探したぞ、キャサリン・ケルピー。\n逃げ切れるとでも思ってたのか？",
  ui_story_5046_50460901_130_dialog_content = "…ゼナス。",
  ui_story_5046_50460901_131_dialog_content = "チッ、なんて暗い家だ。真っ暗じゃないか。",
  ui_story_5046_50460901_132_dialog_content = "温室育ちのお嬢様がこんなボロ屋に住んでるとは、\nずいぶん生活に困ってるようだな。",
  ui_story_5046_50460901_133_dialog_content = "あなたさえいなくなれば、どんなボロ屋だって幸せに暮らせるわ。",
  ui_story_5046_50460901_134_dialog_content = "シーッ。お嬢様がずいぶん恐ろしいこと言うな。",
  ui_story_5046_50460901_135_dialog_content = "これ以上話したくないわ。",
  ui_story_5046_50460901_136_dialog_content = "今日こそ殺してやる！フェンリルの仇よ！",
  ui_story_5046_50460901_137_dialog_content = "（フェンリル？父さんの名前だ！こいつが父さんを殺したの！？）",
  ui_story_5046_50460901_138_dialog_content = "身の程知らずな。",
  ui_story_5046_50460901_139_dialog_content = "はぁ…はぁ…",
  ui_story_5046_50460901_140_dialog_content = "キャサリン、ペンダントを渡せば命だけは助けてやる。",
  ui_story_5046_50460901_141_dialog_content = "死んでも渡さないわ…",
  ui_story_5046_50460901_142_dialog_content = "まったく強情な女だ。\nそんなに死にたいなら、願いをかなえてやる。",
  ui_story_5046_50460901_143_dialog_content = "（母さん！）",
  ui_story_5046_50460901_144_dialog_content = "あああああ――！",
  ui_story_5046_50460901_145_dialog_content = "（火がついた！？母さんがやったの？）",
  ui_story_5046_50460901_146_dialog_content = "クソッ！なんだって急に勢いよく燃え上がったんだ？",
  ui_story_5046_50460901_147_dialog_content = "キャサリン、ハメやがったな？",
  ui_story_5046_50460901_148_dialog_content = "生きて帰れると思ったら大間違いよ…",
  ui_story_5046_50460901_149_dialog_content = "放せ！お前、俺を道連れにする気だな！",
  ui_story_5046_50460901_150_dialog_content = "フェンリルの仇…",
  ui_story_5046_50460901_151_dialog_content = "うぐっ――！",
  ui_story_5046_50460901_152_dialog_content = "（母さん！母さんがボクを見てる…）",
  ui_story_5046_50460901_153_dialog_content = "…",
  ui_story_5046_50460901_154_dialog_content = "（出てくるなって言いたいの？）",
  ui_story_5046_50460901_155_dialog_content = "（母さん！？母さんが動かなくなっちゃったよ！）",
  ui_story_5046_50460901_156_dialog_content = "（母さん――！）",
  ui_story_5046_50460901_157_dialog_content = "フン、この俺を脅すとはな。",
  ui_story_5046_50460901_158_dialog_content = "（うううっ…母さん…）",
  ui_story_5046_50460901_159_dialog_content = "（あいつ、何か探してる…）",
  ui_story_5046_50460901_160_dialog_content = "（あいつを殺して、母さんの仇をとってやる！）",
  ui_story_5046_50460901_161_dialog_content = "（…でも、ダメだ。母さんが出てくるなって言った…）",
  ui_story_5046_50460901_162_dialog_content = "アチッ…いったいどこに隠しやがった！？",
  ui_story_5046_50460901_163_dialog_content = "…",
  ui_story_5046_50460901_164_dialog_content = "やっと見つけたぞ。うっ…顔が痛むな。やけどでもしたか？",
  ui_story_5046_50460901_165_dialog_content = "火事だ！火事だぞ！",
  ui_story_5046_50460901_166_dialog_content = "まずい、見つかる。",
  ui_story_5046_50460901_167_dialog_content = "（あいつ…いなくなった…母さんが…動かない…）",
  ui_story_5046_50460901_168_dialog_content = "（母さん…）",
  ui_story_5046_50460901_169_dialog_content = "ものすごい勢いだったな。ようやく消し止めたが…",
  ui_story_5046_50460901_170_dialog_content = "見つけた時には、キャサリンの息はもうなかったわ…",
  ui_story_5046_50460901_171_dialog_content = "あの火の勢いじゃ、焼け死ぬ前に煙でやられちまうよ。",
  ui_story_5046_50460901_172_dialog_content = "あなたは黙ってて。",
  ui_story_5046_50460901_173_dialog_content = "フン…",
  ui_story_5046_50460901_174_dialog_content = "ちょうど手も空いてるし、皆で片付けるとしよう。",
  ui_story_5046_50460901_175_dialog_content = "はいはい、分かったよ。",
  ui_story_5046_50460901_176_dialog_content = "ちょっと来て！暖炉の中に小さな子どもがいるわ！",
  ui_story_5046_50460901_177_dialog_content = "キャサリンに子供がいるなんて聞いたことないが…",
  ui_story_5046_50460901_178_dialog_content = "しかも傷一つないじゃないか。あんなに激しい火だったのに…",
  ui_story_5046_50460901_179_dialog_content = "はぁ…キャサリンのやつ、窓をきっちり閉めて、\n昼間でもロウソクつけてやがったろ。",
  ui_story_5046_50460901_180_dialog_content = "いつかは火事でも起こすんじゃないかって思ってたが…\nほれ見たことか。",
  ui_story_5046_50460901_181_dialog_content = "今さらそんなこと言って何になる！？\n今一番大事なのはこの子をどうするかってことだろう？",
  ui_story_5046_50460901_182_dialog_content = "孤児院に入れるしかないんじゃないかしら？",
  ui_story_5046_50460901_183_dialog_content = "それしかないな…",
  ui_story_5046_50460901_184_dialog_content = "聞きたいことがあるんだ。",
  ui_story_5046_50461001_1_dialog_content = "少しずつ落ち着いてきたようですね。",
  ui_story_5046_50461001_2_dialog_content = "ありがとう、クリステン。",
  ui_story_5046_50461001_3_dialog_content = "なぜお礼を？",
  ui_story_5046_50461001_4_dialog_content = "ハーティが記憶を取り戻すのを待ってくれて、ありがとう。",
  ui_story_5046_50461001_5_dialog_content = "本当は君もハーティが犯人じゃないって思ってたんでしょ？",
  ui_story_5046_50461001_6_dialog_content = "調査の結果、ハーティへの疑いは確かに小さくなりました。",
  ui_story_5046_50461001_7_dialog_content = "事件は確かにハーティと関係があり、\nどの手がかりもハーティが犯人である可能性を示しています。",
  ui_story_5046_50461001_8_dialog_content = "ですが、矛盾点もたくさん残っています。",
  ui_story_5046_50461001_9_dialog_content = "クリステンは誠実に事件と向き合ってるんだね。",
  ui_story_5046_50461001_10_dialog_content = "先生に教えられたのです。事件としっかり向き合い、\nわずかな手がかりも決して見逃してはならないと。",
  ui_story_5046_50461001_11_dialog_content = "ですが、先生はこの事件に私が関わることを許してくれず…",
  ui_story_5046_50461001_12_dialog_content = "ということは、クリステンはこっそり調べてたの？",
  ui_story_5046_50461001_13_dialog_content = "はい…",
  ui_story_5046_50461001_14_dialog_content = "ところで、PlayerNameさんはなぜハーティと一緒に逃げたのですか？\n人質なのでしょう？",
  ui_story_5046_50461001_15_dialog_content = "ハーティは犯人じゃないって信じてるからだよ。\nそれにあの時、ハーティはすごく情緒が不安定だった。",
  ui_story_5046_50461001_16_dialog_content = "ハーティには僕の助けが必要だ。\nだから僕を一緒に連れて行くように言ったんだよ。",
  ui_story_5046_50461001_17_dialog_content = "短期間でそこまでの信頼関係をお築きになったと…？",
  ui_story_5046_50461001_18_dialog_content = "<size=30>先生もそれくらい私を信頼してくださればいいのに…</size>",
  ui_story_5046_50461001_19_dialog_content = "クリステンはどうしてここが分かったの？",
  ui_story_5046_50461001_20_dialog_content = "昔ここに住んでいた方に教えていただいたのです。",
  ui_story_5046_50461001_21_dialog_content = "この村は孤児院からそう離れておらず、影ノ街にも属していません。\nですから、昔ここの住民たちは苦しい暮らしを送っていました。",
  ui_story_5046_50461001_22_dialog_content = "当時イスタバンが孤児院の大火事の後処理に関与し、\n彼のとった一連の行動は住民たちの心をつかみました。",
  ui_story_5046_50461001_23_dialog_content = "シャドウマスターとなった後、\nイスタバンはこの村の住人を影ノ街へと移住させました。",
  ui_story_5046_50461001_24_dialog_content = "ハーティはその住民たちが孤児院へ送ったのです。",
  ui_story_5046_50461001_25_dialog_content = "村人の話によると、村で昔大火事があり、\n火を消し止めた後、焼け落ちた家の中でハーティを見つけたそうです。",
  ui_story_5046_50461001_26_dialog_content = "この家に住んでいた女性もその時に亡くなったと聞いています。",
  ui_story_5046_50461001_27_dialog_content = "ですが、村人たちはその女性が子どもの話をするのを聞いたことがなく、\nどうすればいいのか分からなかったそうです。",
  ui_story_5046_50461001_28_dialog_content = "最終的には孤児院へ送ることを決めたそうですが、\nその子どもがハーティだったのです。",
  ui_story_5046_50461001_29_dialog_content = "そうだったんだ…",
  ui_story_5046_50461001_30_dialog_content = "クリステンは本当にすごいね。\nわずかな手がかりから、そんなにたくさんの情報を調べあげるなんて。",
  ui_story_5046_50461001_31_dialog_content = "オホン！いくらお褒めくださっても、\nお二人には同行し、調査に協力していただきます。",
  ui_story_5046_50461001_32_dialog_content = "僕は心の底からクリステンはすごいなって思ってるんだよ！\n将来きっといい裁判官になるね！",
  ui_story_5046_50461001_33_dialog_content = "先生もそんな風に思ってくださればいいのですが…",
  ui_story_5046_50461001_34_dialog_content = "ゼナスのこと？",
  ui_story_5046_50461001_35_dialog_content = "ええ…先日光力術で火を消そうとして、先生におケガをさせてしまいました。\nその後ハーメル氏も亡くなり…",
  ui_story_5046_50461001_36_dialog_content = "私のことを信用してくだらないのです。",
  ui_story_5046_50461001_37_dialog_content = "僕はクリステンすごいと思うよ。",
  ui_story_5046_50461001_38_dialog_content = "まだ数回しか会ったことないけど、\nクリステンは真面目で辛抱強くて、心のきれいな裁判官だと思うな。",
  ui_story_5046_50461001_39_dialog_content = "そ、そのような甘い言葉で私が手加減すると思ったら大間違いです…",
  ui_story_5046_50461001_40_dialog_content = "私は白夜城法廷の専門的な訓練を受けているのです。\n正義を…貫く信念はあ…あなたの言葉などで揺らぐものではありません！",
  ui_story_5046_50461001_41_dialog_content = "僕は言いたいことを言っただけだよ！別に意図はないんだ！",
  ui_story_5046_50461001_42_dialog_content = "もし本当にハーティがやったことなら、\n絶対にちゃんと罪を償わせるよ。",
  ui_story_5046_50461001_43_dialog_content = "でも、そうじゃないなら、ハーティに罪を着せるのは絶対に許さない！",
  ui_story_5046_50461001_44_dialog_content = "そ、その通りです！正義はまさにそうあるべきです！",
  ui_story_5046_50461001_45_dialog_content = "だから、クリステンも自信を持つといいよ。\n他人の考えなんて気にしすぎることないんだ。",
  ui_story_5046_50461001_46_dialog_content = "だって、クリステンは本当にすごいんだから！",
  ui_story_5046_50461001_47_dialog_content = "…",
  ui_story_5046_50461001_48_dialog_content = "女性のご機嫌取りがうまいと言われたことはありませんか？",
  ui_story_5046_50461001_49_dialog_content = "え？女の子のご機嫌取り？",
  ui_story_5046_50461001_50_dialog_content = "バイスは毎日のように巨像の経済状況に頭を悩ませてて、\n僕はいつも無駄遣いするって怒られてるんだ。",
  ui_story_5046_50461001_51_dialog_content = "女の子を不機嫌にするのがうまいって言う方が正確だよ。",
  ui_story_5046_50461001_52_dialog_content = "<size=45>グガアア――</size>",
  ui_story_5046_50461001_53_dialog_content = "暗鬼？1匹じゃないみたいだ。",
  ui_story_5046_50461001_54_dialog_content = "ここは長い間荒れ果てたままでしたから、\n暗鬼が出てもおかしくはありません。",
  ui_story_5046_50461001_55_dialog_content = "でも、ハーティはまだ目を覚ましてない。\n今むやみにハーティを連れてここを離れるのは危険じゃないかな？",
  ui_story_5046_50461001_56_dialog_content = "ご心配にはおよびません。\nたった数匹の暗鬼など私が裁いてご覧に入れます！",
  ui_story_5046_50461002_1_dialog_content = "ふぅ――",
  ui_story_5046_50461002_2_dialog_content = "周囲にあった暗鬼の気配が全部消えたよ。",
  ui_story_5046_50461002_3_dialog_content = "ありがとう、クリステン。",
  ui_story_5046_50461002_4_dialog_content = "空の末裔の能力は実に強大なものですね。",
  ui_story_5046_50461002_5_dialog_content = "PlayerNameさんがいなければ、\n何度も暗鬼の不意打ちを食らってしまうところでした。",
  ui_story_5046_50461002_6_dialog_content = "PlayerName…",
  ui_story_5046_50461002_7_dialog_content = "ハーティ！？目が覚めたんだね！",
  ui_story_5046_50461002_8_dialog_content = "目が覚めたのなら、捜査協力のためご同行願いましょう。\n調査結果が出るまでは…",
  ui_story_5046_50461002_9_dialog_content = "ゼナスだ…",
  ui_story_5046_50461002_10_dialog_content = "先生がどうかしましたか？",
  ui_story_5046_50461002_11_dialog_content = "PlayerName…全部、思い出した。",
  ui_story_5046_50461002_12_dialog_content = "あの晩、母さんはボクを守るために、\nボクを暖炉の中に突き飛ばしたんだ。",
  ui_story_5046_50461002_13_dialog_content = "母さんはたった一人で立ち向かったんだ…\nそう、相手の名前はゼナスだ。",
  ui_story_5046_50461002_14_dialog_content = "あいつが母さんを殺して、\n母さんの付けてたロケットペンダントを奪ったんだよ。",
  ui_story_5046_50461002_15_dialog_content = "ロケットペンダントを取り返す！",
  ui_story_5046_50461002_16_dialog_content = "先生が？先生と何の関係があるのですか？",
  ui_story_5046_50461002_17_dialog_content = "ゼナスは殺人犯だ。",
  ui_story_5046_50461002_18_dialog_content = "デタラメを言わないでください！",
  ui_story_5046_50461002_19_dialog_content = "それ以上先生をけなすようなことをおっしゃるのなら、\n私も容赦いたしません！",
  ui_story_5046_50461002_20_dialog_content = "殺人犯は殺人犯だ。それが事実だよ。",
  ui_story_5046_50461002_21_dialog_content = "あの晩ゼナスが家に来た。\n母さんはあいつに殺され、ペンダントも奪われた。",
  ui_story_5046_50461002_22_dialog_content = "全部ボクがこの目で見たんだ！絶対に殺してやる！\n母さんの仇を討ってやる！",
  ui_story_5046_50461002_23_dialog_content = "なぜ先生があなたのお母様を殺した犯人だと断定できるのですか？",
  ui_story_5046_50461002_24_dialog_content = "今思い出したばかりなのでしょう？\nしかもずいぶん昔に起こったことです。",
  ui_story_5046_50461002_25_dialog_content = "あなたの記憶違いでないと言い切れますか？\nあなたがウソをついている可能性も否定できません。",
  ui_story_5046_50461002_26_dialog_content = "間違いない…",
  ui_story_5046_50461002_27_dialog_content = "やつの顔のやけどと母さんのロケットペンダントが…",
  ui_story_5046_50461002_28_dialog_content = "犯人だって証拠だ！",
  ui_story_5046_50461002_29_dialog_content = "申し訳ありません。先生の顔のやけどは私を救った時に負ったものです。",
  ui_story_5046_50461002_30_dialog_content = "あの日の夕方、両親はパーティへ出かけていきました。",
  ui_story_5046_50461002_31_dialog_content = "その日は日が暮れるのが早く、\n両親を見送るとすぐに暗くなったのをよく覚えています。",
  ui_story_5046_50461002_32_dialog_content = "私が独り部屋に戻って本を読んでいると…",
  ui_story_5046_50461002_33_dialog_content = "突然どこからか激しい火が上がり、\n煙の中で一人きりだった私は怖くてその場で泣きわめいていました。",
  ui_story_5046_50461002_34_dialog_content = "その時ちょうどゼナス先生が私を呼ぶのが聞こえました。\n泣き声をたどり、探しに来てくれたのです…",
  ui_story_5046_50461002_35_dialog_content = "火の中を逃げる時先生がしっかりと抱きしめていてくださったので、\n煙でむせた以外、私は傷一つ負いませんでした。",
  ui_story_5046_50461002_36_dialog_content = "ですが先生は…顔の半分にやけどを負ってしまったのです。",
  ui_story_5046_50461002_37_dialog_content = "そうなると、ゼナスさんの火傷はクリステンを助けた時に負ったってことになるね。",
  ui_story_5046_50461002_38_dialog_content = "…",
  ui_story_5046_50461002_39_dialog_content = "ハーティ、ゼナスが来たのはいつだったか覚えてる？",
  ui_story_5046_50461002_40_dialog_content = "8月26日だ。ボクの…誕生日だった。",
  ui_story_5046_50461002_41_dialog_content = "8月26日ですって！？",
  ui_story_5046_50461002_42_dialog_content = "先生が私を助けてくださったのも8月26日です。",
  ui_story_5046_50461002_43_dialog_content = "あの日を…忘れもしません。",
  ui_story_5046_50461002_44_dialog_content = "同じ日に2件の火事か…",
  ui_story_5046_50461002_45_dialog_content = "今クリステンは夜に火事が起こったって言ったよね？\nつまり、ゼナスは夜にクリステンの家に現れた。",
  ui_story_5046_50461002_46_dialog_content = "でも、ハーティも夜にゼナスが襲ってきたって言ってたね。",
  ui_story_5046_50461002_47_dialog_content = "つまり、ゼナスは同じ日の同じ時間に2つの異なる場所に現れたってことになる。",
  ui_story_5046_50461002_48_dialog_content = "どう考えてもそれはあり得ません。\nきっとあなたの記憶違いです、ハーティ。",
  ui_story_5046_50461002_49_dialog_content = "じゃあ、ペンダントはどう説明するんだ？",
  ui_story_5046_50461002_50_dialog_content = "母さんがボクに大切にするように言ったペンダントを、\nなんであいつが持ってるんだ？",
  ui_story_5046_50461002_51_dialog_content = "あのペンダントがあったから、ボクはやつだって分かったんだ。",
  ui_story_5046_50461002_52_dialog_content = "あなたのいうペンダントは先生の一族の印です。",
  ui_story_5046_50461002_53_dialog_content = "ペンダントに描かれている紋様は10数年前に没落した、\n白夜城貴族の家紋です。",
  ui_story_5046_50461002_54_dialog_content = "あの日先生が私を火の海から救い出してくれたことに感謝し、\n父が先生にお名前を尋ねたところ…",
  ui_story_5046_50461002_55_dialog_content = "先生はロケットペンダントを取り出し、元は貴族だったが、\n家が没落し、住居も定まらず暮らしているとお答えになったのです。",
  ui_story_5046_50461002_56_dialog_content = "父は同じ貴族として先生を家に留めることにしたのです。",
  ui_story_5046_50461002_57_dialog_content = "あのロケットペンダントは絶対に母さんのものだ。",
  ui_story_5046_50461002_58_dialog_content = "あいつが母さんのペンダントを盗んで、自分の物のように言ったんだ！",
  ui_story_5046_50461002_59_dialog_content = "何をおっしゃるのです！\n証拠はないのでしょう！？すべて推測にすぎません。",
  ui_story_5046_50461002_60_dialog_content = "（前にハーティは家の中はお母さんが窓に厚いカーテンを掛けてたせいで、\n光が差し込まず、ロウソクを照明にしてたって言ってたっけ）",
  ui_story_5046_50461002_61_dialog_content = "（だったら、事件が起こったのが夜だとは断定できないんじゃないかな？）",
  ui_story_5046_50461002_62_dialog_content = "ハーティ。男の人が家に来たのは夜だったって断定できる？",
  ui_story_5046_50461002_63_dialog_content = "それは…ロウソクがついてたから、たぶん夜だったと思う。",
  ui_story_5046_50461002_64_dialog_content = "問題はそこだよ。",
  ui_story_5046_50461002_65_dialog_content = "ロウソクがついてたから、君はこう考えた――",
  ui_story_5046_50461002_66_dialog_content = "「ロウソクを点ける必要があったってことは、\n事件は夜に起こった」ってね。",
  ui_story_5046_50461002_67_dialog_content = "でも実際にはハーティの家には夜も昼もロウソクが点ってたんだ。\nだから、「ロウソクが点いてた」点から時間は特定できないよ。",
  ui_story_5046_50461002_68_dialog_content = "僕が思うに、ハーティの家で事件があったのは\n昼間だったんじゃないかな？",
  ui_story_5046_50461002_69_dialog_content = "そうなのか…？",
  ui_story_5046_50461002_70_dialog_content = "一方、クリステンはご両親は夕方にパーティに出かけ、\nしかもその日は日が暮れるのが早かったと細かいことまで覚えてた。",
  ui_story_5046_50461002_71_dialog_content = "だから、クリステンの家で火事があったのは夜だ。",
  ui_story_5046_50461002_72_dialog_content = "そう考えると、犯人は昼間ハーティの家を襲って、\n夜にクリステンの家に駆け付け、クリステンを助けたってことになる。",
  ui_story_5046_50461002_73_dialog_content = "つまり「同じ人物が同じ時間に2つの異なる場所に出現した」って事実は成立しないんだ。",
  ui_story_5046_50461002_74_dialog_content = "素晴らしい推理です…",
  ui_story_5046_50461002_75_dialog_content = "ただ、もう1つ重要なポイントがあるんだ。\nここからクリステンの別荘まで行くにはどのくらいかかる？",
  ui_story_5046_50461002_76_dialog_content = "その点はここへ来る途中気づいていました。\n我が家の別荘はここからそう遠くはありません。",
  ui_story_5046_50461002_77_dialog_content = "まさか、本当に先生が？そ、そんなことあり得ません…",
  ui_story_5046_50461002_78_dialog_content = "ゼナスが犯人かどうかを確めるには、\nペンダントを見せてもらわないとね。",
  ui_story_5046_50461002_79_dialog_content = "ハーティは、ペンダントは対だって言ってた。",
  ui_story_5046_50461002_80_dialog_content = "ゼナスがハーティの家を襲った犯人じゃなく、\nかつその言葉通り「没落貴族」なら…",
  ui_story_5046_50461002_81_dialog_content = "ゼナスの持ってるペンダントがハーティのものと\nピッタリはまるはずがない。",
  ui_story_5046_50461002_82_dialog_content = "でも、もし2つのロケットがピッタリと合わさったら…",
  ui_story_5046_50461002_83_dialog_content = "ゼナスが犯人だ。",
  ui_story_5046_50461002_84_dialog_content = "そんなはずありません！先生は絶対に殺人犯ではありません！",
  ui_story_5046_50461002_85_dialog_content = "…そう…そうです！動機です！",
  ui_story_5046_50461002_86_dialog_content = "先生とあなたの家族との間には何の縁も恨みもないでしょう？\nどうしてあなたたちを追うのですか？",
  ui_story_5046_50461002_87_dialog_content = "母さんはある謎の組織が父さんの力を狙って、\n捕まえて実験台にしようとしてたって言ってた。",
  ui_story_5046_50461002_88_dialog_content = "記憶の中で、母さんは父さんの仇を討とうと、\nゼナスも道連れにして死のうとしてた…",
  ui_story_5046_50461002_89_dialog_content = "ゼナスはその謎の組織のやつだ。",
  ui_story_5046_50461002_90_dialog_content = "そんなこと…私は信じません！",
  ui_story_5046_50461002_91_dialog_content = "そんなこと…そんなこと、あり得ません！",
  ui_story_5046_50461002_92_dialog_content = "クリステン、落ち着いて。",
  ui_story_5046_50461002_93_dialog_content = "ゼナスが犯人かどうかは、\n2人のロケットペンダントを合わせてみれば分かることだよ。",
  ui_story_5046_50461002_94_dialog_content = "ロケットペンダントを渡してもらう。",
  ui_story_5046_50461002_95_dialog_content = "渡すのをためらうようなら、ボクがあいつを倒して奪ってやる。",
  ui_story_5046_50461002_96_dialog_content = "暴力はダメだよ！それに影ノ街のあちこちに君を捕まえようと\nしてる兵士がいるんだよ。ゼナスに会って話すのは無理だ。",
  ui_story_5046_50461002_97_dialog_content = "…",
  ui_story_5046_50461002_98_dialog_content = "私がお手伝いします。",
  ui_story_5046_50461002_99_dialog_content = "PlayerNameさんのおっしゃるように、\nロケットペンダントこそ先生の潔白を証明する最良の証拠です。",
  ui_story_5046_50461002_100_dialog_content = "ですから、私がお手伝いします。\n他の兵士のいない時に先生に会えるように計らいましょう。",
  ui_story_5046_50461002_101_dialog_content = "ただし、約束してください。\nペンダントが合わなかった時には大人しく捜査に協力してください。",
  ui_story_5046_50461002_102_dialog_content = "クリステン、信じてくれるの？",
  ui_story_5046_50461002_103_dialog_content = "そんなことは一言も申していません。",
  ui_story_5046_50461002_104_dialog_content = "ただ、PlayerNameさんの緻密な推理に思うところがあるのです…",
  ui_story_5046_50461002_105_dialog_content = "事件を改めて詳細に調べてみたいのです。",
  ui_story_5046_50461002_106_dialog_content = "もうだいぶ遅くなりました。\n急いで影ノ街へ戻りましょう。",
  ui_story_5046_50461101_1_dialog_content = "クリステンさん、お帰りなさいませ。",
  ui_story_5046_50461101_2_dialog_content = "クリステンで結構です。",
  ui_story_5046_50461101_3_dialog_content = "ゼナス隊長はどうされたのです？\nいくら探しても見当たらないのですが。",
  ui_story_5046_50461101_4_dialog_content = "ゼナス隊長は数名を連れて孤児院に向かわれました。",
  ui_story_5046_50461101_5_dialog_content = "孤児院ですか？何をしに行かれたのです？",
  ui_story_5046_50461101_6_dialog_content = "それは…うかがっておりません。",
  ui_story_5046_50461101_7_dialog_content = "そうですか。ありがとう。",
  ui_story_5046_50461101_8_dialog_content = "報告します。何も見つかりません。",
  ui_story_5046_50461101_9_dialog_content = "引き続き探してください。\nどのような物でも見つけ次第、私に渡してください。",
  ui_story_5046_50461101_10_dialog_content = "報告です！",
  ui_story_5046_50461101_11_dialog_content = "何か見つかりましたか？",
  ui_story_5046_50461101_12_dialog_content = "いいえ。クリステンさんがいらっしゃいました。\nお会いしたいとのことです。",
  ui_story_5046_50461101_13_dialog_content = "何をしに来たのでしょう？",
  ui_story_5046_50461101_14_dialog_content = "先生。",
  ui_story_5046_50461101_15_dialog_content = "みなさんは外していただけますか？\n先生と2人でお話がしたいのです。",
  ui_story_5046_50461101_16_dialog_content = "はい。",
  ui_story_5046_50461101_17_dialog_content = "クリステン？なぜここに？",
  ui_story_5046_50461101_18_dialog_content = "あなたは法廷に事件の調査記録を出しに行ったのではないのですか？",
  ui_story_5046_50461101_19_dialog_content = "白夜城へ戻る前に、先生にお願いしたいことがあります。",
  ui_story_5046_50461101_20_dialog_content = "ロケットペンダントをお借りできませんか？",
  ui_story_5046_50461101_21_dialog_content = "ロケットペンダント？",
  ui_story_5046_50461101_22_dialog_content = "以前見せてくださいましたでしょう？\n先生の一族の家紋が描かれたロケットペンダントです。",
  ui_story_5046_50461101_23_dialog_content = "何に使うつもりですか？",
  ui_story_5046_50461101_24_dialog_content = "はい…",
  ui_story_5046_50461101_25_dialog_content = "事件資料を調べている時に先生の一族の家紋と似た紋様を見つけました。\nですから、もう一度見てみたいのです。",
  ui_story_5046_50461101_26_dialog_content = "…",
  ui_story_5046_50461101_27_dialog_content = "クリステン、あなたを小さい頃から知っています。\n本当のことをいっているかどうかは一目で分かりますよ。",
  ui_story_5046_50461101_28_dialog_content = "先生…",
  ui_story_5046_50461101_29_dialog_content = "教えてください。どうしたのです？",
  ui_story_5046_50461101_30_dialog_content = "実は、その…ロケットペンダントで先生の潔白を証明したいのです。",
  ui_story_5046_50461101_31_dialog_content = "潔白を証明する？",
  ui_story_5046_50461101_32_dialog_content = "何年も前の放火事件と先生が関係しているかもしれないことを知りました。",
  ui_story_5046_50461101_33_dialog_content = "先生の容疑を晴らす要となるのが、\n今つけていらっしゃるロケットペンダントなのです。",
  ui_story_5046_50461101_34_dialog_content = "ロケットペンダントと放火事件と何のつながりがあるのですか？",
  ui_story_5046_50461101_35_dialog_content = "先生のペンダントと私の持っているペンダントは…対だそうです。",
  ui_story_5046_50461101_36_dialog_content = "2つのペンダントがピッタリと合わさるかどうか\n確認さえできれば…",
  ui_story_5046_50461101_37_dialog_content = "事件と関係のあるものならば、関係者に渡して詳細に調査するべきでしょう。",
  ui_story_5046_50461101_38_dialog_content = "証拠を突きつけて上司を尋問するとは…\nクリステン、私が教えてきたことを忘れたのですか？",
  ui_story_5046_50461101_39_dialog_content = "おだやかに解決する気がないっていうなら、\n力づくで解決しようじゃないか。",
  ui_story_5046_50461101_40_dialog_content = "ハーティ？",
  ui_story_5046_50461101_41_dialog_content = "クリステン、容疑者を捕まえておきながら、\nなぜ牢に入れないのです？",
  ui_story_5046_50461101_42_dialog_content = "ハーティは容疑者じゃないからだよ。\n影ノ街の数件の放火事件もハーメルさんの死もハーティとは関係ないんだ。",
  ui_story_5046_50461101_43_dialog_content = "…そういうことですか。",
  ui_story_5046_50461101_44_dialog_content = "クリステン、容疑者をかくまっただけでなく、\n容疑者と結託して上司をだまそうとしたのですね！",
  ui_story_5046_50461101_45_dialog_content = "私は…そんなこと…",
  ui_story_5046_50461101_46_dialog_content = "ロケットペンダントを借りるだけなのに、\n反応が激しすぎないかな？",
  ui_story_5046_50461101_47_dialog_content = "まさか、後ろめたいことでもあるの？",
  ui_story_5046_50461101_48_dialog_content = "ハーティの家は昼も夜もロウソクを点けてるのを利用して、\n君はアリバイを作った。しかもクリステンを証人として利用したんだ！",
  ui_story_5046_50461101_49_dialog_content = "当時君はハーティの家で人を殺してから、\nそう離れていないところにあるクリステンの家の別荘に火を放った。",
  ui_story_5046_50461101_50_dialog_content = "それからたまたま通りかかったように見せかけてクリステンを助けて、\n顔のやけどもその時できたように見せかけたんだよ！",
  ui_story_5046_50461101_51_dialog_content = "でも本当はハーティのお母さんと戦った時に、\nハーティのお母さんが君を道連れにしようとして放った火で負ったやけどだ！",
  ui_story_5046_50461101_52_dialog_content = "フン、私を陥れるための作り話ですか？\nそれにしてはよくできています。",
  ui_story_5046_50461101_53_dialog_content = "作り話じゃないよ。今ある情報に基づいて、\n当時の状況を再現してみせただけだ。",
  ui_story_5046_50461101_54_dialog_content = "クリステン、あなたも同じ考えなのですか？",
  ui_story_5046_50461101_55_dialog_content = "先生…私は…",
  ui_story_5046_50461101_56_dialog_content = "PlayerNameさんの推理は…",
  ui_story_5046_50461101_57_dialog_content = "私…",
  ui_story_5046_50461101_58_dialog_content = "…",
  ui_story_5046_50461101_59_dialog_content = "ハハハハハハ！",
  ui_story_5046_50461101_60_dialog_content = "クリステン、あなたという人は本当に素晴らしいお嬢様ですね。",
  ui_story_5046_50461101_61_dialog_content = "師である私よりも、知り合って間もない空の末裔を信じるというのですか？",
  ui_story_5046_50461101_62_dialog_content = "ではなぜ、ロケットペンダントをお貸しくださらないのですか…？",
  ui_story_5046_50461101_63_dialog_content = "ペンダントで疑いは晴れるのですよ…",
  ui_story_5046_50461101_64_dialog_content = "すでに疑っているのでしょう？\nそのような余計なことをする必要がありますか？",
  ui_story_5046_50461101_65_dialog_content = "私が貸そうと貸すまいと、もう結論は出ているのでしょう？",
  ui_story_5046_50461101_66_dialog_content = "違います！いかなる推測も証拠がないうちは…",
  ui_story_5046_50461101_67_dialog_content = "分かりました。もう結構です。",
  ui_story_5046_50461101_68_dialog_content = "これからはもう先生と呼ばないでください。",
  ui_story_5046_50461101_69_dialog_content = "あなたが容疑者側に立つというのなら、\nこの剣もあなたに向けるしかありません。",
  ui_story_5046_50461101_70_dialog_content = "先生…いったい何をなさるおつもりですか？",
  ui_story_5046_50461101_71_dialog_content = "クリステン、自分を信じるんだ！",
  ui_story_5046_50461101_72_dialog_content = "ゼナスは感情に訴えて君を自分側につかせようとしてるんだよ！\n相手が先生であろうとなかろうと、君が守るべきものは正義だ！",
  ui_story_5046_50461101_73_dialog_content = "それでこそ君は君なんだ！\n白夜城の見習い裁判官クリステンなんだよ！",
  ui_story_5046_50461101_74_dialog_content = "私は…",
  ui_story_5046_50461101_75_dialog_content = "衛兵！クリステンは空の末裔と結託し、容疑者ハーティをかばっています。\n全員まとめて捕まえなさい！",
  ui_story_5046_50461101_76_dialog_content = "了解です！",
  ui_story_5046_50461102_1_dialog_content = "はぁ…はぁ…",
  ui_story_5046_50461102_2_dialog_content = "まさか私の衛兵を全員倒してしまうとは…",
  ui_story_5046_50461102_3_dialog_content = "逮捕に抵抗しただけでなく、白夜城衛兵を襲撃した場合、\nどのような法的裁きを受けるかお分かりですか？",
  ui_story_5046_50461102_4_dialog_content = "クリステン、どうです？",
  ui_story_5046_50461102_5_dialog_content = "先生、調査にご協力願います…",
  ui_story_5046_50461102_6_dialog_content = "調査の結果、先生の潔白が証明できれば、\nまた元のように戻れるのです…",
  ui_story_5046_50461102_7_dialog_content = "分かりました。",
  ui_story_5046_50461102_8_dialog_content = "え！？先生、同意してくださるのですか！？",
  ui_story_5046_50461102_9_dialog_content = "（さっきまで絶対に折れようとしなかったのに、\nどうして急に受け入れたんだろう？）",
  ui_story_5046_50461102_10_dialog_content = "ロケットペンダントをさっさと渡せ！",
  ui_story_5046_50461102_11_dialog_content = "母さんの死を…母さんを殺した罪を死んで償え！",
  ui_story_5046_50461102_12_dialog_content = "殺してやる！父さんと母さんの仇だ！",
  ui_story_5046_50461102_13_dialog_content = "落ち着いて、ハーティ！",
  ui_story_5046_50461102_14_dialog_content = "事件はクリステンがきちんと調べてくれるよ。",
  ui_story_5046_50461102_15_dialog_content = "今ここで暴力で解決したら、今度こそ本当に殺人犯になっちゃうよ！",
  ui_story_5046_50461102_16_dialog_content = "僕の知ってるハーティは優しくて心のきれいな、\nお父さんとお母さんに愛されるいい子だよ！",
  ui_story_5046_50461102_17_dialog_content = "お父さんもお母さんも\n君がこんな形で仇を討つことなんて望んでないよ！",
  ui_story_5046_50461102_18_dialog_content = "そうか…父さんも母さんもそんなこと望んでないのか…",
  ui_story_5046_50461102_19_dialog_content = "…そうか。",
  ui_story_5046_50461102_20_dialog_content = "ロケットペンダントはお渡ししましょう。\nただし、影ノ街へ戻り、皆さんの前で潔白を証明します。",
  ui_story_5046_50461102_21_dialog_content = "行きましょう、クリステン。",
  ui_story_5046_50461102_22_dialog_content = "影ノ街に戻り、私の潔白を証明したら、\nまた元のように戻れるのですね…",
  ui_story_5046_50461102_23_dialog_content = "はい…",
  ui_story_5046_50461102_24_dialog_content = "動くな。動けばクリステンの首を折る。",
  ui_story_5046_50461102_25_dialog_content = "先生！？な、何をなさるのです…？",
  ui_story_5046_50461102_26_dialog_content = "何をするの！？早くクリステンを放して！",
  ui_story_5046_50461102_27_dialog_content = "クリステンは容疑者ハーティの追跡中、\n激しい抵抗に遭い、遺憾にも殉職を遂げました。",
  ui_story_5046_50461102_28_dialog_content = "なんてことを！君は正気じゃない！",
  ui_story_5046_50461102_29_dialog_content = "クリステンさえ死ねば、\n今日何が起こったかを知る者は私だけです。",
  ui_story_5046_50461102_30_dialog_content = "私が法廷に報告すれば、\nハーティは極悪非道な放火殺人鬼となり…",
  ui_story_5046_50461102_31_dialog_content = "空の末裔、あなたもその共犯となるのです！",
  ui_story_5046_50461102_32_dialog_content = "そうなれば、あなた方が何を言おうとも誰も信じないでしょう。",
  ui_story_5046_50461102_33_dialog_content = "真実を隠し通せると思ったら大間違いだよ！",
  ui_story_5046_50461102_34_dialog_content = "君だけの力でウソの証言をでっち上げ、\n僕たちを犯人に仕立てあげることなんてできない！",
  ui_story_5046_50461102_35_dialog_content = "真実？真実がどうかなど、重要ですか？",
  ui_story_5046_50461102_36_dialog_content = "重要なのは私が何事もなく、\n引き続き白夜城で騎士であり続けることです…",
  ui_story_5046_50461102_37_dialog_content = "真相には…あなた方のしかばねと共に\n永遠に土の中に眠ってもらいましょう！",
  ui_story_5046_50461102_38_dialog_content = "先生…本気でおっしゃっているのですか？",
  ui_story_5046_50461102_39_dialog_content = "先生はこれまでずっと正義を貫き、真相を明らかにせよと\n教えてくださいました。その先生が、なぜ…なぜ、そんなことを…",
  ui_story_5046_50461102_40_dialog_content = "クリステン、あなたにとって私は大切な存在なのですよね？",
  ui_story_5046_50461102_41_dialog_content = "えっ！？",
  ui_story_5046_50461102_42_dialog_content = "ならば、その大切な私の名誉と地位を守るために\n死ねるのなら、嬉しいのではありませんか？",
  ui_story_5046_50461102_43_dialog_content = "先生…何をおっしゃっているのです…？",
  ui_story_5046_50461102_44_dialog_content = "クリステンは君が何年も前に命の危険を冒して救ったんだよ。\nそんな彼女を殺せるっていうの？",
  ui_story_5046_50461102_45_dialog_content = "（ハーティ！今感知能力で君と話してるんだ！\nなんとかしてクリステンを助けなきゃ！）",
  ui_story_5046_50461102_46_dialog_content = "PlayerName？",
  ui_story_5046_50461102_47_dialog_content = "（僕がゼナスの注意を引くから、\n君は機会を見てゼナスを襲って！）",
  ui_story_5046_50461102_48_dialog_content = "分かった。",
  ui_story_5046_50461102_49_dialog_content = "救う？あの火災のことをおっしゃっているのですか？\nならば、クリステンは今こそ私の恩に報いるべきでしょう。",
  ui_story_5046_50461102_50_dialog_content = "もし僕の推理が間違ってて、当時君はただクリステンを救うために\n命の危険を冒してまで火の海を飛び込んだとしたら…",
  ui_story_5046_50461102_51_dialog_content = "どうしてクリステンを傷つけられるの！？",
  ui_story_5046_50461102_52_dialog_content = "おっしゃる通りです。あの時私が命の危険を冒してまで救い、\n長年宝物のように教え導いて来た少女を…",
  ui_story_5046_50461102_53_dialog_content = "傷つけることなどできましょうか？",
  ui_story_5046_50461102_54_dialog_content = "先生…",
  ui_story_5046_50461102_55_dialog_content = "しかし、クリステン。私のお嬢様。",
  ui_story_5046_50461102_56_dialog_content = "あなたは最初から最後まで、結局私のコマでしかないのです。",
  ui_story_5046_50461102_57_dialog_content = "当時のあの火事も私の計画の1つだったのですよ。",
  ui_story_5046_50461102_58_dialog_content = "え！？",
  ui_story_5046_50461102_59_dialog_content = "権勢のある貴族に取り入り、白夜城に潜り込もうと考えていたところ、\nこの小娘の別荘がちょうど近くにありましてね。",
  ui_story_5046_50461102_60_dialog_content = "あの日別荘にいるのは何の力もない使用人だけだとの情報も手に入れていました。\nそこで使用人を買収し、火を放ったのです。",
  ui_story_5046_50461102_61_dialog_content = "そしてたまたま通りかかったように見せかけて、\n命を賭して白夜城貴族のお嬢様を救い出したというわけです。",
  ui_story_5046_50461102_62_dialog_content = "予想通り、一家はいたく私に感謝し、\n私は無事ずっと夢見ていた白夜城での生活を送ることになったのです。",
  ui_story_5046_50461102_63_dialog_content = "それもこれもあなたのおかげですよ、お嬢様…\nいいえ、クリステン。",
  ui_story_5046_50461102_X63_dialog_content = "ご覧ください。\nあなたを救い出すのに顔にやけどまで負ってしまいました。",
  ui_story_5046_50461102_64_dialog_content = "な、なんて…ひどいことを！絶対に許しません！",
  ui_story_5046_50461102_65_dialog_content = "白夜城で暮らすために顔を犠牲にするなんて、\nそんな価値あるの？",
  ui_story_5046_50461102_66_dialog_content = "空の末裔、あなたに権力の魅力がお分かりになりますか？",
  ui_story_5046_50461102_67_dialog_content = "権力は金銭をもたらしてくれる。\nしかし、金銭で権力を買えるとは限りません。",
  ui_story_5046_50461102_68_dialog_content = "権力さえあれば、すべてを手に入れられるのです！\nすべての者をひざまずかせることができるのですよ！",
  ui_story_5046_50461102_69_dialog_content = "そうでしょう？クリステン？",
  ui_story_5046_50461102_70_dialog_content = "あなたは生まれながらにして白夜城の貴族です。\nずっと権力のもたらす魅惑的な生活を送ってきたのでしょう？",
  ui_story_5046_50461102_71_dialog_content = "冠を戴くものは、必ずその責任の重さをも引き受けなければならない…",
  ui_story_5046_50461102_72_dialog_content = "貴族こそ高潔な品位と徳をそなえていなければなりません。",
  ui_story_5046_50461102_73_dialog_content = "貴族という身分を利用して私利をむさぼる者は\n貴族とは呼べません。",
  ui_story_5046_50461102_74_dialog_content = "ハハハハハハ！",
  ui_story_5046_50461102_75_dialog_content = "クリステン、あなたは本当に優秀な教え子ですね。",
  ui_story_5046_50461102_76_dialog_content = "貴族が全員あなたのように、\n高潔で神聖な白ユリのような存在だと本気で思っているのですか？",
  ui_story_5046_50461102_77_dialog_content = "まあいいとしましょう。少々おしゃべりが過ぎました。",
  ui_story_5046_50461102_78_dialog_content = "むむ！？待て、ハーティはどこです！？",
  ui_story_5046_50461102_79_dialog_content = "…",
  ui_story_5046_50461102_80_dialog_content = "（今だ！ハーティ！）",
  ui_story_5046_50461102_81_dialog_content = "あああああ――！",
  ui_story_5046_50461102_82_dialog_content = "うっ！",
  ui_story_5046_50461102_83_dialog_content = "いつ背後に回り込んだ！？",
  ui_story_5046_50461102_84_dialog_content = "ああ…",
  ui_story_5046_50461102_85_dialog_content = "クリステン！大丈夫！？",
  ui_story_5046_50461102_86_dialog_content = "手を貸してあげるよ。立てる？",
  ui_story_5046_50461102_87_dialog_content = "PlayerNameさん…うう、うううっ…",
  ui_story_5046_50461102_88_dialog_content = "僕のそばへ。",
  ui_story_5046_50461102_89_dialog_content = "もう人質はいない。おとなしくロケットペンダントを渡すんだ。",
  ui_story_5046_50461102_90_dialog_content = "それともまだボクに殴られたいか？",
  ui_story_5046_50461102_91_dialog_content = "分かった…渡そう、ペンダントを渡す。",
  ui_story_5046_50461102_92_dialog_content = "そんなにペンダントが欲しいなら…",
  ui_story_5046_50461102_93_dialog_content = "先に命を渡せ！",
  ui_story_5046_50461102_94_dialog_content = "<color=#e8d9bb>カン――</color>",
  ui_story_5046_50461102_95_dialog_content = "！",
  ui_story_5046_50461102_96_dialog_content = "あっ！",
  ui_story_5046_50461102_97_dialog_content = "ペンダントを渡すふりして、不意打ちをしかけてきたか…",
  ui_story_5046_50461102_98_dialog_content = "もう双方とも武器はない。\nどちらが勝つか分からなくなってきたな。",
  ui_story_5046_50461102_99_dialog_content = "クリステンと空の末裔に戦闘能力はない。\nとなると…",
  ui_story_5046_50461102_100_dialog_content = "私とお前との勝負だな。",
  ui_story_5046_50461102_101_dialog_content = "まずはお前を片付けてから、残りの2人を片付けるとしよう…",
  ui_story_5046_50461102_102_dialog_content = "ハハハハハハ！",
  ui_story_5046_50461102_103_dialog_content = "…",
  ui_story_5046_50461102_104_dialog_content = "それは私の剣！？",
  ui_story_5046_50461102_105_dialog_content = "フン、まあいい、斧も悪くはない。",
  ui_story_5046_50461102_106_dialog_content = "その血で染まった手で剣を握る資格はないよ。",
  ui_story_5046_50461102_X106_dialog_content = "剣は正義の象徴だ。でも、アンタは邪悪だ。",
  ui_story_5046_50461102_107_dialog_content = "「正義は勝つ」とでも本気で思っているのか？",
  ui_story_5046_50461102_108_dialog_content = "もちろんだ。",
  ui_story_5046_50461102_109_dialog_content = "どっちが勝つかなんて、まだ分からないさ。",
  ui_story_5046_50461102_110_dialog_content = "<color=#e8d9bb>カン――</color>",
  ui_story_5046_50461102_111_dialog_content = "くたばるがいい！！",
  ui_story_5046_50461102_112_dialog_content = "ああ！！",
  ui_story_5046_50461102_113_dialog_content = "ああああ！！！",
  ui_story_5046_50461102_114_dialog_content = "<color=#e8d9bb>カタン</color>",
  ui_story_5046_50461102_115_dialog_content = "…",
  ui_story_5046_50461102_116_dialog_content = "自分の剣で首を狙われる気分はどうだ？",
  ui_story_5046_50461102_117_dialog_content = "その首を掻っ切って、\n母さんの仇を討ってやってもいいんだぞ。",
  ui_story_5046_50461102_118_dialog_content = "！",
  ui_story_5046_50461102_119_dialog_content = "でも、そんなことはしない。",
  ui_story_5046_50461102_120_dialog_content = "PlayerNameはそんなこと望んでないからな。",
  ui_story_5046_50461102_121_dialog_content = "父さんも母さんも\nボクの手がアンタの血で汚れることなんて望んでやしない。",
  ui_story_5046_50461102_122_dialog_content = "おい、そこのクリステンとかいうやつ。",
  ui_story_5046_50461102_123_dialog_content = "あ…",
  ui_story_5046_50461102_124_dialog_content = "いつまでメソメソしてんだ。こいつをアンタらに渡す前に\nロケットペンダントをもらってもいいか？",
  ui_story_5046_50461102_125_dialog_content = "ロケットペンダント？何のことだ？\n強盗でもする気か？",
  ui_story_5046_50461102_126_dialog_content = "なぜ、ここまできてまだ罪を認めようとなさらないのです！？",
  ui_story_5046_50461102_127_dialog_content = "何を言ってるのか分かりませんね。",
  ui_story_5046_50461102_128_dialog_content = "先生…いいえ、ゼナス。",
  ui_story_5046_50461102_129_dialog_content = "調査の結果、あなたは何年も前の殺人事件および2件の放火事件と\n関係があることがわかりました。捜査にご協力ください。",
  ui_story_5046_50461102_130_dialog_content = "（クリステン、さっきまで泣いてたのに、\nすぐに落ち着きを取り戻した）",
  ui_story_5046_50461102_131_dialog_content = "フン……",
  ui_story_5046_50461102_132_dialog_content = "相変わらず強情で気の強いお嬢様ですね。",
  ui_story_5046_50461102_133_dialog_content = "今は何もお話ししたくありません。\n何かおっしゃりたいことがあるなら、法廷でお話しください。",
  ui_story_5046_50461102_134_dialog_content = "先程も本気で殺す気などありませんでした。\nあなたは私が救い、長年おそばに仕えた方です。",
  ui_story_5046_50461102_135_dialog_content = "どうして殺せましょう！？",
  ui_story_5046_50461102_136_dialog_content = "なぜ、まだ私をだまそうとなさるのです？",
  ui_story_5046_50461102_137_dialog_content = "何が本当で、何がウソか、見分けることができるのですか？",
  ui_story_5046_50461102_138_dialog_content = "もう結構です！！！",
  ui_story_5046_50461102_139_dialog_content = "あなたのようなペテン師に、\nとやかく指図される筋合いはありません！",
  ui_story_5046_50461102_140_dialog_content = "これから先誰を信じ、誰を信じないかは、\n私自身で判断します。",
  ui_story_5046_50461102_141_dialog_content = "私はもう子どもではありません。\nあなたの教えを必要とする、温室育ちのお嬢様ではないのです。",
  ui_story_5046_50461102_142_dialog_content = "あなたの罪については、法廷が公正な裁きを下すでしょう。",
  ui_story_5046_50461102_143_dialog_content = "申し訳ございません、PlayerNameさん。\nお見苦しいところをお見せしました。",
  ui_story_5046_50461102_144_dialog_content = "私はこれからゼナスを白夜城に連行します。\n判決が下りたら、お二人にお知らせします。",
  ui_story_5046_50461102_145_dialog_content = "ロケットペンダント。",
  ui_story_5046_50461102_146_dialog_content = "ご安心ください。見つけ次第すぐにお届けにあがります。",
  ui_story_5046_50461201_1_dialog_content = "<color=#e8d9bb>数日後――</color>",
  ui_story_5046_50461201_2_dialog_content = "クリステン！",
  ui_story_5046_50461201_3_dialog_content = "こんにちは、PlayerNameさん。",
  ui_story_5046_50461201_4_dialog_content = "ご無沙汰しております、PlayerName殿。",
  ui_story_5046_50461201_5_dialog_content = "ピアタマンも一緒なんだね！",
  ui_story_5046_50461201_6_dialog_content = "ハーティはどちらですか？\n巨像にいるとうかがったのですが。",
  ui_story_5046_50461201_7_dialog_content = "クリステン。",
  ui_story_5046_50461201_8_dialog_content = "どうぞ、ロケットペンダントです。",
  ui_story_5046_50461201_9_dialog_content = "母さんのロケットペンダントだ…",
  ui_story_5046_50461201_10_dialog_content = "今後のゼナスに関する調査と取り調べは私が引き継ぐこととなりました。",
  ui_story_5046_50461201_11_dialog_content = "PlayerName殿のおかげで、\n<color=#FFB400>あの事件</color>の手がかりが見つかりました。",
  ui_story_5046_50461201_12_dialog_content = "あはは…僕は何もしてないよ。",
  ui_story_5046_50461201_13_dialog_content = "まさか僕が人質になったことで、\nこんなにたくさんの事件がつながるとは思ってもなかったし。",
  ui_story_5046_50461201_14_dialog_content = "オ、オホン…",
  ui_story_5046_50461201_15_dialog_content = "それはそうと、いくつか聞きたいことがあるんだ…",
  ui_story_5046_50461201_16_option_content = "この2カ月に起こった放火事件の真犯人は誰だったの？",
  ui_story_5046_50461201_17_dialog_content = "調査の結果、孤児院のリハーサル時に発生した火事も含め、\n影ノ街のこの2か月間の放火事件では同じ燃料が使われていることが分かりました。",
  ui_story_5046_50461201_18_dialog_content = "調べにより、ごく少数の店でしか入手できないことも分かっています。",
  ui_story_5046_50461201_19_dialog_content = "店の主人は2カ月前ゼナスが大量にその燃料を購入したと証言しました。",
  ui_story_5046_50461201_20_dialog_content = "ゼナスも自分がやったと自供しています。\n動機は口封じです。",
  ui_story_5046_50461201_21_dialog_content = "でも、ゼナスはどうしてその人たちの口封じを？",
  ui_story_5046_50461201_22_dialog_content = "それも<color=#FFB400>あの事件</color>と関係があるのです。",
  ui_story_5046_50461201_23_dialog_content = "当時、ハーメル氏を含む5名は孤児院を隠れみのとし、\n子どもたちを実験台として提供する商売をしていました。",
  ui_story_5046_50461201_24_dialog_content = "孤児院が火事になった後、ゼナスとハーメル氏以外の3名は\n苦しい暮らしを強いられていたようです。",
  ui_story_5046_50461201_25_dialog_content = "そこで、3人は過去の事を持ち出し、ゼナスをゆすっていました。\nゼナスも金を渡し、口封じするしかありませんでした。",
  ui_story_5046_50461201_26_dialog_content = "ところが、3人の要求は徐々にエスカレートし…",
  ui_story_5046_50461201_27_dialog_content = "その人たちの口を永遠に封じることにしたんだね。",
  ui_story_5046_50461201_28_dialog_content = "おっしゃる通りです。",
  ui_story_5046_50461201_29_dialog_content = "じゃあ、ハーメルさんは誰に殺されたの？",
  ui_story_5046_50461201_30_dialog_content = "ゼナスは自分が3名の元孤児院職員を放火で殺したと認めています。",
  ui_story_5046_50461201_31_dialog_content = "当時孤児院で働いており、かつ事件と関係した人物は、\nゼナスを含め、5名おりました。",
  ui_story_5046_50461201_32_dialog_content = "つまり、ハーメルさんもゼナスが殺したってこと？",
  ui_story_5046_50461201_33_dialog_content = "その可能性が非常に高いのですが、\n今のところ証拠がなく、本人も認めていません。",
  ui_story_5046_50461201_34_dialog_content = "ゼナスはそんなにたくさんの殺人に関わってたの…？",
  ui_story_5046_50461201_35_dialog_content = "（クリステンの状態、あまりよくないみたいだ…）",
  ui_story_5046_50461201_36_dialog_content = "クリステン、大丈夫？",
  ui_story_5046_50461201_37_dialog_content = "PlayerNameさんは私がそんなに弱い人間だと\n思っていらっしゃるのですか？",
  ui_story_5046_50461201_38_dialog_content = "い、いや、そういう意味じゃないんだ！ただ…",
  ui_story_5046_50461201_39_dialog_content = "私は、大丈夫です。",
  ui_story_5046_50461201_40_dialog_content = "あの日PlayerNameさんがおっしゃったこと、\nすべて覚えています。",
  ui_story_5046_50461201_41_dialog_content = "PlayerNameさんはおっしゃってくださいました。\n私は将来よい裁判官になれる、と。",
  ui_story_5046_50461201_42_dialog_content = "私を励まし、応援してくださる方がこんなにたくさんいるのです。\nたった1人の誰かのためにいつまでも落ち込むことはしません。",
  ui_story_5046_50461201_43_dialog_content = "まだ長い道のりですが、\n自分の努力できっと目標を達成してみせます。",
  ui_story_5046_50461201_44_dialog_content = "何しろ、私は「すごい」のですから！\nそうでしょう？PlayerNameさん？",
  ui_story_5046_50461201_45_dialog_content = "クリステンなら、絶対に大丈夫だよ！",
  ui_story_5046_50461201_46_dialog_content = "ボクも賛成だ。",
  ui_story_5046_50461201_47_dialog_content = "私も同意見です。",
  ui_story_5046_50461201_48_dialog_content = "まあ！私としたことが、先輩がいらしたことを忘れていました…",
  ui_story_5046_50461201_49_dialog_content = "オホン…それではペンダントはお渡ししました。\n私たちはこれで失礼いたしましょう。",
  ui_story_5046_50461201_50_dialog_content = "失礼いたします。",
  ui_story_5046_50461201_51_dialog_content = "…",
  ui_story_5046_50461201_52_dialog_content = "ハーティ、緊張してるの？",
  ui_story_5046_50461201_53_dialog_content = "ああ。",
  ui_story_5046_50461201_54_dialog_content = "この2つのペンダントは対になってるんだ。\nあの日母さんはそのうちの1つをボクにくれた。",
  ui_story_5046_50461201_55_dialog_content = "母さんが言ってた。2つのロケットペンダントが合わさった時、\nボクたち家族は永遠に一緒だって…",
  ui_story_5046_50461201_56_dialog_content = "でも、母さんはもういない。ううっ…",
  ui_story_5046_50461201_57_dialog_content = "母さん…うう、うううっ…",
  ui_story_5046_50461201_58_dialog_content = "いい子だから、泣かないで…",
  ui_story_5046_50461201_59_dialog_content = "（いい子だからハーティ。泣かないで）",
  ui_story_5046_50461201_60_dialog_content = "（母さんがお歌を歌ってあげるわ。\nいい子ね、ハーティ、安心して眠りなさい…）",
  ui_story_5046_50461201_61_dialog_content = "（ラララ～♪ラララ～♪）",
  ui_story_5046_50461201_62_dialog_content = "（ハーティ、あなたのぐっすり眠ってる姿を見てると母さん幸せよ。\n今この瞬間で時が止まればいいのにね）",
  ui_story_5046_50461201_63_dialog_content = "（でも、あなたの大きくなった姿も見たいわ。\nきっとフェンリルにそっくりな大人になるんでしょうね）",
  ui_story_5046_50461201_64_dialog_content = "（生まれたばかりの頃はモコモコとあんなに小さかったのに、\n今じゃ私の膝まで背が届くようになった）",
  ui_story_5046_50461201_65_dialog_content = "（大きくなってもまだ、母さんが抱っこしないと\n寝に行かないし、朝ご飯も食べに来ないわ）",
  ui_story_5046_50461201_66_dialog_content = "（母さん、もう抱っこできなくなってきちゃったわよ）",
  ui_story_5046_50461201_67_dialog_content = "（ねえ、ハーティ。母さんがおばあちゃんになったら、\n今度はあなたが母さんを抱っこしてベッドまで連れて行ってね…）",
  ui_story_5046_50461201_68_dialog_content = "（ハーティ…あなたに話したいことがまだたくさんあるの…）",
  ui_story_5046_50461201_69_dialog_content = "（あなたのことずっと見てたいわ。\nあなたが大きくなっていくのをずっと見守っていたいの…）",
  ui_story_5046_50461201_70_dialog_content = "（…）",
  ui_story_5046_50461201_71_dialog_content = "（…）",
  ui_story_5046_50461201_72_dialog_content = "（…）",
  ui_story_5046_50461201_73_dialog_content = "…",
  ui_story_5046_50461201_74_dialog_content = "もうアンタなんか怖くないよ。この力も…もう怖くない。",
  ui_story_5046_50461201_75_dialog_content = "ボクはありのままの自分を全部受け入れたんだ。",
  ui_story_5046_50461201_76_dialog_content = "これまでの力を恐れ、自分を嫌ってたハーティも…",
  ui_story_5046_50461201_77_dialog_content = "炎で大切な人を守ろうとするハーティも…",
  ui_story_5046_50461201_78_dialog_content = "どっちも、ボクなんだ。",
  ui_story_5046_50461201_79_dialog_content = "（ありのままの自分を…受け入れる準備はできたのか…？）",
  ui_story_5046_50461201_80_dialog_content = "準備はできてる。",
  ui_story_5046_50461202_1_dialog_content = "ボク…勝ったの？",
  ui_story_5046_50461202_2_dialog_content = "アンタは…？",
  ui_story_5046_50461202_3_dialog_content = "（お前はもうありのままの自分を受け入れた）",
  ui_story_5046_50461202_4_dialog_content = "（お前は自分自身と和解したのだ）",
  ui_story_5046_50461202_5_dialog_content = "（これからはこの力もうまく使える。私も嬉しい）",
  ui_story_5046_50461202_6_dialog_content = "（私は、もう行く）",
  ui_story_5046_50461202_7_dialog_content = "炎の力を感じる…！",
  ui_story_5046_50461202_8_dialog_content = "力がどんどんボクの体の中に溶け込んでいく…",
  ui_story_5046_50461202_9_dialog_content = "<color=#e8d9bb>ボン！</color>",
  ui_story_5046_50461202_10_dialog_content = "炎…ボクの思いから生まれた炎…",
  ui_story_5046_50461202_11_dialog_content = "あったかい。",
  ui_story_5046_50461202_12_dialog_content = "PlayerName？",
  ui_story_5046_50461202_13_dialog_content = "目が覚めた？鼻歌を歌ってたら、君が眠っちゃったんだ。",
  ui_story_5046_50461202_14_dialog_content = "ぐっすり気持ちよさそうに寝てたから、起こさなかったんだよ。",
  ui_story_5046_50461202_15_dialog_content = "小さい頃の夢を見た。ボクの不注意で物を燃やしちゃって、\n母さんに怒られて泣いてた。",
  ui_story_5046_50461202_16_dialog_content = "母さんはボクを抱っこしたまま子守歌を歌ってくれた。\nボクをあやして寝かしつけてくれた。",
  ui_story_5046_50461202_17_dialog_content = "眠ってしまうと今度は…",
  ui_story_5046_50461202_18_dialog_content = "心の闇に会った。",
  ui_story_5046_50461202_19_dialog_content = "ボク、あいつに言ったんだ。もう怖くないって。",
  ui_story_5046_50461202_20_dialog_content = "それから？",
  ui_story_5046_50461202_21_dialog_content = "ボクが…勝った。",
  ui_story_5046_50461202_22_dialog_content = "もう炎を恐れない。\nだって、この炎はあったかくボクを包んでくれてるから。",
  ui_story_5046_50461202_23_dialog_content = "父さんと母さんが抱っこしてくれるみたいに。",
  ui_story_5046_50461202_24_dialog_content = "きっと優しい夢だったんだね。",
  ui_story_5046_50461202_25_dialog_content = "すべてのことに立ち向かう勇気が湧いてきたよ。\nそれは父さんと母さんと…",
  ui_story_5046_50461202_26_dialog_content = "アンタがくれた勇気だ、PlayerName。",
  ui_story_5046_50461202_27_dialog_content = "ずっとそばにいてくれて、ありがとう。",
  ui_story_5046_50461202_28_dialog_content = "お礼なんていらないよ！友だちでしょ！",
  ui_story_5046_50461202_29_dialog_content = "ロケットペンダントを合わせてみようと思うんだ。\nPlayerName、一緒にいてくれるか？",
  ui_story_5046_50461202_30_dialog_content = "うん！一緒に合わせよう！",
  ui_story_5046_50461202_31_dialog_content = "<color=#e8d9bb>カチッ――</color>",
  ui_story_5046_50461202_32_dialog_content = "ペンダントを合わせたら、何か出て来たみたいだ…",
  ui_story_5046_50461202_33_dialog_content = "<color=#e8d9bb>パラ…</color>",
  ui_story_5046_50461202_34_dialog_content = "こ、これは…",
  ui_story_5046_50461202_35_dialog_content = "写真がたくさん…",
  ui_story_5046_50461202_36_dialog_content = "これは…ボクが小さい時に描いた家族の絵だ。",
  ui_story_5046_50461202_37_dialog_content = "母さん、ペンダントの中に入れててくれたんだね。",
  ui_story_5046_50461202_38_dialog_content = "君の小さい頃の写真もあるよ！",
  ui_story_5046_50461202_39_dialog_content = "他にも写真が2枚ある…",
  ui_story_5046_50461202_40_dialog_content = "これはきっとハーティのお母さんだね。\nこっちは…",
  ui_story_5046_50461202_41_dialog_content = "父さん…",
  ui_story_5046_50461202_42_dialog_content = "え？ハーティのお父さん？",
  ui_story_5046_50461202_43_dialog_content = "でも、この写真の背景は実験室じゃないの…？",
  ui_story_5046_50461202_44_dialog_content = "ボクは…",
  ui_story_5046_50461202_45_dialog_content = "父さんに会ったことはない。",
  ui_story_5046_50461202_46_dialog_content = "でも、これは父さんだって分かる…",
  ui_story_5046_50461202_47_dialog_content = "「2つのロケットペンダントが合わさった時、\n私たち家族は永遠に一緒になれる…」",
  ui_story_5046_50461202_48_dialog_content = "ボクたち家族は永遠に一緒だ。",
  ui_story_5046_50461202_49_dialog_content = "<color=#e8d9bb>影ノ街某所</color>",
  ui_story_5046_50461202_50_dialog_content = "手紙をゼナスに渡し、後を付けました。",
  ui_story_5046_50461202_51_dialog_content = "あなたたちは引き続きこの一帯を捜索してください。\n隅々まで探すのですよ。",
  ui_story_5046_50461202_52_dialog_content = "了解です！",
  ui_story_5046_50461202_53_dialog_content = "…",
  ui_story_5046_50461202_54_dialog_content = "（この方向は…孤児院へ向かうつもりでしょうか？）",
  ui_story_5046_50461202_55_dialog_content = "お久しぶりですね。",
  ui_story_5046_50461202_56_dialog_content = "あんたか。",
  ui_story_5046_50461202_57_dialog_content = "（ハーメル？まさかシャドウマスターが必要としてるものを彼が？）",
  ui_story_5046_50461202_58_dialog_content = "私に会えて、嬉しくないのですか？",
  ui_story_5046_50461202_59_dialog_content = "おそらく、私に会いに来たのではあるまい。\nアレを取りに来たのだろう？",
  ui_story_5046_50461202_60_dialog_content = "ずいぶん他人行儀ですね。今日はいい知らせをもってきたのですよ。",
  ui_story_5046_50461202_61_dialog_content = "やつに呼び出されたのはあんただろう？\n私と何の関係がある？",
  ui_story_5046_50461202_62_dialog_content = "アンドレアスも他の2人も死にました。\nそのうち私とあなたの番が回ってくるでしょう。",
  ui_story_5046_50461202_63_dialog_content = "座して待つより、こちらから攻撃に出てはどうでしょう？",
  ui_story_5046_50461202_64_dialog_content = "（ハーメルの目線がさっきからずっと向こうに行ってますね）",
  ui_story_5046_50461202_65_dialog_content = "何をお聞きになりたかは分かっていますよ。\nなぜ私が手を下さないのか、でしょう？",
  ui_story_5046_50461202_66_dialog_content = "この手紙は私を名指しし、呼び出しています。\nもし私と彼女とのつながりを知られ、そのまま他のことまで調べられては大変です。",
  ui_story_5046_50461202_67_dialog_content = "そうなれば、あなたに便宜を図ることはできませんし、\nあなたまで調べが及ぶかどうかも定かではありません。",
  ui_story_5046_50461202_68_dialog_content = "私を脅す気か…",
  ui_story_5046_50461202_69_dialog_content = "互いに利益があると言っているだけですよ。\n…これが住所です。",
  ui_story_5046_50461202_70_dialog_content = "いいだろう。面倒は私が片付けてやる。\nその代わり人手を貸してもらいたい。",
  ui_story_5046_50461202_71_dialog_content = "ゼナスが立ち去った後、\nハーメルが熟睡している隙に探してみたところ、アレを見つけました。",
  ui_story_5046_50461202_72_dialog_content = "そこには取引の日時と値段、それから買い手の情報が書かれてました。",
  ui_story_5046_50461202_73_dialog_content = "よくやった。",
  ui_story_5046_50461202_74_dialog_content = "何年も前影ノ街は混乱の極みにあり、まとめ役もいなかった。\n白夜城はここをやつらの罪悪を隠す所としていた。",
  ui_story_5046_50461202_75_dialog_content = "俺が影ノ街の守護者となった今、この街が元の姿に戻ることはない。",
  ui_story_5046_50461202_76_dialog_content = "影はすべてを知っている。",
  ui_story_5046_50461202_77_dialog_content = "はい、シャドウマスター。",
  ui_story_5046_50461202_78_dialog_content = "ご苦労だったな。",
  ui_story_5046_50461202_79_dialog_content = "<color=#e8d9bb>白夜城監獄</color>",
  ui_story_5046_50461202_80_dialog_content = "…",
  ui_story_5046_50461202_81_dialog_content = "お嬢様でしたか。",
  ui_story_5046_50461202_82_dialog_content = "このようなジメジメと陰うつな所にお嬢様がいらしてはなりません。",
  ui_story_5046_50461202_83_dialog_content = "あなたと、私自身の過去とお別れしたくて来ました。",
  ui_story_5046_50461202_84_dialog_content = "今まで私はずっとあなたの言う通りにしてきました。\n考え方も行いもすべてあなたの思う通りに…",
  ui_story_5046_50461202_85_dialog_content = "…あなたの人形も同然でした。",
  ui_story_5046_50461202_86_dialog_content = "お嬢様。私は一度たりともあなたに何をするべきか、\n何を考えるべきか、強制したことはありませんよ。",
  ui_story_5046_50461202_87_dialog_content = "自分でそうなるよう仕向けておきながら、無関係のような顔をして、\nあなたのその態度には反吐が出ます。",
  ui_story_5046_50461202_88_dialog_content = "本当に救いようのないクズです！",
  ui_story_5046_50461202_89_dialog_content = "…",
  ui_story_5046_50461202_90_dialog_content = "取り乱しました。申し訳ありません。",
  ui_story_5046_50461202_91_dialog_content = "ロケットペンダント。",
  ui_story_5046_50461202_92_dialog_content = "あのロケットペンダントの中には、いったい何が入っていたのですか？",
  ui_story_5046_50461202_93_dialog_content = "聞きたいことはそれだけですか？",
  ui_story_5046_50461202_94_dialog_content = "…",
  ui_story_5046_50461202_95_dialog_content = "あのロケットペンダントのために、\n多くの犠牲を払ってきました。",
  ui_story_5046_50461202_96_dialog_content = "あの中には…私の考えている物が入っていたのか、\n知りたいのです。",
  ui_story_5046_50461202_97_dialog_content = "中にはハーティたち家族の写真が入っていました。",
  ui_story_5046_50461202_98_dialog_content = "家族の写真だけですか？",
  ui_story_5046_50461202_99_dialog_content = "ええ、それだけです。",
  ui_story_5046_50461202_100_dialog_content = "ハハハハハハ！！！",
  ui_story_5046_50461202_101_dialog_content = "まったく予想外ですね…",
  ui_story_5046_50461202_102_dialog_content = "こんな結末が待っていたとは…\n実に予想外でしたよ…",
  ui_story_5046_50461202_103_dialog_content = "他に何もおっしゃることがないようなら…",
  ui_story_5046_50461202_104_dialog_content = "私はこれで失礼します。",
  ui_story_5046_50461202_105_dialog_content = "…",
  ui_story_5046_50461202_106_dialog_content = "あなたに会うのは、これが最後です。",
  ui_story_5046_50461202_107_dialog_content = "さようなら、先生。",
  ui_story_5046_50461202_108_dialog_content = "（さようなら、私の過去…）",
  ui_story_5046_50461202_109_dialog_content = "<color=#e8d9bb>影ノ街孤児院竣工式当日</color>",
  ui_story_5046_50461202_110_dialog_content = "この孤児院は影ノ街の心ある方々の強い思いのおかげで、\n今日こうして再建がかないました。謹んでお礼申し上げます。",
  ui_story_5046_50461202_111_dialog_content = "それでは、ここに影ノ街孤児院の竣工を宣言いたします！",
  ui_story_5046_50461202_112_dialog_content = "おめでとう！",
  ui_story_5046_50461202_113_dialog_content = "無事完成して本当によかった！",
  ui_story_5046_50461202_114_dialog_content = "孤児院がきちんと運営されることを願ってるよ。\n昔みたいなことは二度と起こってほしくない。",
  ui_story_5046_50461202_115_dialog_content = "孤児院は影ノ街のシャドウマスターが管理監督しますんで、\nご安心ください。",
  ui_story_5046_50461202_116_dialog_content = "グリム！？",
  ui_story_5046_50461202_117_dialog_content = "ゼナスが捕まった日、ハーティと一緒にバーに行ったけど、\n留守だった…",
  ui_story_5046_50461202_118_dialog_content = "少し用がありましてね。外出してたんです。",
  ui_story_5046_50461202_119_dialog_content = "それはそうと、ハーティはどうしたんです？",
  ui_story_5046_50461202_120_dialog_content = "ハーティは…",
  ui_story_5046_50461202_121_dialog_content = "続いて、この孤児院を火事から救った英雄、\nハーティに登場していただきましょう！",
  ui_story_5046_50461202_122_dialog_content = "…",
  ui_story_5046_50461202_123_dialog_content = "ハーティはここ2カ月影ノ街で起こった複数の火事現場で、\n勇敢にも救助に努め――",
  ui_story_5046_50461202_124_dialog_content = "数日前この竣工式のリハーサル会場で起こった火事でも、\n1人の少女が火の中に閉じ込められ…",
  ui_story_5046_50461202_125_dialog_content = "ハーティは危険も顧みず、火の海の中に飛び込み、\nその少女を救出しました…",
  ui_story_5046_50461202_126_dialog_content = "なんだ、あの子は放火犯じゃなかったのか…",
  ui_story_5046_50461202_127_dialog_content = "現場に姿を現したのは、救助のためだったのか？",
  ui_story_5046_50461202_128_dialog_content = "勇敢な子だな。まさに英雄じゃないか…",
  ui_story_5046_50461202_129_dialog_content = "さすがベセルさん、気遣いが行き届いてますね。\nこれで影ノ街の住人もハーティを放火犯だなんて言わなくなります。",
  ui_story_5046_50461202_130_dialog_content = "そうだね。僕だったらいくら考えても、\nこんな風にうまくはやれないよ。",
  ui_story_5046_50461202_131_dialog_content = "フフ…PlayerNameさんにはPlayerNameさんのいいところがありますよ。\n誰だって完璧じゃありません。",
  ui_story_5046_50461202_132_dialog_content = "面倒くさ。",
  ui_story_5046_50461202_133_dialog_content = "あれ…もう下りてきちゃったの？",
  ui_story_5046_50461202_134_dialog_content = "あのまま壇上にいたら、全身鳥肌が立っちまうよ。",
  ui_story_5046_50461202_135_dialog_content = "慣れればなんてことありませんよ。\nまだ外の世界に触れて間もないですからね。これから色々と学ばなければ。",
  ui_story_5046_50461202_136_dialog_content = "うう…",
  ui_story_5046_50461202_137_dialog_content = "ハーティ、これからどうするつもりですか？",
  ui_story_5046_50461202_138_dialog_content = "そうだな…",
  ui_story_5046_50461202_139_dialog_content = "まだ分からない。",
  ui_story_5046_50461202_140_dialog_content = "今までは母さんとの記憶を思い出すことが目標だった。",
  ui_story_5046_50461202_141_dialog_content = "でも、その目標はもうかなえた…",
  ui_story_5046_50461202_142_dialog_content = "他に何ができるのか、分からないんだ。",
  ui_story_5046_50461202_143_dialog_content = "それでいいんだよ。人生はそうやって、\n一つ一つ目標をかなえながら進んでいくんだ！",
  ui_story_5046_50461202_144_dialog_content = "次の目標が見つかるまで、休憩時間も必要だよ。",
  ui_story_5046_50461202_145_dialog_content = "だって、一つ目の目標をかなえるために、\nハーティは全力を尽くしたんだから。",
  ui_story_5046_50461202_146_dialog_content = "次の目標か…",
  ui_story_5046_50461202_147_dialog_content = "それが何なのか、分からないよ。",
  ui_story_5046_50461202_148_dialog_content = "いつか必ず見つかるよ。",
  ui_story_5046_50461202_149_dialog_content = "君の人生は始まったばかりだよ！",
  ui_story_5046_50461202_150_dialog_content = "前に話したみたいに、この世界には\n僕たちのまだ知らないことがたくさん存在してるんだ。",
  ui_story_5046_50461202_151_dialog_content = "次の目標が見つかるまでの時間、ゆっくりと休むといいよ！",
  ui_story_5046_50461202_152_dialog_content = "ああ。",
  ui_story_5046_50461202_153_dialog_content = "ありがとう、PlayerName。",
  ui_story_5046_50461202_154_dialog_content = "それよりも、この先また急に頭が痛くなったりしないか心配だよ…",
  ui_story_5046_50461202_155_dialog_content = "君とそっくりな犬がまた君に何か話しかけるんじゃないかって…",
  ui_story_5046_50461202_156_dialog_content = "もう心配いらないよ。",
  ui_story_5046_50461202_157_dialog_content = "和解したんだ。",
  ui_story_5046_50461202_158_dialog_content = "今、ボクたちは一つなんだ。",
  ui_story_5046_50461202_159_dialog_content = "うわあっ――！",
  ui_story_5046_50461202_160_dialog_content = "あ、あの犬と瓜二つだ！",
  ui_story_5046_50461202_161_dialog_content = "ああ。",
  ui_story_5046_50461202_162_dialog_content = "でも、怖がることないよ。",
  ui_story_5046_50461202_163_dialog_content = "ボクはもうこの力をちゃんと制御できるんだ…",
  ui_story_5046_50461202_164_dialog_content = "炎の力をね。",
  ui_story_5046_50461202_165_dialog_content = "お兄ちゃん！",
  ui_story_5046_50461202_166_dialog_content = "君は…",
  ui_story_5046_50461202_167_dialog_content = "君は…あの時の？",
  ui_story_5046_50461202_168_dialog_content = "あたしたちをたすけてくれたワンちゃんに、\nお花のかんむり、作ったの！",
  ui_story_5046_50461202_169_dialog_content = "ワンちゃんどこにいるか知ってる？",
  ui_story_5046_50461202_170_dialog_content = "ワンちゃんは…",
  ui_story_5046_50461202_171_dialog_content = "ここだよ。",
  ui_story_5046_50461202_172_dialog_content = "うわぁああ――！",
  ui_story_5046_50461202_173_dialog_content = "この姿、そんなに怖いか？",
  ui_story_5046_50461202_174_dialog_content = "おっきいワンちゃんだね！",
  ui_story_5046_50461202_175_dialog_content = "カッコいい！",
  ui_story_5046_50461202_176_dialog_content = "…",
  ui_story_5046_50461202_177_dialog_content = "ホントにあの日たすけてくれたワンちゃん？",
  ui_story_5046_50461202_178_dialog_content = "ああ。",
  ui_story_5046_50461202_179_dialog_content = "あ！わかった！",
  ui_story_5046_50461202_180_dialog_content = "ワンちゃんはいろんな所でみんなをたすけてるから、\nどんどん強くなってるんだ！",
  ui_story_5046_50461202_181_dialog_content = "それで、おっきなワンちゃんになったんだね！",
  ui_story_5046_50461202_182_dialog_content = "アハハ…",
  ui_story_5046_50461202_183_dialog_content = "ワンちゃん！あたしのヒーロー！",
  ui_story_5046_50461202_184_dialog_content = "よいしょ…よいしょ…",
  ui_story_5046_50461202_185_dialog_content = "ううっ…とどかない…",
  ui_story_5046_50461202_186_dialog_content = "ワンちゃんにお花の冠をかぶらせてあげたいの？",
  ui_story_5046_50461202_187_dialog_content = "うん！",
  ui_story_5046_50461202_188_dialog_content = "ボクがかがむよ。",
  ui_story_5046_50461202_189_dialog_content = "はい、できた！",
  ui_story_5046_50461202_190_dialog_content = "たすけてくれて、ありがとう！",
  ui_story_5046_50461202_191_dialog_content = "このお花はね、保育士のお姉ちゃんにナイショでつんできたんだ…",
  ui_story_5046_50461202_192_dialog_content = "ひとりで勝手に出歩いちゃダメだよ！",
  ui_story_5046_50461202_193_dialog_content = "で、でも…ワンちゃんはあたしをたすけてくれたから…",
  ui_story_5046_50461202_194_dialog_content = "なにかプレゼントしなきゃでしょ！",
  ui_story_5046_50461202_195_dialog_content = "無事ならそれでいいんだ。",
  ui_story_5046_50461202_196_dialog_content = "プレゼントはいらないよ。",
  ui_story_5046_50461202_197_dialog_content = "ダメ！",
  ui_story_5046_50461202_198_dialog_content = "孤児院では、ほかの子をたすけた子は\n保育士のお姉ちゃんからごほうびをもらえるんだよ！",
  ui_story_5046_50461202_199_dialog_content = "ワンちゃんはあたしをたすけてくれたから、\nごほうびをもらわなくちゃいけないの！",
  ui_story_5046_50461202_200_dialog_content = "でも、あたしは、なにも持ってないから…",
  ui_story_5046_50461202_201_dialog_content = "…",
  ui_story_5046_50461202_202_dialog_content = "「ありがとう」の一言で十分だ。",
  ui_story_5046_50461202_203_dialog_content = "なにをプレゼントしたらいいか、考えてたらね…",
  ui_story_5046_50461202_204_dialog_content = "窓の外から、お花がとんできたの！",
  ui_story_5046_50461202_205_dialog_content = "あの日突然あらわれて、あたしをたすけてくれたワンちゃんみたいに！",
  ui_story_5046_50461202_206_dialog_content = "だから、お花のかんむりを作ったの。\nワンちゃんが楽しい気持ちになればいいなって…",
  ui_story_5046_50461202_207_dialog_content = "お花のかんむり、気に入った？",
  ui_story_5046_50461202_208_dialog_content = "ああ…",
  ui_story_5046_50461202_209_dialog_content = "気に入ったよ。",
  ui_story_5046_50461202_210_dialog_content = "ありがとう。",
  ui_story_5046_50461202_211_dialog_content = "みんな、ありがとう。"
}
return config
